  str_mission_desc_4001010 = "คุณลองใช้พลังจิตเป็นครั้งแรกในรอบ 17 ปี สาวน้อยข้างหน้าคุณคนนี้เป็นโอกาสให้คุณออกไปจากที่นี่หรือเปล่านะ?",
  str_mission_desc_4001020 = "คุณไม่เคยเห็นคนมาก่อนแต่ตอนนี้คุณมีเพื่อนแล้ว",
  str_mission_desc_4001030 = "หรือว่าโคลอสซัสพร้อมที่จะเปิดใช้งานแล้วนะ?",
  str_mission_desc_4001040 = "ออโรเรียนจะไม่หยุดสู้ตราบใดที่ยังมีแสงสว่าง",
  str_mission_desc_4001041 = "อิคลิพไซท์มีมาไม่หยุดไม่หย่อน หากเริ่มจะรับมือไม่ได้ ก็ควรลองหาทางอื่นดีกว่า",
