  str_mission_desc_4001045 = "ทดสอบ",
  str_mission_desc_4001046 = "ทดสอบ",
  str_mission_desc_4001047 = "ทดสอบ",
  str_mission_desc_4001050 = "คุณคิดอะไรได้ชัดเจนกว่าหากมีมิสบลังค์ชี้แนะวิธีไปยังจุดหมาย",
  str_mission_desc_4001051 = "คุณสู้ในสมรภูมิรบได้ง่ายขึ้นกว่าแต่ก่อน ออโรเรียนและคุณเข้ากันได้ค่อนข้างดีแล้ว",
  str_mission_desc_4001060 = "การต่อสู้ของคุณยากขึ้น พิสูจน์ให้เห็นว่าออโรเรียนและคุณเติบโตขึ้น",
  str_mission_desc_4001070 = "ในช่วงเวลาสำคัญ พื้นก็เริ่มสั่นและมีอะไรบางอย่างปรากฏออกมา",
  str_mission_desc_4001080 = "โซรอซยังบินไม่ได้ในตอนนี้ ก่อนมันจะใช้ได้คุณก็ต้องสู้กับอิคลิพไซท์นับไม่ถ้วน",
  str_mission_desc_4001090 = "พบเห็นอิคลิพไซท์ในทุกพื้นที่ของโคลอสซัส ป้องกันให้ถึงที่สุด!",
  str_mission_desc_4001100 = "อิคลิพไซท์ที่เพิ่มจำนวนขึ้นได้รุกรานส่วนสำคัญของโคลอสซัส ซึ่งก็คือห้องบังคับการ",
  str_mission_desc_4001101 = "มีภาวะวิกฤติที่ยังไม่ชัดเจนเกิดขึ้นรอบตัวคุณ",
  str_mission_desc_4001110 = "ถ้าจำนวนพลไม่ชนะ ก็ต้องใช้แผนล่อหลอก",
  str_mission_desc_4001120 = "คุณต้องไปจากที่นี่พร้อมสหายทุกคน!",
  str_mission_desc_4001130 = "โคลอสซัสพุ่งออกไปพร้อมกับเสียงคำรามของเครื่องยนต์ อย่างไรก็ดี คู่ปรับที่แข็งแกร่งกว่าอย่างคราเคนก็เดินออกมาจากเงามืด",
  str_mission_desc_4002015 = "การเสียสละของสหายและข่าวที่คาดไม่ถึง...ทั้งหมดนี้ดูจะสร้างเงามืดไปตามทางข้างหน้า จากนี้ไปทุกอย่างจะเป็นอย่างไรกันนะ",
  str_mission_desc_4002010 = "โซรอสเกิดขัดข้องและตกลงไปในดินแดนรกร้าง",
  str_mission_desc_4002035 = "ทดสอบ",
  str_mission_desc_4002020 = "คุณต้องบัญชาการกลุ่มคนขี้โม้ในคราวนี้...",
  str_mission_desc_4002030 = "เรดีเซล เวรนช์แข็งแกร่งโดยไม่มีข้อสงสัย แต่อิคลิพไซท์ไล่ต้อนจนมาถึงทางตัน",
  str_mission_desc_4002031 = "เดี๋ยวนะ! กำลังเสริมของอิลลูมินาอาจกำลังมา ต้องอดทนไว้ก่อน",
  str_mission_desc_4002040 = "ดูจากความเป็นไปได้ในการต่อสู้และอาการบาดเจ็บของไวซ์แล้ว พวกเรดีเซล เวรนช์ดันให้คุณจนมุม",
  str_mission_desc_4002050 = "สถานการณ์ไม่สู้ดีเท่าไรนัก พวกอิคลิพไซท์เหมือนจะมุ่งหน้าไปหาโคลอสซัส",
  str_mission_desc_4002060 = "ในขณะที่ทุกคนเดาว่าอิคลิพไซท์ระดับสูงควบคุมอยู่หรือไม่ อิคลิพไซท์ใหม่อย่างอัมบราฮัลก์ก็ปรากฏตัวขึ้น",
  str_mission_desc_4002070 = "อิคลิพไซท์คุกคามประชากรเมืองใต้ดินตามบัญชาของโนซาร์ด เพื่อเก็บแรงเอาไว้ คุณไม่มีทางเลือกอื่นนอกจากถอยทัพ!",
  str_mission_desc_4002080 = "คุณถูกอิคลิพไซท์โจมตีโดยไม่ทันตั้งตัว แต่โชคดีที่ยังไม่สายเกินไป",
  str_mission_desc_4002090 = "อิคลิพไซท์ยึดเมืองใต้ดินแล้ว ถึงจุดจบแล้วหรือไง?",
  str_mission_desc_4002100 = "เมืองใต้ดินหมายเลข 28 สลายแล้วและคารอนออกคำสั่งสุดท้ายให้สังหารศัตรูพร้อมกันทุกคน",
  str_mission_desc_4002101 = "ให้ประชากรและผู้บาดเจ็บขึ้นโคลอสซัสเลย! ยังไม่ถึงเวลาให้ผ่อนคลาย!",
  str_mission_desc_4002110 = "ภาระอันหนักหน่วงที่เพิ่มขึ้นตกอยู่ที่คุณ เพื่อน หัวหน้าและประชากร...จะเลือกทางไหนดีนะ?",
  str_mission_desc_4002120 = "เมื่อถูกล้อม คารอนแผดเสียงร้องดังก้องหูให้คุณ \nหนีไป เขาจะตายไปพร้อมกับเมืองใต้ดินหมายเลข 28 เอง",
  str_mission_desc_4003010 = "ด้วยการช่วยเหลือของไวซ์และโซรอซ การค้นหาผู้คนของคุณดูจะเป็นไปด้วยดี",
  str_mission_desc_4003020 = "หนึ่งในผู้คนขอให้คุณช่วย เขาบังเอิญพบเจอภัยอันตรายเข้างั้นเหรอ?!",
  str_mission_desc_4003030 = "เหมือนคุณถูกต่อยหน้าเข้าอย่างจัง มีร่องรอยของอิคลิพไซท์เต็มไปหมดทุกที่",
  str_mission_desc_4003031 = "สัญญาณฟังไม่ค่อยชัดเท่าไร \"เขาคนนั้น\" กำลังถูกไล่ล่า คุณต้องรีบแล้ว",
  str_mission_desc_4003040 = "เส้นทางที่นำไปยังเรลิกขรุขระและลาดชัน อิคลิพไซท์ได้เปรียบเสียนี่กระไร",
  str_mission_desc_4003050 = "อิคลิพไซท์หลั่งไหลเข้ามามหาศาล ใครอยู่เบื้องหลังเหตุการณ์นี้กันนะ",
  str_mission_desc_4003060 = "คุณพบเขาแล้ว! แต่เขาถูก\nศัตรูที่กลายเป็นคนทรยศไล่ล่า",
  str_mission_desc_4003070 = "ไม่มีใครบอกได้ว่าศัตรูแข็งแกร่งแค่ไหน ถึงอย่างนั้นก็เถอะ...คงถอยหลังไม่ได้แล้ว",
  str_mission_desc_4003080 = "ชูมเมอร์ได้โมดูลคลังปัญญาไปครองแล้ว สายเกินไปเสียแล้ว...แต่คุณก็ไม่ควรหนีนะ!",
  str_mission_desc_4003090 = "เมนเดลสันอ่อนแอลงเรื่อย ๆ แต่คุณมุ่งไปข้างหน้าโดยไม่ลังเล",
  str_mission_desc_4003091 = "คุณเข้าใกล้เป้าหมายเข้าไปทุกที ได้กลิ่นศัตรูไหม?",
  str_mission_desc_4003100 = "อากาศคละคลุ้งไปด้วยความไม่แน่นอน หมอกหนาปกคลุมขยายสู่ความมืดมิด",
  str_mission_desc_4003110 = "พลังงานมืดครอบงำร่างกายเมนเดลสันทีละน้อย ร่างกายของเขาดูช่างเปราะบางเหลือเกิน!",
  str_mission_desc_4003120 = "คุณได้ยินเสียงคุยกันโหวกเหวกในหมู่อิคลิพไซท์ระดับสูงในความมืดและระส่ำระสายโดยรอบ การทดสอบสุดท้ายอยู่ข้างหน้าแล้ว",
  str_mission_desc_4004010 = "บริเวณตะวันออกของลูโมโพลิสชั้นล่างถูกอิคลิพไซท์บุกรุก เวลาเป็นสิ่งสำคัญและคุณต้องชนะให้ได้",
  str_mission_desc_4004020 = "พบอิคลิพไซท์ในบริเวณตะวันตก! ตัวที่หนีไปได้เรียกปิศาจมาทุกที่",
  str_mission_desc_4004030 = "จำนวนอิคลิพไซท์เยอะกว่าที่คุณคิด การอพยพและลี้ภัยมาก่อนสิ่งใด\nสำหรับชาวเมือง",
  str_mission_desc_4004031 = "หน่วยผู้พิทักษ์กวาดล้างเศษซากอิคลิพไซท์ทีละตัว ไม่มีตัวไหนที่\nรอดจากการล่าของพวกเขาได้",
  str_mission_desc_4004040 = "ในพื้นที่ตะวันตกห่างไกล อิคลิพไซท์ที่ถูกอัญเชิญมารอคอย\nมาเนิ่นนานแล้ว",
  str_mission_desc_4004050 = "การที่อิคลิพไซท์โจมตีครั้งแล้วครั้งเล่า อาจเป็นแค่ฉากหน้าก็ได้",
  str_mission_desc_4004060 = "เชลต์ตัดสินใจทุ่มทุกอย่างในฝั่งของเธอ เธอปลุกน้องสาวที่กลายเป็นอิคลิพไซท์",
  str_mission_desc_4004070 = "มุ่งหน้าตามรอยพี่น้องอิคลิพไซท์แล้วกำจัดศัตรูที่ประมาทเลินเล่อ",
  str_mission_desc_4004080 = "พี่น้องอิคลิพไซท์ไม่ได้บุ่มบ่ามโดยไม่วางแผน พวกเขาอัญเชิญอิคลิพไซท์มาอย่างไม่หยุดหย่อน",
  str_mission_desc_4004090 = "ใกล้เข้าไปแล้วสิ คุณเกือบจะจับหัวโจกที่วางแผนก่อเหตุวุ่นวายนี้ได้แล้ว",
  str_mission_desc_4004091 = "กำจัดพวกมันให้หมด อย่าไว้ชีวิตใครทั้งนั้น",
  str_mission_desc_4004100 = "ชายน่าสงสัยคนนั้นไปไหน หมอนั่นเป็นใครกัน",
  str_mission_desc_4004110 = "เลือดของพี่น้องอิคลิพไซท์ทำให้เมืองนี้เปื้อนมลทิน พวกมันไม่มีทางหันหลังกลับแล้ว",
  str_mission_desc_4004120 = "ได้เวลาสอบสวนพี่น้องแล้ว ศัตรูที่สิ้นหวังนี้จะขัดขืนยังไงกันนะ",
  str_mission_desc_4005010 = "จำนวนโคลอสซัสที่ร่วงหล่นชี้ให้เห็นถึงจำนวนเคเลสไทต์ที่สละชีพไป เช่นเดียวกับจำนวนอิคลิพไซท์ที่มือเปื้อนเลือด...",
  str_mission_desc_4005020 = "ภายในโคลอสซัสที่ร่วงหล่นนั้นเสียหายอย่างมาก เส้นทางไปยังยูนิตเติบโตอิสระขรุขระและวุ่นวาย",
  str_mission_desc_4005030 = "มีอันตรายโผล่มาในเรลิก อิคลิพไซท์ปรากฏตัวออกมาจากเงามืด",
  str_mission_desc_4005031 = "เร่งฝีเท้าอคิลลีสเป็นสิ่งสำคัญที่จะรอดพ้นอันตรายไปได้",
  str_mission_desc_4005040 = "ระวังตัวไว้เสมอ คุณอาจบาดเจ็บเพราะอิคลิพไซท์ได้เหมือนกับดักที่ไม่อาจสังเกตเห็นได้",
  str_mission_desc_4005050 = "เหยื่อล่อที่ดีสามารถหลบหนีตามที่ขยับได้อย่างปราศจากอันตราย",
  str_mission_desc_4005060 = "เสียงเพลงศาสนาบรรเลงขึ้นมาเบา ๆ โคลอสซัสเริ่มเปล่งประกายอีกครั้งจากการพักของมัน นี่เป็นของขวัญสุดท้าย ประชาชนของข้า",
  str_mission_desc_4005070 = "โอกาสที่มาในโคลอสซัสทำให้คุณคิดหนัก ตอนนี้จำเป็นต้องมีหนทางแก้ไข",
  str_mission_desc_4005080 = "ทหารไล่ตามมากขึ้นเรื่อย ๆ ราวกับแมลงวันที่น่ารำคาญ",
  str_mission_desc_4005090 = "เหลืออีกแค่ 5 นาทีก่อนถึงเส้นตาย คุณจะตัดสินใจอย่างไร?",
  str_mission_desc_4005091 = "หลบหนีอย่างระมัดระวังและกลยุทธ์ใจกล้าเป็นสิ่งสำคัญ",
  str_mission_desc_4005100 = "จงเป็นฝ่ายรุกก่อน อย่านั่งรอคอย",
  str_mission_desc_4005110 = "ทุกอย่างล้วนมีทางออก เพียงแต่คุณต้องรู้จักพลิกแพลง",
  str_mission_desc_4005120 = "การนับถอยหลังจะสิ้นสุดลงแล้ว การโจมตีแบบไม่ทันตั้งตัวจะพลิกสถานการณ์ได้ไหมนะ ได้เวลาปล่อยท่าไม้ตายใส่ชูมเมอร์แล้ว!",
  str_mission_desc_4006010 = "เมื่อไล่ตามโมดูลควบคุมไฟในระเบียงเสียงกระซิบ คุณจะพบรอยรองเท้าบูททหาร ต้องเป็นของคนทรยศอย่างเกิร์ตเซิร์ดแน่",
  str_mission_desc_4006020 = "การจะดักชูมเมอร์ได้ ก็ต้องเร่งการค้นหา",
  str_mission_desc_4006030 = "กลุ่มซุ่มโจมตีหนึ่งของศัตรูติดตามอีกฝ่าย ขณะที่คาร์ลีนและไวซ์มุ่งมั่นหาโมดูลควบคุมไฟให้เร็วที่สุดเท่าที่จะทำได้",
  str_mission_desc_4006031 = "ความมืด ความหนาวเหน็บและความเงียบงัน...การต่อสู้เพียงลำพังนั้นเกินกว่าจะทนไหว แต่คุณไม่มีกำลังสนับสนุนจริงหรือ?",
  str_mission_desc_4006040 = "ถึงแม้จะเป็นการสนับสนุนทางไกลของมิสเชโอล ทางคดเคี้ยวในระเบียงเสียงกระซิบก็ผลักไสให้คุณสับสน",
  str_mission_desc_4006050 = "ดูเหมือนเกิร์ตเซิร์ดจะแอบนำไปข้างหน้าแล้ว นี่จะเป็นการต่อสู้ครั้งสุดท้ายหรือเปล่านะ?",
  str_mission_desc_4006060 = "\"แก...ฆ่าเชลต์!\" ผู้ล้างแค้นปรากฏตัวต่อหน้าคุณ",
  str_mission_desc_4006070 = "โมดูลควบคุมไฟอยู่ใกล้มือนิดเดียว ศัตรูจะทำอะไรกันแน่",
  str_mission_desc_4006080 = "จำนวนอิคลิพไซท์เพิ่มขึ้นและการต่อสู้อย่างต่อเนื่องทำให้ทุกคนเหนื่อยล้า",
  str_mission_desc_4006090 = "ไม่เคยหยุดพัก...รอยเท้าของเกิร์ตเซิร์ดกำลังเข้ามาหาและคุณสัมผัสได้ถึงกลิ่นความแค้นที่คุ้นเคย",
  str_mission_desc_4006091 = "ไม่ว่าจะอับจนหนทางยังไง สหายของคุณก็จะมาหาโดยไม่หวั่นต่ออันตรายใด ๆ",
  str_mission_desc_4006100 = "กับดักและกลุ่มซุ่มโจมตีตามทางหยุดคุณไว้ไม่ได้ มีคำถามที่เกิร์ตเซิร์ดต้องถามชูมเมอร์",
  str_mission_desc_4006110 = "ในที่สุดคุณก็ไปถึงส่วนลึกของระเบียงเสียงกระซิบ และถ้าไม่มีอะไร \"เหนือความคาดหมาย\" เกิดขึ้น โมดูลควบคุมไฟก็น่าจะอยู่ที่นี่",
  str_mission_desc_4006120 = "เกิร์ตเซิร์ดจะได้สิ่งที่เขาต้องการหรือไม่ ชูมเมอร์จะได้ทำตามประกาศก่อนตายของเขาไหม การเดินทางของคุณใกล้มาถึงจุดสิ้นสุดแล้ว",
  str_mission_desc_4007010 = "คุณตัดสินใจจะแยกทางไปเพื่อให้การดำเนินการช่วยเหลือและสนับสนุนเป็นไปพร้อมกัน",
  str_mission_desc_4007020 = "อิคลิพไซท์มหาศาลหลั่งไหลมาทั่วลูโมโพลิสชั้นล่าง แต่ปฏิบัติการของคุณน่าจะผ่านไปด้วยดีนะ",
  str_mission_desc_4007030 = "คุณรู้สึกท้อแท้ที่สัมผัสถึงโซรอซไม่ได้ แต่คุณต้องปกป้องชาวเมืองของลูโมโพลิสชั้นล่าง แม้ว่าจะไม่มีความสามารถด้านการต่อสู้ก็ตาม",
  str_mission_desc_4007031 = "ตอนนี้มีบางอย่างกำลังปะทุขึ้นในลูโมโพลิส",
  str_mission_desc_4007040 = "ข้างหน้าคุณมีแต่ภัยอันตรายและการต่อสู้ไปตามถนนอย่างบ้าคลั่ง นี่เป็นการทดสอบ\nที่คุณไม่เคยเจอมาก่อน",
  str_mission_desc_4007050 = "หน่วยสนับสนุนในลูโมโพลิสชั้นล่างจัดการเรียบร้อยแล้ว แต่เมืองชั้นบนกลับถูกโจมตีงั้นเหรอ?!",
  str_mission_desc_4007060 = "ในขณะที่คุณมุ่งหน้าไปยังเมืองชั้นบน ศัตรูประหลาดที่คุ้นเคยก็ปรากฏตัวขึ้น มันตัวใหญ่และน่ากลัว",
  str_mission_desc_4007070 = "นี่เป็นการต่อสู้เพื่อสิ่งที่ทุกคนอยากปกป้อง",
  str_mission_desc_4007080 = "การต่อสู้นี้เป็นการตัดสินความเป็นความตายที่คุณต้องแข่งกับเวลาเพื่อคว้าชัยชนะ",
  str_mission_desc_4007090 = "ความตื่นตระหนกค่อย ๆ ก่อตัวขึ้นอย่างหยุดไม่อยู่ คุณปล่อยให้พวกอิคลิพไซท์นี้ทำลายโซรอซอีกไม่ได้!",
  str_mission_desc_4007100 = "ข้อความจากโซรอซ หรือว่าจะเป็น...?!",
  str_mission_desc_4007110 = "อุณหภูมิรอบ ๆ เริ่มทะลักเข้ามาอย่างรวดเร็วและคุณได้กลิ่นชูมเมอร์!",
  str_mission_desc_4007111 = "ส่วนประกอบ 'ความตระหนักรู้ในตน' ของโซรอซหายไปแล้วจริงหรือ พันธะที่มีกับคุณจะหายไปด้วยไหม",
  str_mission_desc_4007120 = "ชูมเมอร์เปลี่ยนไปเป็นคนละคนหลังจากครอบครองโมดูลทั้งหมด\nนี่เป็นการต่อสู้หรือแค่...เกม สำหรับอีกฝ่ายกันแน่",
  str_mission_desc_4008020 = "ชูมเมอร์รั้งคุณไว้ในอวิดัซให้ไวซ์มาช่วยคุณ คุณตัดสินใจหาหัวหน้าวิเวียนและพาเธอไปด้วย",
  str_mission_desc_4008030 = "ในขณะที่คุณก้าวไปข้างหน้า พลันร่างกายก็รู้สึกประหลาดแต่ไม่มีเวลาตรวจว่ามีอะไรแปลกไป คุณต้องหาวิเวียนให้เร็วที่สุด",
  str_mission_desc_4008040 = "คุณก้าวไปเบา ๆ และจัดการกับศัตรูที่ขวางทางอย่างรวดเร็ว",
  str_mission_desc_4008041 = "หลอกล่อ สลับฝั่งและแทงข้างหลัง...อิคลิพไซท์จะโดนตีอย่างไม่ทันตั้งตัว",
  str_mission_desc_4008050 = "ภายในของโคลอสซัสสีดำจัดวางอย่างซับซ้อน คุณต้องระมัดระวังอย่างมาก",
  str_mission_desc_4008060 = "ชูมเมอร์ยังหาคุณไม่เจอ เดินหน้าต่อ...บางทีหัวหน้าวิเวียนอาจอยู่ในห้องข้างหน้าก็ได้!",
  str_mission_desc_4008070 = "ในขณะที่คูรีบุกทะลวงไปข้างหน้า คุณก็เจอที่ที่หัวหน้าวิเวียนถูกจับไว้และมีศัตรูทรงพลังรอคุณอยู่",
  str_mission_desc_4008090 = "หัวหน้าวิเวียนได้รับการช่วยเหลือสำเร็จ ดังนั้นภารกิจด่วนที่สุดต่อมาก็คือการออกจากสถานที่เลวร้ายนี้ แต่มันเป็นทางเลือกที่สมเหตุสมผลที่สุดแล้วจริงหรือ",
  str_mission_desc_4008100 = "เกิดเสียงดังขึ้น สถานการณ์เปลี่ยนไปแล้ว คาร์ลีนทำสำเร็จ หรือชูมเมอร์เป็นฝ่ายชนะกันแน่!?",
  str_mission_desc_4008110 = "กลยุทธ์ของคุณเปลี่ยนจากหนีเป็นโจมตี! นี่เป็นโอกาสสุดท้ายของคุณที่จะหักแขนขาศัตรูจากภายใน!",
  str_mission_desc_4008111 = "คุณยังต้องเจอการทดสอบและความยากแค้นอะไรอีกในอวิดัซอันเลวร้ายแห่งนี้นะ",
  str_mission_desc_4008120 = "เส้นทางนำไปยังห้องบังคับการเต็มไปด้วยอันตรายและอิคลิพไซท์ที่โจมตีอย่างบ้าคลั่ง",
  str_mission_desc_4008130 = "เดินหน้าต่อไป...ชูมเมอร์อาจอยู่ใกล้ ๆ!",
  str_mission_desc_4008140 = "ในที่สุดวินาทีตัดสินก็มาถึง ลูโมโพลิสและโคลอสซัสสีดำ...วันนี้จะมีฝั่งหนึ่งที่ต้องพ่ายแพ้ และคุณจะได้เป็นสักขีพยานเหตุการณ์ทั้งหมด",
  str_mission_desc_4009020 = "คุณตามร่องรอยเศษซากของอวิดัซไปและพบว่าตัวเองกลับไปที่อีราเวล ที่ซึ่งเป็นจุดเริ่มต้นของทุกสิ่ง",
  str_mission_desc_4009030 = "จะมีคนอื่นอยู่ที่นี่อีกไหมนะ นอกจากพวกอิคลิพไซท์",
  str_mission_desc_4009040 = "อันตรายที่สาหัสยิ่งกว่านี้ยังรออยู่ข้างหน้า รวมทั้งใบหน้าที่คุ้นเคยของใครบางคน...",
  str_mission_desc_4009041 = "ค้นหาจุดอ่อนของมันให้เจอ และใช้ศัตรูกำจัดศัตรู",
  str_mission_desc_4009050 = "เมื่อได้ซินซาเข้าร่วมขบวน การสำรวจอีราเวลก็กลายเป็นงานที่ง่ายขึ้นกว่าเดิมมาก",
  str_mission_desc_4009060 = "พลังความมืดที่มีอยู่มากมายอาจทำให้อากาศเยือกเย็นขึ้น แต่คุณก็ต้องก้าวต่อไป",
  str_mission_desc_4009070 = "อารมณ์ที่หนักแน่นเชือดเฉือนผ่านอากาศเข้ามา เสียงร้องนั่นมาจากไหนกันนะ ใช่อิคลิพไซท์รึเปล่า",
  str_mission_desc_4009090 = "พื้นดินสั่นสะเทือน และออร่าที่น่ากลัวก็พุ่งพรวดเข้ามา...",
  str_mission_desc_4009100 = "ใช้พลังจิตของคุณเพื่อผลักดันไปข้างหน้า เพื่อค้นหาหนทางฝ่าขบวนทัพของศัตรูให้ได้!",
  str_mission_desc_4009110 = "เหมือนว่าศัตรูจะพากันมาเยอะขึ้นเรื่อย ๆ แล้ว และพวกมันก็ดูจะปฏิบัติการกันอย่างพร้อมเพรียงซะด้วย",
  str_mission_desc_4009111 = "ถ้าคุณไม่สามารถกำจัดศัตรูแบบตรง ๆ ได้ ให้ลองสร้างโอกาสจากมุมอื่นดู",
  str_mission_desc_4009120 = "ศัตรูตัวฉกาจปรากฏขึ้น... ได้เวลากำจัดสิ่งชั่วร้ายให้พ้นไปจากอีราเวลแล้ว!",
  str_mission_desc_4009130 = "ศัตรูที่แข็งแกร่งยิ่งกว่าเดิมรออยู่ ก่อนที่จะเผชิญกับการต่อสู้ข้างหน้า คุณต้องหลบหนีจากการปิดล้อมของอิคลิพไซท์ให้ได้ก่อน...",
  str_mission_desc_4009140 = "ซากยานอวิดัซอยู่ข้างหน้านั่น ว่าแต่ใครกันล่ะที่ยืนอยู่ข้างหน้า!?",
  str_mission_desc_4010020 = "อวิดัซอยู่ตรงหน้าคุณ ไม่ว่าจะไล่ตามฟอร์เซคิน หรือยืนยันว่าชูมเมอร์ยังมีชีวิตอยู่หรือไม่...  ทางเลือกเดียวของคุณคือต้องเข้าไป...",
  str_mission_desc_4010030 = "คุณใช้พลังจิต จนรู้มาว่าชูมเมอร์กำลัง... กินอิคลิพไซท์อยู่เหรอเนี่ย!?",
  str_mission_desc_4010040 = "อิคลิพไซท์พวกนี้ไม่ได้พากันหนีตายทั้งหมดนะ... บางส่วนก็เตรียมพร้อมที่จะต่อสู้และฆ่าคุณ",
  str_mission_desc_4010041 = "ถ้าโชคพอจะเข้าข้างคุณบ้าง ก็ลองใช้ประโยชน์จากสภาพแวดล้อมเพื่อพลิกสถานการณ์ให้เข้าทางคุณเลย!",
  str_mission_desc_4010050 = "มีอิคลิพไซท์จำนวนนับไม่ถ้วนอยู่ภายในยานอวิดัซราวกับหนอนเน่าที่ชอนไชอยู่ในซากศพ",
  str_mission_desc_4010060 = "อิคลิพไซท์พวกนี้ดูมุ่งมั่นที่จะขัดขวางไม่ให้คุณเดินหน้าไปต่อได้",
  str_mission_desc_4010070 = "ศัตรูที่คุ้นเคยอีกตัวปรากฏตัวขึ้ืนมา ดูท่าทางแล้วเราห้ามประมาทกับเวทมนตร์ชุบชีวิตของฟอร์เซคินเด็ดขาด...",
  str_mission_desc_4010090 = "เมื่อยืนยันความฝันของคุณเกี่ยวกับอีราเวลได้ ไฟโทสะของคุณก็จุดติดขึ้นมาอีกครั้ง",
  str_mission_desc_4010100 = "ศัตรูที่ยืนอยู่ตรงหน้าคุณดูจะมีความสามารถในการกักเก็บลูมินาติกส์! การต่อสู้ครั้งนี้หินแน่นอน",
  str_mission_desc_4010110 = "อิคลิพไซท์ที่ขวางเส้นทางอยู่นี้ไม่มีเจตนาจะยอมแพ้เลยถ้าไม่ได้ต่อสู้",
  str_mission_desc_4010111 = "ดูเหมือนว่าอิคลิพไซท์พวกนี้จะหลั่งไหลกันเข้ามาอย่างไม่มีที่สิ้นสุด...",
  str_mission_desc_4010120 = "อิคลิพไซท์พวกนี้พยายามผลักดันให้คุณเจอกับสถานการณ์ที่สิ้นหวัง!",
  str_mission_desc_4010130 = "ชูมเมอร์อยู่ข้างหน้านี้เอง คุณไม่จำเป็นต้องใช้พลังจิตก็รับรู้ได้... พื้นดินที่สั่นสะเทือนและพลังความมืดที่รุนแรงก็บ่งบอกได้อย่างเพียงพอแล้ว",
  str_mission_desc_4010140 = "เอาชนะชูมเมอร์ให้ได้!",
  str_mission_desc_4101020 = "เมื่อถูกพลังความมืดข่มเอาไว้ คุณจึงต้องเผชิญกับความยากลำบากในการต่อสู้มากขึ้น แต่คุณไม่สามารถถอยกลับได้เพื่อความปลอดภัยของโซรอซ!",
  str_mission_desc_4101030 = "ลึกเข้าไปในเมืองใต้ดิน มีร่องรอยจากสงครามฝังอยู่ท่ามกลางความลับอื่น ๆ...",
  str_mission_desc_4101040 = "อิคลิพไซท์ระดับสูงมาที่นี่กันได้ยังไง? วิ่งเลย! ห้ามหยุดเด็ดขาด!",
  str_mission_desc_4101060 = "ไรน์ฮาร์ตเฝ้ามองคุณอยู่ เพื่อให้แน่ใจว่าคุณจะปลอดภัย เธอจึงถูกความวิตกกังวลเข้าครอบงำ",
  str_mission_desc_4101070 = "เกิดบ้าอะไรขึ้นที่เมืองใต้ดินหมายเลข 80 กันเนี่ย? บางทีไรน์ฮาร์ตอาจมีคำตอบก็ได้",
  str_mission_desc_4101080 = "อีกไม่นานคุณก็จะลงจอด พอจะมีความหวังให้ได้เดินทางกลับอย่างปลอดภัยรออยู่บ้างไหมนะ?",
  str_mission_desc_4101090 = "ความเกลียดชังที่เนิ่นนานไม่สามารถปลอบประโลมให้บรรเทาลงได้โดยง่าย บางครั้งการจากไปอาจเป็นทางเลือกที่ดีที่สุด",
  str_mission_desc_4201020 = "โซรอซถูกอิคลิพไซท์ซุ่มโจมตีเหรอ อย่าเพิ่งตื่นกลัว เราจะไล่พวกมันไปจากยานโคลอสซัสแน่นอน!",
  str_mission_desc_4201030 = "ที่เห็นอิคลิพไซท์สามารถโจมตีโซรอซได้นั้นชี้ให้เห็นว่ามีคนอยู่เบื้องหลังเรื่องทั้งหมด นี่ไม่ใช่การซุ่มโจมตีธรรมดา!",
  str_mission_desc_4201040 = "อย่างไรก็ดี ถ้าลงจอดได้ตามที่วางแผนไว้ ก็ไม่ถือว่าเป็นเหตุยานตก",
  str_mission_desc_4201041 = "การเผชิญหน้ากับอิคลิพไซท์ขณะค้นหาทางเข้าไม่ใช่ส่วนหนึ่งของแผนการ แต่จะมัวเสียเวลาไม่ได้ มาจัดการพวกมันอย่างรวดเร็วกันเลย",
  str_mission_desc_4201050 = "ดีนะที่คุณมีเครื่องตรวจจับโลหะมาช่วยเริ่มต้นการค้นหาทางเข้าของเรา แต่ว่ามันจะค้นหาอะไรที่เป็นประโยชน์ได้แน่เหรอ?",
  str_mission_desc_4201060 = "ที่นี่ว่างเปล่า... มีเหลือเพียงแค่เสียงสะท้อนและเศษเสี้ยวของอดีต",
  str_mission_desc_4201061 = "สำรวจและค้นหาต่อไป... มาพยายามให้เต็มที่เพื่อค้นหาแสงแห่งความหวังในห้วงลึกกันเถอะ",
  str_mission_desc_4201070 = "มีวิญญาณไม่ทราบที่มาคอยดูการต่อสู้อยู่ และมันติดตามคุณทุกฝีก้าว",
  str_mission_desc_4201080 = "อย่าหยุดและอย่าหันกลับไปมองข้างหลัง วิ่งไปข้างหน้าต่อไปและไล่ตามฟ้าหลังฝนนั่นให้ได้",
  str_mission_desc_4201090 = "คนเราต้องทำชั่วร้ายแบบไหนกันถึงได้ถูกเนรเทศไปยังห้วงลึกแบบนั้น?",
  str_mission_desc_4201100 = "มันไม่ได้อยู่ตรงนี้ แต่อยู่ลึกลงไป เดินหน้าต่อไป แต่คอยระวังภัยคุกคามจากอดีตไว้ด้วย",
  str_mission_desc_4201120 = "เคเลสไทต์ ออโรเรียน อิคลิพไซท์ โคลอสซัส... อยากรู้จังว่ามีความลับกี่อย่างที่ซ่อนอยู่ในฐานอันกว้างใหญ่ที่ถูกทิ้งร้างมานานแห่งนี้...",
  str_mission_desc_4201130 = "มันไม่ใช่แค่กำแพงกับประตูของฐานเท่านั้นที่คอยปกป้องความลับเหล่านี้เอาไว้ แต่มีอิคลิพไซท์พวกนั้นด้วยเช่นกัน",
  str_mission_desc_4201140 = "สมองกลผู้ช่วยได้รับความเสียหาย และไม่มีช่องทางให้ใส่คำสั่งได้อย่างถูกต้อง ถ้างั้น... รีบูตมันก่อนดีไหม?",
  str_mission_desc_4202020 = "ท่าทางจะมีอิคลิพไซท์อยู่ในหอคอยแห่งนี้ พวกมันอยู่ที่นี่กันตั้งแต่แรกแล้วเหรอ?",
  str_mission_desc_4202030 = "ขณะที่คุณเคลื่อนที่ต่อไป คุณก็ได้พบกับสิ่งที่ไม่เคยพบเห็นและไม่ได้คาดหมาย",
  str_mission_desc_4202040 = "คุณได้ยินเสียงแปลกประหลาดอยู่เบื้องหลังมาพักหนึ่งแล้ว มีอิคลิพไซท์ตามรอยคุณอยู่... หรืออย่างอื่นกันแน่?",
  str_mission_desc_4202041 = "เรามีอิคลิพไซท์ที่ฉลาดพอจะใช้กับดักตั้งแต่เมื่อไรกัน?! คอยระวังไว้นะ แล้วปราบพวกมันให้ได้!",
  str_mission_desc_4202050 = "กับดักที่นำไปสู่คอร์ดโซนทั้งหมดนี้มันยังไงกันแน่?! อยากรู้จังว่าเอามาใช้ได้ไหม...",
  str_mission_desc_4202060 = "บาร์ตันตันสินใจใช้คอร์ดลิงก์เพื่อหลบหนีออกจากสถานการณ์ที่ยากลำบากนี้ พยายามทำทุกวิถีทางเพื่อซื้อเวลาให้เขาเถอะ!",
  str_mission_desc_4202070 = "ใจเย็น ๆ... อีกนิดเดียวทุกอย่างก็จะเข้าทางคุณแล้ว",
  str_mission_desc_4202090 = "การต่อสู้กำลังโหมกระหน่ำอยู่นอกหอคอย และในที่สุดกำลังเสริมก็มาถึง ตอนนี้ก็เหลือแค่ต่อสู้กันเท่านั้น",
  str_mission_desc_4202100 = "ทุกคนกำลังพยายามเต็มที่ในสนามรบ แต่พวกเขาจะต้านไว้ได้นานเท่าไร?",
  str_mission_desc_4202115 = "ชาวออโรเรียนที่อยู่นอก Obelisk of Return กำลังพยายามอย่างเต็มที่เพื่อหาโอกาสพลิกกระแส",
  str_mission_desc_4202111 = "ท่าทางตัวปัญหาจะเข้าสู่สนามรบแล้ว เวลากำลังจะหมด ต้องโจมตีเดี๋ยวนี้!",
  str_mission_desc_4202120 = "ยังมีอิคลิพไซท์ปิดกั้นเส้นทางสู่วงแหวนแกนกลาง และมีความท้าทายที่ยากยิ่งกว่าเดิมอยู่ข้างหน้า",
  str_mission_desc_4202130 = "มีบางอย่างที่มีแค่คุณเท่านั้นที่จะจัดการได้ ทุกคนมาแล้วและพร้อมช่วยเหลือ ดังนั้นลงมือได้เลย",
  str_mission_desc_4202140 = "นี่คือเสียงเรียกกลับคืน ไม่ใช่เรียกตัวคุณ แต่เรียกความหวังให้กลับมา",
  str_mission_desc_4203020 = "เพื่อให้เข้าใจเงื่อนไขของ Vice ได้ดีขึ้น คุณยินยอมให้ Illumina ค้นคว้าโมดูลข้อมูลใหม่ที่พบใน Soroz",
  str_mission_desc_4203030 = "หลังจากเข้าสู่สนามรบจำลองแล้ว คุณจะเริ่มทำการทดสอบตามคำแนะนำของนักวิจัย อย่างน้อยที่สุด การต่อสู้ก็ค่อนข้างง่าย...สำหรับตอนนี้",
  str_mission_desc_4203040 = "คุณใช้โปรแกรมจำลองการต่อสู้อีกครั้ง แต่คราวนี้ภูมิประเทศและสภาพแวดล้อมเปลี่ยนไป",
  str_mission_desc_4203041 = "มีความสับสนอลหม่านและอันตรายอยู่รอบตัว และคุณก็หลงทางไปหมดแล้ว... คุณไม่สามารถอยู่ที่นี่ได้นานกว่านี้อีกแล้ว!",
  str_mission_desc_4203050 = "รอก่อน. ไม่มีใครบอกว่าการจำลองจะยากขนาดนี้!",
  str_mission_desc_4203060 = "สถานที่นี้คืออะไร? ทำไมฉันไม่เคยเห็นมาก่อน รอง? ไรน์ฮาร์ด? พวกคุณได้ยินฉันไหม",
  str_mission_desc_4203070 = "ทหารที่สิ้นหวังถูกบดขยี้ภายใต้การโจมตีของ Eclipsite อันโหดร้าย... นี่คือจุดจบของโลกหรือไม่?",
  str_mission_desc_4203090 = "Guardian One ผู้รับผิดชอบการดำเนินงานประจำวันของสหพันธ์อิลลูมินาทั้งหมด... ดูเล็กกว่าที่คิด",
  str_mission_desc_4203100 = "แม้ว่านี่จะเป็นครั้งแรกที่คุณได้พบกับ Guardian One แต่ความรู้สึกไว้วางใจที่บริสุทธิ์และเป็นธรรมชาติระหว่างคุณสองคนก็เกิดขึ้น",
  str_mission_desc_4203110 = "เป็นไปไม่ได้ที่จะยืนด้วยเท้าทั้งสองข้างบนพื้นแข็งในสภาพแวดล้อมเสมือนจริง ถึงกระนั้น ทางเลือกเดียวของคุณก็คือเดินไปข้างหน้าต่อไป",
  str_mission_desc_4203111 = "การทดลองนี้พยายามทดสอบขีดจำกัดของความแข็งแกร่งเพื่อที่จะค้นพบโอกาสแม้แต่น้อยที่จะทำลายมันได้",
  str_mission_desc_4203120 = "ยื่นมือออกไป วิ่งให้เร็วขึ้น—อีกแค่ก้าวเดียวก็จะไปถึงแล้ว",
  str_mission_desc_4203130 = "ถึงเวลาแก้ไขสิ่งต่างๆ ท้ายที่สุด นั่นคือเหตุผลที่คุณมาที่นี่ตั้งแต่แรก",
  str_mission_desc_4203140 = "หลังจากเวลาผ่านไปไม่แน่นอน ในที่สุดคุณก็มาถึงความผิดพลาดขั้นสุดท้าย",
  str_mission_desc_4204020 = "อาวุธสำคัญที่ทรงพลังที่เรียกว่า \"Combat Cyborg\" คือ...",
  str_mission_desc_4204030 = "ฌอนกลับมาจากเขตสงครามให้เร็วที่สุดเท่าที่จะทำได้ เขาได้รับข่าวจากกองทหารรักษาการณ์อิลลูมินาว่าคุณอยู่ระหว่างทาง",
  str_mission_desc_4204031 = "บางครั้งการพุ่งเข้าสู่การต่อสู้โดยตรงไม่ใช่ตัวเลือกที่ดีที่สุด",
  str_mission_desc_4204040 = "คุณเดินทางต่อไปยัง Twilight ที่ซึ่งเพื่อนเก่าสามคนกลับมารวมตัวกันอีกครั้ง",
  str_mission_desc_4204050 = "หลังจากไปถึงชานเมืองของ Twilight ในที่สุด แสงออโรร่าเหนือศีรษะก็เริ่มพวยพุ่งจนเกินการควบคุม สะกดหายนะให้กับผู้ที่อาศัยอยู่ด้านล่าง",
  str_mission_desc_4204060 = "ยังมีพลเรือนที่อยู่ข้างหลังคุณพยายามหลบหนี! อย่าปล่อยให้ Eclipsite แม้แต่ตัวเดียวผ่านคุณไป!",
  str_mission_desc_4204070 = "จู่ๆ ลำแสงก็สว่างขึ้นในสนามรบ ทำให้คุณและพรรคพวกต่อสู้ได้โดยไม่มีข้อจำกัด",
  str_mission_desc_4204090 = "ในที่สุดคุณและพันธมิตรก็พร้อมแล้ว ความมืดจะไม่บดบังการมองเห็นของคุณอีกต่อไป",
  str_mission_desc_4204100 = "สิ่งที่คุณค้นหา...จะเป็นได้ที่ไหน?",
  str_mission_desc_4204101 = "ค้นหาจุดอ่อน เล็งให้ดี และตั้งสมาธิในการโจมตีของคุณ!",
  str_mission_desc_4204115 = "ใครมีพลังมากกว่า: Axelia หรือ Sean",
  str_mission_desc_4204120 = "หลังจากผ่านความยากลำบากมาไม่น้อย ในที่สุดคุณก็ได้พบกับยักษ์ใหญ่ที่ตกลงสู่ซากปรักหักพัง ชัยชนะอยู่แค่เอื้อม",
  str_mission_desc_4204130 = "ทันทีหลังจากคัดลอกข้อมูล Colossus ก็เริ่มขยับ ภัยพิบัติอื่นอาจอยู่ใกล้แค่เอื้อม?",
  str_mission_desc_4204140 = "บทกวีสุดท้าย แด่เธอ... คำอำลาสุดท้าย",
  str_mission_desc_4205020 = "Forsakin บังคับให้คุณต่อสู้กับทหาร Illumina",
  str_mission_desc_4205030 = "คุณพบทหารยามที่ทางเข้าห้องปฏิบัติการอีกครั้ง",
  str_mission_desc_4205040 = "คุณและ Vice จะไม่กระตุกนิ้วหัวแม่มือในขณะที่การทดสอบดำเนินต่อไป รอเวลาที่เหมาะสมเพื่อพลิกสถานการณ์...",
  str_mission_desc_4205041 = "คว้าโอกาสที่จะเอาชนะศัตรูและหลบหนี!",
  str_mission_desc_4205050 = "การต่อต้านของคุณถูก Eclipsites อัญเชิญโดย Forsakin ในการดวลที่ดุเดือดถึงตาย!",
  str_mission_desc_4205070 = "แยกจาก Vice ตัวคนเดียวของคุณไม่มีทางเลือกอื่นนอกจากต้องเชื่อฟัง Forsakin คุณต้องทำตามความประสงค์ของเธอและผจญภัยลึกเข้าไปใน Undercity",
  str_mission_desc_4205080 = "เพื่อตามหาทั้งคุณและ Vice ที่หายไปนาน Carleen ทำตามคำแนะนำของ Gronru ไปยัง Undercity",
  str_mission_desc_4205090 = "ยังคงค้นหาไฟล์ Forsakin ไม่ได้คาดหวังการป้องกันที่ดีใน File Archive",
  str_mission_desc_4205100 = "เมื่อได้รับมอบหมายให้ทำภารกิจสำคัญ ในที่สุด Yingel ก็พบเบาะแสของ Vice แต่ดันไปเจอศัตรูที่น่าเกรงขามก่อนที่จะได้รับการช่วยเหลือ...",
  str_mission_desc_4205101 = "ศัตรูบางตัวจะต่อสู้กับคุณในการต่อสู้ที่ยาวนานและถึงตายได้ ดังนั้นโปรดระวัง...",
  str_mission_desc_4205110 = "Yingel กำลังต่อสู้กับการต่อสู้ที่ยากลำบาก ในขณะที่ Carleen ไปถึง Forsakin และจะพยายามพาคุณออกไปจากที่นี่",
  str_mission_desc_4205120 = "Forsakin เสียสมดุลจากเปลวไฟที่น่าประหลาดใจ ใช้โอกาสนี้เพื่อเอาชนะเธอและเฮลิออส!",
  str_mission_desc_4205130 = "เมื่อคุณกำลังจะเอาชนะ Forsakin เธอขัดขวางโดยตัดไฟที่ประตูหลัก...",
  str_mission_desc_4205140 = "Forsakin ได้ทำการอัปเกรดขั้นสุดท้ายเป็น Helios แล้ว มันจะเป็นการต่อสู้ที่โหดร้าย",
  str_mission_desc_4206020 = "เซสชันแรกคือการต่อสู้เสมือนจริงผ่าน Battle Simulator และผู้เข้าร่วมการฝึกทุกคนกำลังเตรียมตัวอย่างจริงจัง",
  str_mission_desc_4206030 = "เซสชันที่สองเป็นบทเรียนการต่อสู้ โดยมีทีมเจ้าหน้าที่ฝึกอบรมที่นำโดย Wrath ถ่ายทอดความรู้ในการสู้รบให้กับผู้เข้าร่วมการฝึก...",
  str_mission_desc_4206040 = "สำหรับหน่วยกิตหลักสูตรเพิ่มเติม คุณ Vice และ Carleen ตัดสินใจขอใบอนุญาตจำลองเพิ่มเติมเพื่อฝึกฝนทักษะการต่อสู้ของคุณ",
  str_mission_desc_4206041 = "ดูเหมือนว่าศัตรูจะกินขาดจากการต่อสู้! มันต้องมีวิธียุติการต่อสู้!",
  str_mission_desc_4206050 = "ก่อนที่การฝึกจะเริ่มขึ้น Eclipsites จากใครก็ไม่รู้ก็ปรากฏตัวขึ้นในเมืองกันนอน กำจัดพวกเขาโดยเร็วที่สุด",
  str_mission_desc_4206060 = "เซสชั่นที่สามของการฝึกร่วมทางทหารกำลังต่อสู้ Eclipsites ของแท้ในการต่อสู้จริง ผู้เข้าร่วมจะเอาชนะศัตรูจำนวนมากได้หรือไม่?",
  str_mission_desc_4206070 = "เมื่อมาถึงจุดยึดธง ทีมก็แยกกันและไปที่ Undercity อย่างไรก็ตาม ทีมของคุณต้องต่อสู้กับ Eclipsites อย่างไม่คาดคิด",
  str_mission_desc_4206080 = "การต่อสู้ที่วุ่นวายยังคงดำเนินต่อไป และทีมแปลกๆ นั้นก็พิสูจน์แล้วว่าค่อนข้างแข็งแกร่ง...",
  str_mission_desc_4206090 = "คุณดำดิ่งลึกเข้าไปใน Undercity จนกระทั่งพบกับอันตรายที่ใหญ่กว่าในรูปของความชั่วร้ายขนาดมหึมาที่เหมือนแมงมุม",
  str_mission_desc_4206110 = "คุณ Yingel และคนอื่นๆ แยกกันไปดู Gannon แน่นอนว่าคุณเจอ Eclipsites ที่หลุดรอดช่องโหว่ในการป้องกัน!",
  str_mission_desc_4206120 = "ผู้บุกรุก Eclipsite แตกตื่นกระจัดกระจาย ดูเหมือนไม่ได้ตั้งใจจะต่อสู้ คุณยังสัมผัสได้ถึงอันตรายที่คุ้นเคยของภูติผีตนหนึ่ง...",
  str_mission_desc_4206121 = "ผู้บุกรุกยังคงอยู่ในเมืองที่ต้องกำจัดโดยเร็วที่สุด",
  str_mission_desc_4206130 = "ตามเส้นทางของ Wraith คุณมาถึงประตูแห่งหนึ่งที่ระดับต่ำสุด ฟิเจอรัลด์กำลังตามล่าอะไรบางอย่างในนั้น หยุดเขา!",
  str_mission_desc_4206140 = "พวกโบตั๋นหมดทาง ตอนนี้ไปที่ Figerald the Wraith!",
  str_mission_desc_4207020 = "คุณและวิซเข้าสู่สำนักงานของผู้บัญชาการกองทัพอิลลูมินา หวังว่าจะมีโอกาสเปลี่ยนแนวคิด แต่ก่อนที่คุณจะพูดอะไรได้ ผู้บัญชาการก็ได้รับคำสั่งภารกิจและออกไปแล้ว...",
  str_mission_desc_4207030 = "ประชาชนของอิลลูมินากำลังพูดคุยกันเรื่องที่เกิดขึ้นเมื่อเร็ว ๆ นี้ ในขณะที่คุณสังเกตเหตุการณ์นี้ มีประกาศส่งเสียงผ่านระบบอินเตอร์เน็ตใต้ดิน ประกาศถึงความสำเร็จในการขึ้นครองตำแหน่งของจอมทัพใหม่...",
  str_mission_desc_4207031 = "อิคลิพไซท์กำลังจะหลุดออกจากที่ที่ถูกกักกันเร็ว ๆ นี้ ขจัดพวกมันเพื่อความปลอดภัยของห้องปฏิบัติการ!",
  str_mission_desc_4207040 = "พึ่งได้รับการเลื่อนขั้นเป็นจอมพลแห่งอิลลูมินา วราธถูกมอบหมายให้เสริมกำลังแนวหน้าการรบที่ Twilight แต่ในขณะที่เธอเตรียมตัวสำหรับการออกเดินทาง เธอดูเหมือนจะไม่รู้สึกความสุขที่คาดหวังจากการเป็นจอมพล...",
  str_mission_desc_4207050 = "ย้อนอดีตไปดู วราธได้เริ่มต้นท้าชิงต่อไรน์ฮาร์ตอย่างไม่รู้จบ ซึ่งเกือบทั้งหมดล้มเหลว รวมถึงการคัดเลือกสุดท้ายสำหรับจอมพล...",
  str_mission_desc_4207060 = "โจเซลีนนำทหารผู้บาดเจ็บไปยังที่ปลอดภัย อย่างไรก็ตาม เมื่อทราบถึงความไม่มั่นใจของทหารในสนามรบ เธอจึงคิดอยู่ว่าจะช่วยเสริมใจให้พวกเขาอย่างไร...",
  str_mission_desc_4207080 = "ด้วยความสามารถทางจิตใจของคุณ คุณรับรู้ได้ว่าพลังความมืดที่ปกคลุม Twilight ดูเหมือนจะถูกควบคุมโดยคำสั่งจากศูนย์กลาง แต่ก็ยังคงมีความลึกลับที่คาดเดาไม่ถูกเกี่ยวกับศัตรูหลักที่ศูนย์กลางนี้...",
  str_mission_desc_4207090 = "การมาถึงของกลุ่มทหารอิลลูมินาทำให้การกระทำของอิคลิพไซท์หยุดชั่วขณะ แต่ฟอร์เซคินดูเหมือนจะตรวจพบความลับเบื้องหลังความแข็งแกร่งเพิ่มของทหารคนเหล่านี้...",
  str_mission_desc_4207100 = "ในขณะที่การต่อสู้กับอิคลิพไซท์ยังคงเดือดขึ้น คลื่นของการกระทำผิดปกติเริ่มกระจายในหมู่ทหารอิลลูมินา ความสงสัยเพิ่มขึ้นว่าทหารอาจถูกสั่งการโดยศัตรูที่ทำหน้าที่เป็นคำสั่งกลาง...",
  str_mission_desc_4207110 = "ความห่วงใยในสนามรบของ Axelia, Yingel ไปยังห้องปฏิบัติการของ Ulysses ภายในกำแพงเหล่านี้เธอเห็นการทดลองที่โหดร้าย...",
  str_mission_desc_4207111 = "ปีศาจในทรายดูดได้ขวางทางของคุณ ปราบพวกมันเถอะ!",
  str_mission_desc_4207120 = "พบกับความเสียหายที่ขยายออกไปอย่างต่อเนื่องและการโจมตีของอิคลิพไซท์ วราธตัดสินใจอย่างเด็ดขาด - จะพุ่งเข้าไปในโคลนเพื่อค้นหาศัตรูคำสั่งกลางที่ซ่อนอยู่ในนั้น...",
  str_mission_desc_4207130 = "หลังจากปะทะกับศัตรูในคำสั่งกลาง ร่างกายของวราธเริ่มสูญเสียการควบคุมอย่างทีละขั้น โซรอซคาดว่าความตื่นตัวของเธออาจถูกกลืนกินโดยโคลน...",
  str_mission_desc_4207140 = "กองกำลังของ Axelia ตกอยู่ในโคลนมานานแล้ว ณ ขณะนี้ Axelia สูญเสียความสามารถในการโจมตี Eclipsites แล้ว แต่ริมฝีปากของเธอยังคงกระซิบคำสั่งการกระทำพิเศษสองอย่าง...",
  str_mission_desc_4208020 = "พวกคุณสามารถเอาชนะอิคลิพไซท์ดินเหนียวแล้ว และเริ่มการค้นหาตำแหน่งของวราธอย่างเต็มที่ อย่างไรก็ตาม ในขณะนี้เอง การเปลี่ยนแปลงที่ไม่คาดคิดก็เริ่มปรากฏขึ้นในหมู่ทหารอิลลูมินา...",
  str_mission_desc_4208030 = "ความสบายใจท่วมคุณเมื่อวราธกลับมา แต่ความทุกข์ยากของเธอทำให้คุณสับสน ต่อมา ความสนใจของทุกคนเปลี่ยนไปสู่การจัดการกับสถานการณ์ของทหารที่บาดเจ็บ...",
  str_mission_desc_4208040 = "กองกำลังติดตามที่นำโดยคารอนและไวซ์พบกับความต้านทานแปลกประหลาด ซึ่งป้องกันไม่ให้พวกเขาเข้าถึง Dark Zone ในระหว่างนั้นบนรถไฟ มีผู้โดยสารลึกลับปรากฏขึ้น...",
  str_mission_desc_4208041 = "สถานการณ์เริ่มควบคุมไม่ได้ ศัตรูกำลังมุ่งเป้าหมายที่คุณ; กรุณาปกป้องเพื่อนร่วมทีมของคุณ",
  str_mission_desc_4208050 = "วิกตอเรียนำกลุ่มหลบหนีการไล่ล่าของกำลังลึกลับชั่วคราว แต่ในขณะนี้เอง ไบเบิลโชกเลือดนำความประทับใจใหม่ๆ มาให้เห็น...",
  str_mission_desc_4208060 = "ในขณะที่วราธกำลังค้นหาผู้ใต้บังคับบัญชาของเธอ ทหารคนหนึ่งที่สับสนก็เข้ามาคว่ำคอเธอ ทุกคนพยายามพูดให้เธอเข้าใจ แต่เธอก็ยังไม่สามารถตัดสินใจได้...",
  str_mission_desc_4208070 = "โจเซลีนขอร้องให้ฐานที่มั่นลูโม่เปิดที่พักให้ผู้ลี้ภัย แต่กลับถูกปฏิเสธ แต่ในขณะที่ทหารที่ได้รับบาดเจ็บเริ่มโจมตีคนที่ไม่มีความผิด พลังเสียงที่มีอำนาจก็ส่งเสียงดังขึ้น...",
  str_mission_desc_4208080 = "เมื่อการค้นหาถึงเส้นขอบของ Twilight ภาพที่ทำให้ตะลึงตาเกิดขึ้นอยู่หน้าตาของกลุ่ม และผู้บงการที่อยู่เบื้องหลังทั้งหมดในที่สุดก็ปรากฏตัว...",
  str_mission_desc_4208100 = "ด้วยโคลนที่หายไป ทไวไลท์เหลือเพียงกำแพงที่แตกสลายและซากปรักหักพัง แต่ก็ยังหวังใหม่ในอนาคตของเมือง สำหรับลีโอและโจเซลีน ที่ต้องเผชิญกับเศษซากที่รกเลอะ",
  str_mission_desc_4208110 = "ตามแนวป้องกันของอิลลูมินา ชาโรนานำกองพลที่ 1 พยายามขับไล่อิคลิพไซท์ แต่น้ำท่วมของหนองน้ำและการโจมตีจากทหารคนเดียวกันทำให้ความตื่นตัวเกิดขึ้นในทัพ...",
  str_mission_desc_4208111 = "กำจัดความโค้งของด้วยกำลังเสริมปืนใหญ่!",
  str_mission_desc_4208120 = "ขณะที่ฟอร์เซคินนำความวุ่นวายในการโจมตีเส้นป้องกันของ Illumina ความขัดแย้งของเสียงล้อกระทั่งและกีบเท้ากระโดดเป็นสะพัดจากทิศทางของ Twilight...",
  str_mission_desc_4208130 = "การต่อสู้อย่างดุเดือดยังคงเปิดฉากอยู่ ด้วยทหารอิลลูมินาที่สับสนเริ่มโจมตีฝ่ายของคุณอย่างต่อเนื่อง...",
  str_mission_desc_4208140 = "ขณะที่ผู้บัญชาการของอิลลูมินาวิเคราะห์สถานการณ์ปัจจุบัน ฟอร์เซคิน หลังจากได้รับสัญญาณการถอยกลับจากอิคลิพส์ ตัดสินใจให้การโจมตีครั้งสุดท้ายต่อทหารอิลลูมินา...",
  str_mission_desc_4001010_long = "คุณติดอยู่กับการพยายามเปิดโคลอสซัส แม้ว่าความพยายามตลอด 17 ปีจะสูญเปล่า\nจู่ ๆ ไวซ์ สาวออโรเรียนก็โผล่มาในโคลอสซัส เมื่อคุณลองใหม่อีกครั้ง\nไวซ์สัญญาว่าจะพาคุณออกไปจากที่นี่เมื่อคุณเอาชนะอิคลิพไซท์ได้ด้วยพลังจิตของคุณ\nสุดท้ายคุณจะได้ออกไปจากโคลอสซัสไหมนะ",
  str_mission_desc_4001020_long = "คุณเอาชนะอิคลิพไซท์ด้วยความสามารถได้อีกครั้ง\nคุณและทีมของไวซ์เป็นเพื่อนกันแล้ว\nไม่อยากจะเชื่อเลยว่าคุณจะมีเพื่อนก่อนจะเยี่ยมเยือนโลกเสียอีก",
  str_mission_desc_4001030_long = "เครื่องสื่อสารเสียหายไปแล้ว อิคลิพไซท์ก็มีจำนวนมากกว่าคุณโดยไม่มีกำลังเสริม\nทุกคนอาจรอดถ้าคุณเปิดใช้งานห้องสตาร์ไลท์",
  str_mission_desc_4001045_long = "คุณเสียสติไปเพราะใช้พลังจิตควบคุมโคลอสซัสมากเกินไป\nออโรเรียนอีกรายอย่างมิสบลังค์มาร่วมแรงร่วมใจกับคุณ\nถึงอย่างนั้น สัญลักษณ์สัญญาณก็ดึงดูดความสนใจของอิคลิพไซท์\nคุณไม่มีทางเลือกนอกจากเริ่มเคลื่อนไหวและหาทางออก",
  str_mission_desc_4001050_long = "คุณพบเป้าหมายของคารอน ซึ่งก็คือวิศวกรโซยา ที่สถานีหลักในทันที\nนอกจากโซยาแล้วยังมีชายหนุ่มที่หายตัวไป\nคุณเมินเฉยไม่ได้จึงบุกฝ่ากลุ่มอิคลิพไซท์เพื่อตามหาเขา\nโชคดีที่เขายังมีชีวิตอยู่!\nถึงอย่างนั้นก็พบว่าเขาบาดเจ็บ และที่จริงแล้ว \"เขา\" เป็นผู้หญิง",
  str_mission_desc_4001060_long = "ในที่สุดคุณก็เข้ามาในเมืองใต้ดินหมายเลข 28\nคารอนพาคุณและเหล่าคนนอกเข้ามาถึงแม้ว่าจะค่อนข้างเข้มงวดก็ตาม\nหลังจากที่คุณเอาชนะพวกหลบหนีได้แล้วก็พาโซรอซลงจอดที่ท่าจอด\nถึงแม้จะมีทรัพยากรจำกัดในเมืองใต้ดิน โคลอสซัสก็ได้รับการเติมเต็มอีกครั้งและค่อย ๆ ฟื้นฟูขึ้น\nด้วยการพักที่พระเจ้าประทานมาให้ คุณรู้สึกโล่งอกและ...สลบเหมือด",
  str_mission_desc_4001070_long = "ออโรเรียนและคุณเอาชนะอิคลิพไซท์ระดับสูงขนาดใหญ่อย่างคราเคนด้วยกันได้\nมันไม่ใช่เวลาที่ควรสังสรรค์เลยเพราะกองทัพแข็งแกร่งของอิคลิพไซท์รอคอยคุณอยู่\nเพื่ออพยพทุกคนไปยังโลกใหม่อย่างปลอดภัย...\nไวซ์ตัดสินใจพยายามเปิดใช้งานโคลอสซัสกับคุณ",
  str_mission_desc_4001095_long = "คุณและไวซ์ควบคุมโคลอสซัสร่วมกัน เมื่อเครื่องยนต์ติด...โซรอซซึ่งมีออโรราปกคลุมอยู่ ก็ตื่นขึ้นอย่างเต็มตัวแล้ว",
  str_mission_desc_4001080_long = "โซรอซจำเป็นต้องอุ่นเครื่องเพราะไม่ได้ใช้มา 17 ปี\nอย่างไรก็ดี อิคลิพไซท์ก็พบพวกคุณโดยไม่ทันตั้งตัว\nการป้องกันโคลอสซัสสำคัญที่สุด!",
  str_mission_desc_4001090_long = "ปฏิบัติการช่วยเหลือที่เป็นไปไม่ได้นั้นยากเกินไป\nไม่หนีและไม่ยอมแพ้ คุณทำได้หรือเปล่า\nเสียงระเบิดจากที่ห่างไกลฟังดูไม่รื่นหูสำหรับไวซ์กับคุณ\nเกิดอะไรขึ้นกับฝั่งคารอนบ้างนะ",
  str_mission_desc_4001100_long = "ความผิดปกติใกล้เข้ามาจากที่คารอนดูแลอยู่\nรีบไปที่เป้าหมายแล้วเตรียมต่อสู้กับศัตรูน่าสะพรึง!\nคารอนและเดย์นาเข้าขากันอย่างกับอะไรดี ทุกคนกลับมาพร้อมหน้าแล้ว!\nมีแสงแห่งความหวังในชะตาอันสิ้นหวัง:\nโซรอสจอดอยู่ที่ท่าจอดใกล้ ๆ นี้",
  str_mission_desc_4001110_long = "โซรอซที่เป็นความหวังในยามทุกข์ยาก\nจะช่วยให้คุณหนีไปได้\nไม่มีใครรู้ว่าจะมีความท้าทายอันยิ่งใหญ่อะไรอีก\nไม่มีเวลาให้คิดมากไปกับอุปสรรคที่เหนือการคาดเดา กันผู้บาดเจ็บและสหายของคุณเพื่อช่วยพวกเขาขึ้นโคลอสซัสตอนนี้ซะ\nปรับตัวไปตามสถานการณ์!",
  str_mission_desc_4001120_long = "คุณบาดเจ็บสาหัสเพราะการโจมตีอันรุนแรงของอิคลิพไซท์\nสหายบางคนของคุณก็ล้มในการต่อสู้ ในขณะที่ทุกคนต่างก็สู้เพื่อเอาชีวิตรอดอย่างเอาเป็นเอาตาย\nสิ่งที่รอคุณอยู่ คือสมรภูมิที่เข้มข้น",
  str_mission_desc_4001130_long = "โซรอซออกตัวตามการคาดหวังของทุกคน\nอย่างไรก็ตาม อิคลิพไซท์ระดับสูงอีกตนอย่างโนซาร์ดก็ปรากฏตัวบนโคลอสซัส\nเปิดฉากการต่อสู้ไม่หยุดยั้ง ทุกคนล้าเกินกว่าจะต่อกรไหว\nสหายบางคนของคุณก็สละชีพเพื่อให้คนที่เหลืออยู่รอดต่อไป",
  str_mission_desc_4002015_long = "ไวซ์จึงโน้มน้าวให้กลับไปที่อิลลูมินากับเธอก่อนเพราะทุกคนพ้นอันตรายแล้ว\nในขณะที่คุณลังเลอยู่นั่นเอง โซรอซที่ถูกทิ้งไม่ได้ใช้งานมา 17 ปีก็ตกลงไปยังพื้นดินด้วยเหตุขัดข้อง\nแต่ถึงอย่างนั้นโนซาร์ดก็ไม่ตายและไล่ล่าคุณไม่ลดละ",
  str_mission_desc_4002010_long = "เสียงดังจากโคลอสซัสที่ตกลงมาเรียกอิคลิพไซท์มานับไม่ถ้วน\nการต่อสู้ครั้งใหม่กำลังมา",
  str_mission_desc_4002035_long = "ไวซ์บาดเจ็บสาหัสเพราะปกป้องคุณจากอิคลิพไซท์ตอนถกเถียงกันอยู่\nในช่วงหัวเลี้ยวหัวต่อสำคัญ กลุ่มโจรก็อ้างว่าซินซาเป็นคนเอาชนะอิคลิพไซท์ได้\nคุณปลอดภัยแล้ว แต่พวกเขาก็อ้างว่าโคลอสซัสเป็นของพวกเขา",
  str_mission_desc_4002020_long = "การต่อสู้เริ่มขึ้นอีกครั้ง แต่คุณต้องพึ่งพาเรดีเซล เวรนช์ที่ไม่รู้ว่าเป็นใคร\nแต่ก็ดีที่ได้รู้ว่าโจรพวกนี้สู้เป็นเหมือนออโรเรียน!",
  str_mission_desc_4002030_long = "การต่อสู้เริ่มขึ้นอีกครั้ง แต่คุณต้องพึ่งพาเรดีเซล เวรนช์ที่ไม่รู้ว่าเป็นใคร\nแต่ก็ดีที่ได้รู้ว่าโจรพวกนี้สู้เป็นเหมือนออโรเรียน!",
  str_mission_desc_4002040_long = "ไม่รู้ว่าซินซาทำไปเพราะใจอ่อนหรือมีแผนกันแน่\nคุณไม่มีคำพูดใดเกี่ยวกับเรื่องนี้นอกจากดูว่าจะเกิดอะไรขึ้นต่อไป\nเขาพาคุณไปที่ฐานเรดีเซล เวรนช์\nถนนเทลสตรีทเส้นนี้เต็มไปด้วยความหมดอาลัยและฉ้อฉล\nเขาพาคุณมาที่นี่ทำไมกัน",
  str_mission_desc_4002050_long = "โลกใบนี้มีลำดับชั้นและมักจะมีมุมมืดที่คุณไม่เคยรู้มาก่อนเสมอ\nความจริงที่คุณกับไวซ์ก็เพิ่งได้ความเข้าใจใหม่เกี่ยวกับเรดีเซล เวรนช์...\nคุณพอจะรู้เจตจำนงของซินซาอย่างน้อยหนึ่งอย่าง นั่นคือ\nช่วยชำระล้างผู้ไร้ทางสู้ ด้วยความช่วยเหลือจากโซรอซ",
  str_mission_desc_4002060_long = "การต่อสู้เป็นไปด้วยดี แต่ทุกคนต่างสงสัยว่าทำไมอิคลิพไซท์ถึงสู้ได้อย่างเด็ดเดี่ยวและเป็นธรรมชาติ\nการปรากฏตัวของอัมบราฮัลก์พิสูจน์ได้ว่าพวกเขาคิดถูก!\nเมื่อกำลังเสริมของอิลลูมินามาถึงแล้ว หนุ่ม ๆ เรดีเซล เวรนช์ก็จากไปอย่างแนบเนียน\nเป็นอีกครั้งที่ชะตาของคุณถูกคนอื่นกำหนด",
  str_mission_desc_4002095_long = "คุณกลับไปยังเมืองใต้ดินหมายเลข 28 กับคารอน และไวซ์กับโซรอซก็ลงจอดอย่างปลอดภัย\nการป้องกันนั้นทะลวงแทบไม่เข้า แต่คารอนและฮิอิโระก็ยังสงสัยว่ามีอิคลิพไซท์หาทางบุกเข้ามาได้\nไม่กี่วันต่อมาไวซ์ก็ฟื้นตัว การพักผ่อนระยะสั้นกลับถูกขัดด้วยวิกฤตครั้งใหม่...\nเมืองใต้ดินเริ่มสั่นไหวและเสียงเตือนดังขึ้น เกิดอะไรขึ้นกันแน่?!",
  str_mission_desc_4002070_long = "อิคลิพไซท์เจาะทะลวงการป้องกันที่มุมอับของเมืองใต้ดินและทุกอย่างก็ตกอยู่ในอันตราย\nวิธีที่ดีที่สุดที่จะปกป้องคนบาดเจ็บและประชาชนได้คือการถอยทัพ คุณทำได้เพียงใช้แผนฉุกเฉินเท่านั้น\nมีปริศนาบางอย่างอยู่ในเหตุการณ์นี้ แต่คุณไม่มีเวลาคิดอย่างละเอียดเลย...",
  str_mission_desc_4002080_long = "ซินซาและอีฟเคยอาศัยอยู่เมืองใต้ดินมาก่อน\nอีฟก็ลด \"ภาพลักษณ์แบบนั้น\" ที่นั่นเช่นกัน\nความจริงคืออะไรกันนะ\nประวัติศาสตร์บอกอะไรเราได้บ้าง\nตอนนี้คุณทำได้เพียงเดินตามซินซาไปแล้วทำคำขอสองสิ่งของเขาให้สำเร็จ",
  str_mission_desc_4002090_long = "คุณถูกคลื่นโจมตีกระหน่ำจากอิคลิพไซท์\nถ้าเป็นอย่างนี้ต่อไป มีหวังทุกคนตกอยู่ในอันตรายใหญ่หลวงแน่!\nด้วยความที่เคยเผชิญกับอันตรายคล้ายคลึงกันแบบนี้ คุณเลยคิดอะไรดี ๆ ออก โคลอสซัสเป็นความหวังสุดท้าย",
  str_mission_desc_4002100_long = "อิคลิพไซท์รวมตัวกันรอบโคลอสซัส คุณควรถอยทัพและทำลายข้อมูลเมืองใต้ดินทั้งหมดให้เร็วที่สุด\nแต่ตอนนี้ยังไม่ถึงเวลากดปุ่มสีแดง!",
  str_mission_desc_4002110_long = "ทุกคนขึ้นโคลอสซัสแล้ว ยกเว้นคารอน\nคุณทิ้งคารอนไว้แบบนี้ไม่ได้แต่ก็เกือบไม่รอดในการต่อสู้แล้ว\nการทอดทิ้งอย่างโหดร้ายนี้หลีกเลี่ยงไม่ได้ แม้ว่าจะตัดสินใจแบบไหนก็ตาม...",
  str_mission_desc_4002120_long = "กดปุ่มสีแดงแล้ว ถอยทัพเดี๋ยวนี้!\nคุณเอาชนะโนซาร์ดที่ฟื้นกลับมาอีกครั้งได้และทำการล้อมทุกตัวที่จะหนีได้\nเมืองใต้ดินหมายเลข 28 คุกรุ่นไปด้วยหมอก ในขณะที่คุณไว้อาลัยให้คารอน...\nรถไฟบินสูงพุ่งออกมาจากไฟ ใช่คารอนหรือเปล่านะ?!",
  str_mission_desc_4003015_long = "ก่อนกำลังเสริมมาถึง คุณสัมผัสได้ว่ามีหนุ่มคนหนึ่งเรียกให้ช่วย เขาเป็นคนของคุณหรือเปล่า\nคุณตั้งใจคว้าโอกาสเพียงเล็กน้อยสืบหาความจริงแม้ว่าจะเป็นการตัดสินใจที่อันตราย!\nไวซ์ตัดสินใจเข้าข้างคุณในครั้งนี้ เคเลสไทต์จะไม่ต้องสู้เพียงลำพังอีกต่อไป",
  str_mission_desc_4003010_long = "แผ่นศิลาที่สร้างขึ้นใหม่ตั้งอยู่บนหน้าผาขณะที่ดวงอาทิตย์ส่องแสงตามปกติ\nทั้งคุณและซินซาต่างสลัดความรู้สึกโหยหาไม่หลุด\nความเปลี่ยนแปลงใหม่ทำให้ต้องแปลกใจ เมื่อกองทหารอิลลูมินาทำลายความสงบเสียนี่\nไวซ์กับคุณกลับไปหาทีมหลังจัดการกับการโจมตีที่คาดไม่ถึงของอิคลิพไซท์\nคนของเรดีเซล เวรนช์จากไปแล้ว หายไปในความรกร้าง...",
  str_mission_desc_4003020_long = "เมนเดลสันที่ปกป้องโมดูลคลังปัญญาถูกชูมเมอร์โจมตี\nแม้ว่าเขาจะพยายามต่อต้านสุดกำลังแต่ก็เปลี่ยนชะตาที่จะถูกฉีกร่างขาดรุ่งริ่งไม่ได้\nเมื่อไม่มีทหารเลย เขาจึงต้องล่าถอยพร้อมกับเรียกให้คุณช่วยในระหว่างที่วิ่งหลบหนีไปด้วย",
  str_mission_desc_4003030_long = "\"เวลามีไม่มากแล้ว\" ชายปริศนาเรียกร้องให้ช่วย\nการขุดค้นโคลอสซัสที่เรลิก ES-0096-F7 หยุดนิ่งไปเหนือความคาดหมาย ฮิอิโระก็หายไปเช่นกัน\nคุณและไวซ์เปิดใช้งานโคลอสซัสกะทันหันเพื่อค้นหาหัวหน้าของคุณ\nไม่เพียงแค่พิสูจน์ความสามารถในการสั่งการโคลอสซัสของคุณเท่านั้น\nยังเป็นการช่วยชีวิตสหายของคุณเพิ่มขึ้นอีกด้วย",
  str_mission_desc_4003031_long = "ติดตามตอนต่อไป",
  str_mission_desc_4003040_long = "สมาชิกทีมขุดค้นถูกหลอมกลืนเป็นอิคลิพไซท์!\nคุณต้องตั้งสติเพื่อสู้กับอดีตสหายของตนเอง\nในขณะที่กำแพงไฟของออโรเรียนในเรลิกสึกกร่อนด้วยพลังมืด\nอวิดัซผู้ยิ่งใหญ่ประกาศด้วยพลังอันกล้าแกร่งว่าเธอจะกวาดล้างผู้ทรยศและแก้แค้นให้แก่มารดา",
  str_mission_desc_4003050_long = "คุณไม่สามารถช่วยผู้รอดชีวิตคนสุดท้ายได้ ชะตากรรมได้กำหนดให้ดาร์กเคนนิ่งเป็นเช่นนี้\nบุปผาพิรุณอาจช่วยวิญญาณของเขาได้...\nซากุระชำระล้างร่างกายเขาและปลูกฝังศรัทธาแห่งออโรเรียนลงไปในจิตใต้สำนึกของเขา\nเขาได้บอกสารสำคัญแก่คุณว่า \"พวกมัน\" ยังคงอยู่ ณ ที่นี้",
  str_mission_desc_4003060_long = "ในที่สุดคุณก็พบเมนเดลสันแล้ว ซึ่งขณะนี้เขากำลังบาดเจ็บสาหัส\nเขาถูกทหารของตนเองจับเพราะพลังที่แข็งแกร่งของชูมเมอร์\nการต่อสู้ใกล้เข้ามาแล้ว...",
  str_mission_desc_4003070_long = "ดูเหมือนว่าการแสดงนั้นได้จบลงไปอย่างลับ ๆ ณ ที่ไหนสักแห่ง\nอย่างไรก็ตาม ชูมเมอร์ต้องการที่จะแสดงให้ถึงจุดสูงสุดกว่านี้อีก เพื่อฉีดพลังความมืดไร้ขีดจำกัดเข้าไปยังแกนกลางของโคลอสซัส\nไวซ์เห็นอะไรบางอย่างถึงแม้ว่าจะมีหมอกหนาปกคลุมไปทั่ว\nคุณอาจจะต้องเล่นไปตามสัญชาตญาณ หรือไม่ก็หาทางหยุดการแสดงนี้",
  str_mission_desc_4003080_long = "คุณกลัวจนอกสั่นขวัญแขวน แต่การตายอย่างมีเกียรติย่อมดีกว่าการมีชีวิตอยู่อย่างไร้ศักดิ์ศรี\nเคเลสไทต์ถูกกำจัดไปหมดแล้ว ดังนั้นการปกป้องอนาคตของทุกคนนั้นสำคัญที่สุด!\nตอนนี้ชูมเมอร์ก็มีคลังปัญญาไว้ในการครอบครองแล้ว อีกไม่นานก็คง...\nคุณต้องสู้ต่อไปเพื่อจัดการทุกอย่างให้เสร็จสิ้น!",
  str_mission_desc_4003090_long = "เวลานี้เงาในความคิดของคุณได้ยืนอยู่ตรงหน้าคุณแล้ว ดูแปลกหน้า แต่ก็คุ้นเคย\nชายผู้บอบบางคนนี้คือเอคโค่ของเรลิกโคลอสซัส เมนเดลสัน\nระหว่างนั้น ฮิอิโระและโซยาก็ถูกฝังอยู่ภายใต้ซากโบราณ\nเสียงคำรามก่อนตายของโคลอสซัสก้องกังวานไปทั่วซากโบราณ...\nพวกเขาต้องเร่งฝีเท้าให้เร็วขึ้นก่อนที่จะเกิดการถล่มครั้งที่สอง",
  str_mission_desc_4003091_long = "ติดตามตอนต่อไป",
  str_mission_desc_4003100_long = "ระบบส่วนใหญ่ตัดสัญญาณเนื่องจากความเสียหายที่ชูมเมอร์ก่อขึ้น\nการค้นหาตำแหน่งของฮิอิโระและโซยาเป็นเรื่องที่ยากมาก พวกเขาต้องหาทางหนีด้วยความสามารถของตนเอง\nคุณและไวซ์มุ่งหน้าไป\nทำภารกิจที่สำคัญต่อไปกับเมนเดลสัน",
  str_mission_desc_4003110_long = "คุณอยู่ ณ สถานที่ซึ่งเคยเก็บโมดูลคลังปัญญาไว้ และชูมเมอร์...\nอาจจะเฝ้ารอคุณอยู่ที่นี่\nหยุดเธอซะ! ร่างกายของเมนเดลสันเริ่มอ่อนแอลงเรื่อย ๆ เนื่องจากพลังงานความมืด\nนี่อาจจะ...เป็นการต่อสู้ครั้งสุดท้ายของเขาก็ได้",
  str_mission_desc_4003120_long = "ชูมเมอร์หนีไปแล้ว และทาบาอัดก็รอคุณอยู่ที่นั่น\nเพราะความช่วยเหลือจากฮิอิโระ ร่างกายของทาบาอัดได้สลายไปท่ามกลางซากุระ\nเมนเดลสันได้จบชีวิต บรรลุนิมิตสุดท้ายของเขาและได้ทิ้งเบาะแสไว้กับคุณ มันคือ\nโมดูลคลังปัญญา ยูนิตเติบโตอิสระและโมดูลควบคุมไฟ...สิ่งเหล่านี้จะเป็นสิ่งที่ชูมเมอร์หมายไว้ต่อไป",
  str_mission_desc_4003145_long = "ขณะนี้ โมดูลคลังปัญญาถูกล็อกไว้ที่มุมไหนสักแห่งในคลังสารของลูโมโพลิส\nดวงตาที่กำลังจับจ้องเข้ามาใกล้หมายความว่าอิคลิพไซท์จะต้องเข้าโจมตีลูโมโพลิสในเร็ว ๆ นี้แน่",
  str_mission_desc_4004015_long = "เมืองในท้องฟ้ามหึมาปรากฏขึ้นต่อหน้า ดูเหมือนว่าเป้าหมายของคุณ ซึ่งก็คือโมดูลปัญญาอีกอันหนึ่ง จะอยู่ที่นั่น\nชูมเมอร์ ศัตรูเก่าของคุณได้สังเกตเห็นลูโมโพลิสแล้ว ดูท่าว่าสถานการณ์จะไม่ดีแล้ว\nภารกิจหลักของคุณตอนนี้คือการโน้มน้าวคาร์ลีน กัปตันหน่วยผู้พิทักษ์\nทันใดนั้นเอง การสนทนาของคุณก็ถูกขัดจังหวะโดยการจู่โจมโดยไม่ทันตั้งตัว",
  str_mission_desc_4004010_long = "จากคำให้การของชาวบ้านในลูโมโพลิสชั้นล่าง พวกอิคลิพไซท์มักจะจู่โจมพวกเขาที่บริเวณทางทิศตะวันออกอยู่เสมอ หน่วยผู้พิทักษ์ได้เข้าไปสืบสวนการโจมตีดังกล่าวแล้ว แต่คุณเลือกที่จะไปตรวจสอบบริเวณทิศตะวันตกเพราะสัญชาตญาณของคาร์ลีน สายลับที่แฝงตัวอยู่ในเมืองแอบลือกันว่า \"เราจะได้รับอิสรภาพตามที่เคยสัญญาไว้ หากเราได้สิ่งนั้นมา\"",
  str_mission_desc_4004020_long = "พบอิคลิพไซท์ในบริเวณตะวันตก! ตัวที่หนีไปได้ ได้เรียกปิศาจขึ้นมาทุกที่\nหัวหน้าหน่วยลูโมโพลิสชั้นล่าง เกิร์ตเซิร์ด กล่าวว่าประชาชนนอกเมืองต้องได้รับการคุ้มครอง\nดูเหมือนว่าเขาจะเคยเป็นอัศวินที่เลื่องชื่อเสียงด้วย...",
  str_mission_desc_4004030_long = "พิกัดที่โซรอซให้นั้นชี้ไปที่สวนลูโมโพลิส ซึ่งอยู่ในเขตที่มีการคุ้มกันแน่นหนาในลูโมโพลิส\nเมื่อดาร์กโอเวอร์มาถึง\nอวิดัซผู้ยิ่งใหญ่ ที่คืบคลานในความมืดจะต้องมุ่งชิงแกนกลางของลูโมโพลิสเป็นแน่\nก่อนที่จะเกิดมรสุม คุณสัมผัสได้ว่าเรื่องใหญ่กำลังจะเกิดขึ้น",
  str_mission_desc_4004040_long = "ดาร์กโอเวอร์เปลี่ยนทหารคุ้มกันลูโมเป็นอิคลิพไซท์\nสิ่งนี้ไม่ควรอยู่ที่นี่ ลูโมโพลิสชั้นล่างกำลังอยู่ในอันตราย!\nทหารคุ้มกันลูโมขวางคุณไว้ตอนที่คุณไล่ล่าไชร์ลงไปยังสวนลูโมโพลิส\nเรื่องนี้เป็นเรื่องของแกนกลางและชะตากรรมแห่งลูโมโพลิส ดังนั้น\nไวซ์โน้มน้าวกัปตันหน่วยผู้พิทักษ์คาร์ลีนอย่างสุดความสามารถเพื่อให้มาสนับสนุนภารกิจของคุณ",
  str_mission_desc_4004050_long = "ทางเขตตะวันตกมีรายงานการเคลื่อนไหว! ดูเหมือนว่าครั้งนี้จะเป็นอิคลิพไซท์เลเวลสูง!\nตามล่าและกำจัดมันให้หมด\nคาร์ลีนดูไม่สบายใจอีกแล้ว\nไม่ว่าจะเกิดอะไรขึ้น คุณจะต้องผ่านมันไปให้ได้",
  str_mission_desc_4004060_long = "เชลต์เข้าร่วมต่อสู้พร้อมกับน้องสาวของเธอ แต่สถานการณ์ยังเข้าข้างคุณอยู่\nหมอกควันพรางสองพี่น้องอิคลิพไซท์ที่กำลังมุ่งหน้าอย่างรวดเร็วไปยัง\nที่พักอาศัยของชนชั้นสูงลูโมบนเมืองชั้นบน!\nระวัง! ทหารคุ้มกันทุกคน กลับไปประจำการป้องกันเดี๋ยวนี้!",
  str_mission_desc_4004085_long = "เกิร์ตเซิร์ดกำลังถอดรหัสโมดูลคลังปัญญาในคลังสารลูโมโพลิส\nเชลต์บอกเขาว่าเธอจะหลอกล่อศัตรูไปยังเมืองชั้นบนเพื่อถ่วงเวลาไว้\nคาร์ลีนรู้ทันทีว่ามันคงเหมือนเป็นการฆ่าตัวตายถ้าหากเธอหนีไปยังเมืองชั้นบน\nเธอจึงขอให้ราฟาเอลค้นหาในทิศตรงข้ามขณะที่เธอกำลังตามล่าสองพี่น้องอิคลิพไซท์",
  str_mission_desc_4004100_long = "ระหว่างนั้นเอง ราฟาเอลไม่พบบุคคลน่าสงสัย\nแต่เธอพบกัปตันทีมเกิร์ตเซิร์ดที่เพิ่งทำภารกิจสำเร็จมา\nเขาถือกล่องที่มีผ้าห่ออยู่ ข้างในนั้นมันมีอะไรกันนะ...",
  str_mission_desc_4004110_long = "ด้วยการตามรอยเลือด คุณได้มาถึงสถานที่ใกล้เมืองชั้นบน พี่น้องอิคลิพไซท์ไม่มีทางหวนกลับแล้ว\nพวกเขาหันไปขอความช่วยเหลือกับชายปริศนาอย่างสิ้นหวังเพียงเพื่อจะถูกบอกว่า\nพวกเขาเลือกได้แค่ว่าจะเอาชนะศัตรูหรือมีชีวิตรอดต่อไปเท่านั้น",
  str_mission_desc_4004120_long = "\"ฉันจะเสกให้กลายเป็นดอกแดนดิไลออน...จงโบยบินไปซะ\"\nชายปริศนาโกหกและใช้พลังแปลงกายพี่น้องเป็นมอนสเตอร์น่าเกลียดน่ากลัว\nพลังมหาศาลนั้นเป็นเครื่องมือทรงพลังแต่ก็เป็นเครื่องทรมานที่ไร้มนุษยธรรม\nพี่น้องที่ทรมานมานานถูกลดลงจนกลายเป็นเถ้า วิกฤตน่ารำคาญนี้ถูกแก้ไขแล้ว\nภารกิจของเกิร์ตเซิร์ดสำเร็จแล้ว ตอนนี้ชูมเมอร์ได้โมดูลคลังปัญญาฉบับสมบูรณ์ไปแล้ว",
  str_mission_desc_4005015_long = "ผู้บัญชาการกองทัพอิลลูมินาไม่สามารถละทิ้งตำแหน่งของตนและช่วยเหลือคุณไม่ได้อีก\nคุณต้องตามชูมเมอร์และค้นหายูนิตเติบโตอิสระด้วยตัวเอง\nหัวหน้าหน่วยข่าวกรองฟิลิชีนำเบาะแสมาให้\nในขณะที่คาร์ลีนทำตามคำสั่งพิเศษจากลูโมโพลิส\nเธอจะไล่ตามชูมเมอร์กับคุณ",
  str_mission_desc_4005010_long = "จำนวนโคลอสซัสที่ร่วงหล่นชี้ให้เห็นถึงจำนวนเคเลสไทต์ที่สละชีพไป\nตอนนี้คุณอยู่ที่เรลิกโคลอสซัสของผู้ไร้นาม 13 เสียที แต่พบว่าตัวเองอยู่ในซากโบราณ\nกรอนรู ผู้อำนวยการวิจัยของอิลลูมินา ทำการวิจัยที่นี่\nยูนิตเติบโตอิสระตกใส่โคลอสซัสจริง ๆ ด้วย!\nคุณต้องใช้พลังของเคเลสไทต์ถ้าจะแกะมันออกจากโคลอสซัส",
  str_mission_desc_4005020_long = "ภายในโคลอสซัสที่ล่มสลายนั้นเสียหายอย่างมาก เส้นทางไปยังยูนิตเติบโตอิสระขรุขระและวุ่นวาย\nการสั่นไหวผิดปกติประกาศให้รู้ว่าชูมเมอร์มาถึงแล้ว\nเธอปล่อยพลังออกมาโดยไม่สกัดกั้นและล้อเลียนพวกโง่เขลาและขี้แพ้อ่อนแอ",
  str_mission_desc_4005060_long = "จิตใจของคนตายเป็นดั่งบทกวี เฉกเช่นเดียวกับเสียงเพลง สัมผัสของความว่างเปล่าครอบคลุมพื้นที่และกาลเวลา\nโมดูลที่สองเป็นของขวัญสุดท้ายที่เขามอบให้ ตอนนี้โคลอสซัสเริ่มเปล่งประกายจากช่วงพักอีกครั้ง\nอย่างไรก็ตาม ชูมเมอร์ก็มาจากเบื้องบน\nกรอนรูเรียกโทรนมาเพื่อป้องกันให้คุณถอยทัพ ปกป้องโมดูลที่คุณมี",
  str_mission_desc_4005070_long = "เสียงจากลำโพงดังขึ้น\nกรอนรูส่งข้อความมา สั่งให้ทุกคนถอยทัพด้วยความรวดเร็ว แต่ชูมเมอร์พูดตัดขึ้นมา\n\"นำโมดูลมาให้ข้าที่โคลอสซัสร้างภายใน 30 นาที ไม่งั้นกรอนรูเตรียมตัวตายได้เลย\"\nจะทำตามคำสั่งหรือช่วยกรอนรูดีล่ะ?",
  str_mission_desc_4005090_long = "เหลือเวลาเพียงแค่ 5 นาทีก่อนถึงเส้นตาย\nโซรอซยังไม่ได้จากไปไหนหรือลงมา คุณได้ตัดสินใจแล้ว\nระหว่างนั้นเองกรอนรูก็ไม่ได้นั่งรอให้ตัวเองชะตาขาด เธอแข็งแกร่งเกินกว่าที่ใครจะสามารถจินตนาการได้",
  str_mission_desc_4005120_long = "แม้แต่สำหรับพวกเคเลสไทต์ การได้ครอบครองพลังของอิคลิพไซท์ทำให้แข็งแกร่งได้ขนาดนี้เลยหรือ\nชูมเมอร์เอาชนะได้อย่างง่ายดายราวกับปอกกล้วยเข้าปาก แต่สิ่งที่เหนือความคาดหมายของเราคือการที่เธอรักษาสัญญาอันน่าเบื่อนั้นไว้ แต่เธอก็กล่าวไว้เช่นกันว่าการไว้ชีวิตของคุณนั้นเป็นเพียงเพราะความเมตตาและความเวทนา แต่ศึกครั้งหน้าของคุณจะเป็นการต่อสู้ถึงตาย",
  str_mission_desc_4006015_long = "คุณต้องตามหาโมดูลควบคุมไฟต่อในทันทีถึงแม้ว่าจะไม่ได้รับความช่วยเหลือจากอิลลูมินาหรือลูโมโพลิสเท่าไรนัก\nคุณตัดสินใจที่จะเดินทางไปยังระเบียงเสียงกระซิบที่ห่างไกลด้วยตัวของคุณเอง\nระเบียงเสียงกระซิบนั้นเหมือนกับเขาวงกตอันซับซ้อน และในขณะที่คุณกำลังหัวเสียอยู่นั้น เจ้าแห่งเงา ผู้ปกครองแห่งอัมบราตันได้ส่งเพื่อนร่วมทางมากฝีมือมากับคุณ\nโดยเชโอลจะเป็นผู้นำทางคุณสำรวจเขาวงกตแห่งนี้เอง",
  str_mission_desc_4006010_long = "ปฏิบัติการล่าผ่านไปด้วยดีถึงแม้ว่าคุณจะมีมิสเชโอลสนับสนุนอยู่ระยะไกลเท่านั้น\nรอยเท้าของกองทัพแปลกตาจากรอยเท้าของอิคลิพไซท์...\nเกิร์ตเซิร์ดนี่เอง คนทรยศที่เคยเป็นวีรบุรุษในลูโมโพลิสมาก่อน\nเขาเชื่อคำโกหกที่ว่าเชลต์ตายแล้ว ความเกลียดชังจึงเติบโตขึ้นในจิตใจ",
  str_mission_desc_4006050_long = "ปรากฏว่าคุณพบทางไปยังโมดูลควบคุมไฟที่ถูกต้องแล้ว แต่คุณยังประมาทไม่ได้ เกิร์ตเซิร์ดดูจะแอบซุ่มอยู่ข้างหน้า นี่จะเป็นการต่อสู้ครั้งสุดท้ายกับเขาหรือไม่",
  str_mission_desc_4006060_long = "เกิร์ตเซิร์ดที่มุ่งมั่นจะแก้แค้นคุณพ่ายแพ้แม้ว่าจะใช้พลังมืด\nในที่สุดเขาก็รู้ว่าความจริงที่ว่านั้นเป็นคำโกหก ชูมเมอร์และชายปริศนาปั่นหัวเขาเพื่อใช้งาน\nโชคร้ายที่สายไปเสียแล้ว แดนดิไลออนได้จากไปกับสายลมแล้ว...\nเกิร์ตเซิร์ดเศร้าโศกมากจนตัดสินใจพาคุณไปยังที่ชูมเมอร์อยู่",
  str_mission_desc_4006085_long = "หลายสิบปีก่อนหลังจากวิกฤตดาร์กโอเวอร์จบลง เกิร์ตเซิร์ดเป็นอัศวิน เขาไม่รู้สึกดีกับการแต่งงานกับลูกสาวชนชั้นสูง จุดเริ่มต้นของเทพนิยายของเขาไม่มีตอนจบที่มีความสุข จนมาเจอเชลต์ แม้ว่าจะเป็นทางเลือกที่ผิดก็ตาม",
  str_mission_desc_4006070_long = "อิคลิพส์รู้อยู่แล้วว่าเกิร์ตเซิร์ดทรยศ\nโมดูลควบคุมไฟอยู่ในกำมือของคุณได้โดยการชี้แนะของเกิร์ตเซิร์ด\nในเวลานั้น ที่รอคอยคุณอยู่คือสหายเก่า โนซาร์ด ผู้ทรงพลังหลังถูกแปลงเปลี่ยนเป็นชายปริศนา",
  str_mission_desc_4006110_long = "คุณสัมผัสได้ว่าชูมเมอร์นอนรออยู่ที่ไหนสักแห่งที่ปลายทาง\nคุณได้รู้เรื่องตัวระบุโมดูลจากเกิร์ตเซิร์ด แต่นั่นหมายความว่าชูมเมอร์ก็รู้เรื่องนี้เช่นกัน!",
  str_mission_desc_4006120_long = "คารอนที่ขับเคลื่อนรถไฟสู่ยมโลกด้วยตัวเองทำให้ชูมเมอร์คิดว่าเป็นกองกำลังเสริมของอิลลูมินา\nชายปริศนาและชูมเมอร์ลังเลที่จะเสี่ยง พวกเขาจึงจากไปและทิ้งร่างของเกิร์ตเซิร์ดไว้\nคาร์ลีนเผาร่างของเขา ซึ่งจากนี้เขาจะล่องลอยไปกับเชลต์...\nในขณะเดียวกัน ลูโมโพลิสก็กำลังเผชิญหน้ากับวิกฤตที่หนักหน่วงกว่าเดิม",
  str_mission_desc_4007015_long = "โคลอสซัสสีดำของชูมเมอร์มาถึงน่านฟ้าลูโมโพลิส\nลูโมโพลิสชั้นล่างที่ไม่มีโล่คุ้มกันกำลังตกอยู่ในอันตราย โชคดีที่มีผู้บัญชาการกองทัพอิลลูมินาอยู่ใกล้เคียงมาช่วย\nชูมเมอร์จะได้ชดใช้สิ่งที่เขาทำในภายหลัง หลังภัยด่วนนี้ชูมเมอร์จะถูกสะสางบัญชี!",
  str_mission_desc_4007010_long = "ยิ่งไปกว่านั้น อิคลิพไซท์ก็มารวมตัวกันในลูโมโพลิสชั้นล่างด้วย\nเมื่อขาดกำลังสนับสนุนจากทหาร ทุกคนก็ทำได้แค่แยกกันดำเนินการ\nอย่างไรก็ดี คุณก็จะพบการต่อสู้ที่ไร้จุดจบอีกอยู่ดี",
  str_mission_desc_4007050_long = "ปฏิบัติการกำจัดและช่วยเหลือในลูโมโพลิสชั้นล่างสำเร็จได้อย่างรวดเร็วเพราะยุทธวิธีของคุณ\nการเชื่อมโยงกันระหว่างคุณกับโซรอซอ่อนแอมากแต่น่าจะปลอดภัย\nในขณะที่ทุกคนโล่งใจนั่นเอง คาร์ลีนก็ได้รู้ว่าเมืองชั้นบนถูกโจมตี!",
  str_mission_desc_4007060_long = "โคลอสซัสสีดำเป็นภัยต่อเกาะลอยทั้งหมด\nแต่ทุกคนเร่งไปเมืองชั้นบนได้ทันเวลาและนำ มารา โซล ลงมา\nการต่อสู้จบลงด้วยความโอหังของชูมเมอร์ ทว่าตอนนั้นเองคุณก็ได้ยินเสียงเรียกให้ช่วย...\nโคลอสซัสถูกโจมตีเองงั้นเหรอ?!",
  str_mission_desc_4007085_long = "คุณพยายามทุกทางเพื่อเชื่อมต่อกับโซรอซแต่ล้มเหลว\nไม่อยากเดาสิ่งที่แย่ที่สุด ความสำคัญแรกคือการกลับไปสนับสนุนโซรอซโดยทันที\nและในตอนที่ทุกคนหมดหนทางแล้วเพราะไม่มียานพาหนะ\nคาร์ลีนก็ขับเรือเหาะที่ปล้นมาหาคุณราวกับเป็นผู้กอบกู้",
  str_mission_desc_4007070_long = "โซรอซยุ่งเหยิงหลังการบุกรุกของอิคลิพไซท์\nบทสรุปที่แย่ที่สุดพอจะคาดเดาได้ แต่คุณเชื่อว่าโซรอซยังมีชีวิตอยู่\nหาโซรอซก่อนที่ชูมเมอร์จะเจอเรา!",
  str_mission_desc_4007100_long = "คุณสัมผัสได้ถึงโซรอซหลังจากการต่อสู้อันดุเดือด\nมันไม่ใช่แค่เสียงเพรียกแล้ว แต่เป็นข้อความซ้ำ ๆ\nหรือจะหมายความว่า...โซรอซมาถึงจุดจบแล้ว",
  str_mission_desc_4007110_long = "คุณสัมผัสไม่ได้ถึงโซรอซมาสักพักแล้ว\nและความเจ็บปวดที่สั่นคลอนอยู่ในใจเป็นเครื่องย้ำเตือนความผิดแปลกนี้\nเป็นอย่างที่คิด เมื่อชูมเมอร์บอกว่า โซรอซนั้น...",
  str_mission_desc_4007120_long = "เพื่อโซรอซแล้ว คุณต่อสู้กับชูมเมอร์ที่แข็งแกร่งขึ้นอย่างสุดกำลัง!\nการค้นพบที่น่าประหลาดใจที่สุดคืออิคลิพไซท์ระดับสูงอีกตัว ฟอร์เซคิน เป็นหนึ่งในสหายที่อยู่กับอิลลูมินาก่อนหน้านี้!\nยังไม่ทันได้ตกใจ โคลอสซัสสีดำก็ชาร์จพลังเต็มแล้ว\nวิเวียนวางแผนเสี่ยงชีวิตเพื่อให้คุณหนี\nหลังการปะทะที่ร้ายแรงซึ่งนำมาสู่ความว่างเปล่า คุณจะต้องเผชิญกับอะไรต่อไปอีก...",
  str_mission_desc_4008015_long = "เสียงร้องปลุกคุณจากความฝัน\nคุณอยู่ในอวิดัซกับไวซ์ที่มาช่วยคุณอย่างไม่เคยลังเลใจ\nตอนนี้คุณต้องหาทางออก",
  str_mission_desc_4008020_long = "\"ไม่ควรมีใครถูกทิ้งไว้ข้างหลัง\"\nพอคิดแบบนี้แล้วคุณก็ตัดสินใจช่วยหัวหน้าวิเวียนก่อน!\nในขณะที่บุคคลลึกลับผู้นั้นนำทางคุณต่อไป",
  str_mission_desc_4008030_long = "ในขณะที่คุณก้าวไปข้างหน้า พลันร่างกายก็รู้สึกประหลาด\nแต่ไม่มีเวลาตรวจว่ามีอะไรแปลกไป คุณต้องหาวิเวียนให้เร็วที่สุด\nขณะเดียวกันนั้นเอง คุณก็มั่นใจว่าคาร์ลีนต้องทุ่มเทต่อสู้สุดกำลังแน่",
  str_mission_desc_4008060_long = "ความผิดปกติภายในร่างกายยากที่จะเพิกเฉย บางอย่างกำลังจะเกิดขึ้น\nเพราะเวลาต่อสู้ แม้แต่อิคลิพไซท์ยังเหมือนกับมองไม่เห็นคุณเลย\nแล้วในเงามืดนั้นเกิดอะไรขึ้น",
  str_mission_desc_4008070_long = "ในขณะที่คูรีบุกทะลวงไปข้างหน้า คุณก็ไปถึงที่ซึ่งหัวหน้าวิเวียนถูกจับไว้\nและมีโซลฟอล ศัตรูทรงพลังรอคุณอยู่\nหลังกำจัดมันแล้ว บุคคลลึกลับก็เผยรูปร่างที่แท้จริงและช่วยคุณกำจัดเหตุประหลาดที่รู้จักกันในชื่อ \"เมล็ดพันธุ์\"",
  str_mission_desc_4008085_long = "ลูโมโพลิส คาร์ลีนไม่ได้รับการสนับสนุนจากลอร์ด\nอย่างไรก็ตาม เธอก็ไม่ได้เสียความมุ่งมั่นที่จะใช้อาวุธอัลติเมท\nคาร์ลีนตัดสินใจเปิดใช้งานแดโมคลีสในห้องควบคุมด้วยตัวเอง!",
  str_mission_desc_4008090_long = "ถึงแม้หัวหน้าวิเวียนจะได้รับการช่วยเหลือ หนีตอนนี้ก็คงไม่เป็นการฉลาดเท่าไรนัก\nนี่เป็นจุดเปลี่ยนของการต่อสู้ และกลุ่มกลายเป็นกำลังสำคัญที่จะตัดกำลังศัตรูจากภายใน\nคุณไปไหนไม่ได้...ต้องหยุดป้องกันแล้วโจมตีแทน!",
  str_mission_desc_4008100_long = "การต่อสู้เริ่มร้อนระอุขึ้นแล้วและชูมเมอร์ก็รู้ถึงการกระทำของคุณเสียที\nเหมือนกับว่าการต่อสู้อันดุเดือดนี้จะถูกกำหนดให้เกิดขึ้นในบริเวณแกนกลางโคลอสซัสสีดำ...ห้องบังคับการ!\nในขณะที่แดโมคลีสก็กำลังก่อพายุครั้งสุดท้าย",
  str_mission_desc_4008130_long = "การยืนอยู่ต่อหน้าลูโมโพลิสตามที่ต้องการมาเนิ่นนาน ชูมเมอร์จะคิดอะไรอยู่ตอนนี้\nจิตใจเธอจะเต็มไปด้วยอดีตหรือความเสียใจกันนะ\nคุณควรไปต่อ ทรัพยากรทั้งหมดอยู่ข้างหน้าแล้ว!",
  str_mission_desc_4008140_long = "การต่อสู้ครั้งสุดท้ายที่ห้องบังคับการ อิคลิพไซท์ที่ขวางทางคุณจะถูกกำจัดอย่างรวดเร็ว\nสักพักชูมเมอร์ก็รู้สึกถึงพลังทำลายล้างโดยที่ไม่รู้เรื่องแดโมคลีสมาก่อน\nคาร์ลีนเปิดฉากโจมตีปืนใหญ่เบาและทะลวงอวิดัซด้วยความช่วยเหลือของคุณ\nในที่สุดพายุสีดำก็ถูกโค่นลง",
  str_mission_desc_4008155_long = "ในขณะที่การต่อสู้กำลังจบลง\nบุคคลสำคัญหลายคนที่จะมีอิทธิพลต่อทิศทางของโลกก็เดินจากเบื้องหลังไปยังด้านหน้าของเวที\nกระแสน้ำวนที่ใหญ่กว่ากำลังก่อตัวขึ้น คุณจะนำทางชะตากรรมสุดท้ายของคุณอย่างไร",
  str_mission_desc_4009015_long = "หลังจากเหตุการณ์อันตรายจบลง คาร์ลีนก็ได้รับบทลงโทษชั่วคราว และงานชิ้นสำคัญในการค้นหาต้นตอของเหตุการณ์นี้จึงมาตกอยู่ที่คุณ\nต้องหา \"ซาก\" ของชูมเมอร์ให้เจอ และเรื่องนี้จะต้องคลี่คลายให้ได้เสียก่อนถ้าคุณอยากซ่อมแซมโซรอซ\nบังเอิญแท้ ๆ ที่อวิดัซไปตกในสถานที่ที่คุ้นเคยแต่ไม่คุ้นชินอย่าง... อีราเวล",
  str_mission_desc_4009020_long = "อีราเวลที่รอคุณอยู่แตกต่างจากสถานที่ที่คุณเห็นในนิมิต\nมันทั้งแห้งแล้ง ขาดชีวิตชีวา ปนเปื้อนไปด้วยพลังงานประหลาด และมีฝูงอิคลิพไซท์อยู่เต็มไปหมด",
  str_mission_desc_4009030_long = "หลังจากที่โคลอสซัสลำนี้ตกในอีราเวล สมาชิกเรดีเซล เวรนช์ได้เข้าร่วมการตามหายานลำนี้พร้อมกับคุณ\nซินซากับบ็อปเปอร์หวังว่าจะได้วัตถุดิบจากซากยาน แต่สุดท้ายแล้วกลับคลาดกันกับคณะของเพื่อน ๆ",
  str_mission_desc_4009040_long = "คุณพบกับซินซาอีกครั้งโดยไม่ได้คาดหมาย แต่ท่าทางเขาจะไม่รู้ตัวว่าตัวเองอยู่ที่ไหน\nทว่านี่ไม่ใช่เวลาจะถามไถ่อะไรกันทั้งนั้น สิ่งแรกของงานนี้คือการเริ่มค้นหาอวิดัซ...",
  str_mission_desc_4009050_long = "แม้ว่าการสำรวจจะดำเนินไปอย่างราบรื่นมากขึ้นเมื่อได้รับความช่วยเหลือจากซินซา แต่อากาศก็เย็นเยือกขึ้นทุกวินาที\nบรรยายได้เพียงว่า ตอนนี้สถานที่แห่งนี้ได้กลายเป็นรังอิคลิพไซท์ไปซะแล้ว...",
  str_mission_desc_4009070_long = "คุณพบเหรียญตราที่ทำให้พิสูจน์ได้ว่าอิคลิพไซท์ตัวหนึ่งนั้น เดิมทีเคยเป็นออโรเรียนมาก่อน\nดูเหมือนศัตรูรูปร่างน่าเกลียดตรงหน้าคุณนี้ ครั้งหนึ่งก็เคยเป็นเหมือนสหายชาวออโรเรียนของคุณ\nคุณต้องจบความปวดร้าวของมัน",
  str_mission_desc_4009085_long = "ชูมเมอร์กำลังพักฟื้นจากบาดแผลที่สาหัสอยู่ภายในกระสวยรักษา และฝันถึงตัวเองเมื่อนานมาแล้ว\nชูมเมอร์จากในอดีตได้เล่าให้ฟังถึงความมุ่งมั่นและความปรารถนา เหมือนกับเธอในตอนนี้ที่รอการเกิดใหม่",
  str_mission_desc_4009090_long = "คุณสัมผัสได้ถึงความเศร้าหมองและสิ้นหวังที่แผ่ซ่านออกมาจากส่วนลึกของอีราเวล\nนี่เป็นภาพลวงหรือเปล่า หรือว่าความเป็นจริง อวิดัซเองก็ร่ำไห้ด้วยความเจ็บปวดเหมือนกันเหรอ",
  str_mission_desc_4009130_long = "เมื่อเอาชนะอิคลิพไซท์ในอีราเวลได้แล้ว ในที่สุดคุณก็ใกล้จะถึงจุดที่อวิดัซตก\nทว่าสมาชิกองค์กรลับอย่างทรู ออเดอร์ก็ดูจะมีธุระที่นี่เช่นกัน พวกนั้นพากันรวบรวมอะไรบางอย่างอยู่ในเงามืด...",
  str_mission_desc_4009140_long = "เมื่อได้พบกันอีกครั้ง ฟอร์เซคินดูแปลกใจเล็กน้อยที่คุณยังไม่ได้ \"แปลงกาย\"\nก่อนที่คุณจะทันได้สะสางกันให้รู้ดำรู้แดง เธอก็หนีไปแล้ว\nโดยก่อนที่เธอจะหนีไป เธอได้หลุดเบาะแสสำคัญออกมา จนทำให้รู้ว่าชูมเมอร์ยังมีชีวิตอยู่",
  str_mission_desc_4010015_long = "ในขณะเดียวกัน ที่ศูนย์การแพทย์ลูโมโพลิส...\nฟิลิชีแวะมาเยี่ยมวิเวียนและบอกเธอว่าคุณกำลังตามล่าฟอร์เซคินอยู่\nแล้วทั้งสองคนยังพูดคุยกันอีกสักพักถึงเรื่องความสัมพันธ์ระหว่างฟอร์เซคินกับจอมทัพอีกด้วย...",
  str_mission_desc_4010020_long = "คุณเข้าสู่ตัวยานอวิดัซ เพื่อที่จะไล่ล่าฟอร์เซคินและตามหาชูมเมอร์ต่อไป\nแม้ว่าอวิดัซจะตกนานแล้ว แต่ซากของมันก็ยังคงแผ่พลังความมืดที่ทรงพลังประมาณหนึ่งออกมา\nที่น่าวิตกยิ่งกว่านั้นก็คือ อิคลิพไซท์บนยานต่างรีบพากันวิ่งหนี ราวกับมีอะไรบางอย่างที่ชั่วร้ายกำลังตื่นขึ้น...",
  str_mission_desc_4010030_long = "ชูมเมอร์ยังคงพักฟื้นจากบาดแผล เธอตื่นแต่เช้าและกำลังจับอิคลิพไซท์กินเพื่อฟื้นฟูพลังงาน!\nถึงแม้ว่าคุณจะยังไม่เข้าใจที่มาที่ไปเรื่องที่เธอเสื่อมทรามไปได้ขนาดนี้ แต่คุณก็ต้องไปต่อเพื่อตามหาศัตรูอมตะของคุณ!",
  str_mission_desc_4010070_long = "ศัตรูของคุณล้มตายแล้วอีกครั้ง\nความโหดร้ายและไม่แยแสต่อศีลธรรมของฟอร์เซคินทำให้คุณเหลืออด คุณต้องตามหาเธอกับชูมเมอร์ให้เจอ!\nขณะเดียวกัน ในเส้นทางแห่งการไล่ล่าของคุณ ข้อมูลเพิ่มเติมเกี่ยวกับอดีตของชูมเมอร์ก็ได้เปิดเผยออกมา...",
  str_mission_desc_4010085_long = "ในวันนั้นเมื่อสิบเจ็ดปีก่อน ชูมเมอร์ได้กลายเป็นทูตแห่งการล่มสลายของอีราเวล\nเธอเปล่งเสียงแซ่ซ้องอันโกลาหลในนามของอิคลิพส์ บ้างก็จำใจต้องยอมรับ ส่วนที่เหลือก็ต่อสู้ต่อต้านจนตัวตาย\nแต่ในท้ายที่สุด เคเลสไทต์ก็ถึงจุดจบ เธอใช้เลือดสด ๆ ของคนในชนเผ่าตัวเองที่เพิ่งหลั่งไหลมาบรรลุเป้าหมายที่แสวงหามาเนิ่นนาน นั่นก็คือวิวัฒนาการมืด",
  str_mission_desc_4010090_long = "หลังจากได้รู้ถึงอดีตคร่าว ๆ ของชูมเมอร์ คุณก็เข้าใจว่าภาพในความฝันที่คุณเห็นนั้นตรงกับโศกนาฏกรรมในความทรงจำที่ห่างไกลนั้น\nเส้นทางการแก้แค้นได้ดำเนินมานานมากพอแล้ว ถึงเวลาต้องหาตัวชูมเมอร์ให้พบและจบเรื่องราวทั้งหมดลงสักที",
  str_mission_desc_4010130_long = "ในที่สุดฟอร์เซคินก็ผลักดันให้ชูมเมอร์ไปถึงจุดที่ไม่สามารถย้อนกลับได้ และบังคับให้เธอต้องก้าวผ่านพัฒนาการด้านพลังครั้งยิ่งใหญ่ของเธอ...\nอย่างไรก็ตาม ผลก็คือเธอสูญเสียการควบคุมทั้งหมด เธอมาปรากฏตัวต่อหน้าคุณอีกครั้ง ในสภาพที่บ้าคลั่งเกินบรรยาย\nมีเพียงแค่ฝ่ายเดียวเท่านั้นที่จะรอดชีวิตจากการต่อสู้ครั้งนี้ได้",
  str_mission_desc_4010140_long = "คุณเอาชนะชูมเมอร์ผู้บ้าคลั่งได้ แต่ดูเหมือนภายในตัวเธอจะมีพลังที่แผ่ซ่านไม่หยุด\nฟอร์เซคินต้องการนำเมล็ดพันธุ์กลับคืนมา จึงสูบพลังงานออกจากตัวเธอจนหมด\nในที่สุด ชูมเมอร์ซึ่งมีชีวิตอยู่เพื่อสงครามลัทธิอันบิดเบี้ยวที่บูชาความยุติธรรมและการเกิดใหม่ก็ต้องตายลงท่ามกลางกระแสอิคลิพไซท์ที่ถาโถมเข้ามา...\nเช่นเดียวกับพวกพ้องของเธอเมื่อหลายปีก่อน",
  str_mission_desc_4010155_long = "ทุกคนสามารถหลบหนีออกมาจากอวิดัซได้อย่างปลอดภัยและเดินทางออกจากอีราเวลด้วยความช่วยเหลือจากเรดีเซล เวรนช์\nนอกจากนี้คุณยังเชื่อมต่อโมดูลคลังปัญญาที่ได้รับมาจากชูมเมอร์เข้ากับโซรอซได้สำเร็จอีกด้วย และเท่าที่ผ่านมาการซ่อมแซมยานก็ดูจะมีความหวัง\nตอนนี้คุณชักจะอยากรู้แล้วสิ ว่าการผจญภัยครั้งต่อไปจะพาคุณไปที่ไหน...",
  str_mission_desc_4101015_long = "ขณะนี้โซรอซขาดเสถียรภาพเมื่อไม่มีเทมเพลตเอคโค่ ถ้ายังเป็นแบบนี้ต่อไป อาจเกิดความเสียหายตามมาได้ คุณกับไวซ์ตัดสินใจไปยังเมืองใต้ดินที่อยู่บริเวณพรมแดนของดินแดนรัตติกาลนิรันดร์ ตามเบาะแสที่ได้รับจากโมดูลคลังปัญญา",
  str_mission_desc_4101020_long = "เมื่อไปถึงเมืองใต้ดินหมายเลข 80 ที่พรมแดนของดินแดนรัตติกาลนิรันดร์ คุณก็รู้ว่าอิคลิพไซท์ได้ยึดสถานที่แห่งนี้เป็นของตัวเองไปแล้วตั้งแต่ที่อิลลูมินาทิ้งไป พลังความมืดที่เข้มข้นทำให้แทบเป็นไปไม่ได้เลยที่จะใช้ลูมินาติกส์ ภายใต้สถานการณ์เหล่านี้ คุณจึงเริ่มต้นการสืบสวนด้วยความระมัดระวัง",
  str_mission_desc_4101030_long = "คุณกับไวซ์เดินทางลึกเข้าไปในเมืองใต้ดินดังกล่าว ร่องรอยสงครามมีให้เห็นได้ทุกแห่งหนภายใต้ชั้นฝุ่นหนาที่สะสมมายาวนานหลายปี ในซากปรักหักพัง คุณค้นพบว่ามีโมดูลโคลอสซัสทิ้งไว้ที่นี่บางส่วน...",
  str_mission_desc_4101040_long = "ชิ้นที่สามารถใช้ซ่อมแซมเทมเพลตเอคโค่ของโซรอซได้นั้นฝังอยู่ในเครื่องจักรที่ห้องหลัก คุณพยายามนำมันออกมา ซึ่งทำให้แกนพลังงานของเมืองใต้ดินแห่งนี้หยุดทำงาน เมื่อไม่มีไฟฟ้า เมืองใต้ดินแห่งนี้จึงเริ่มพังทลาย และมีอิคลิพไซท์ระดับสูงตัวหนึ่งปรากฏขึ้นในขณะที่เมืองกำลังถล่มลง",
  str_mission_desc_4101055_long = "คุณกับไวซ์เผชิญหน้ากับอิคลิพไซท์ระดับสูงตัวนั้นด้วยความยากลำบากมากขึ้นเพราะพลังความมืด ขณะเดียวกันก็พยายามหาโอกาสหลบหนี ทว่าอิคลิพไซท์ตัวนี้ขวางทางพวกคุณไว้อย่างสิ้นเชิง ในวินาทีสำคัญนี้เองที่ไรน์ฮาร์ตเข้ามาช่วยชีวิตพวกคุณเอาไว้ และคุณก็ต้องแปลกใจที่อิคลิพไซท์ระดับสูงตัวนั้นดูท่าทางจะเป็นสหายร่วมรบเก่าแก่ของเธอ",
  str_mission_desc_4101060_long = "ไรน์ฮาร์ตนำคุณไปตามเส้นทางหนีอีกเส้นทางหนึ่งเพื่อขึ้นสูงพื้นดิน แต่พลังความมืดกลับหนักอึ้งขึ้นเรื่อย ๆ เมื่อคุณเข้าใกล้พื้นดินมากขึ้น ตอนนั้นเป็นเวลากลางคืนแล้ว การต่อสู้มีแต่จะยากขึ้นนับจากนั้น",
  str_mission_desc_4101070_long = "เมื่อคุณรบเร้าอย่างต่อเนื่อง ไรน์ฮาร์ตจึงเริ่มเล่าเรื่องราวจากในอดีตให้ฟังอีกครั้ง ครั้งหนึ่งสหายร่วมรบของเธอเคยต่อสู้ในสงครามที่ยากลำบากกับเธอในเมืองใต้ดินหมายเลข 80 เธอฝ่าวงล้อมของศัตรูออกมาเพื่อขอความช่วยเหลือ แต่กลับพบว่าอิลลูมินาได้ทิ้งพวกเธอเอาไว้ข้างหลังเพื่อรักษาชีวิตประชากรส่วนใหญ่เอาไว้",
  str_mission_desc_4101080_long = "คุณขึ้นไปถึงระดับพื้นดินท่ามกลางความมืดมิดก่อนรุ่งสางพอดี ฟอร์เซคินกับอิคลิพไซท์ระดับสูงนั้นรออยู่ในความเงียบงัน ไรน์ฮาร์ตขอความช่วยเหลือจากคุณ เธออยากพยายามนำตัวสหายร่วมรบกลับคืนมาอีกครั้ง",
  str_mission_desc_4101090_long = "ฟอร์เซคินกระตุ้นความเกลียดชังที่ฝังลึกอยู่ในตัวอิคลิพไซท์ระดับสูงและทำให้รูปลักษณ์ของมันเปลี่ยนแปลงไป สงครามมรณะกำลังจะเกิดขึ้น ไรน์ฮาร์ตได้รับบาดเจ็บอย่างรุนแรงเพื่อปกป้องคุณ ในสถานการณ์ที่สิ้นหวังนี้ เธอยังคงต้านทานอย่างกล้าหาญ...",
  str_mission_desc_4101105_long = "เมื่อมีภัยจากกองทัพอิคลิพไซท์ ไวซ์กับคุณจึงนำตัวไรน์ฮาร์ตที่บาดเจ็บสาหัสกลับไปที่โซรอซ และมุ่งหน้าไปยังสถานพยาบาลของอิลลูมินา ระหว่างทาง ไรน์ฮาร์ตจดจำอะไรบางอย่างได้จากในอดีต ดูเหมือนว่าความเปลี่ยนแปลงที่มีความสำคัญมหาศาลกำลังก่อตัวขึ้นภายในเมืองใต้ดินที่แน่นหนาของอิลลูมินา...",
  str_mission_desc_4201015_long = "ตามเบาะแสที่คุณได้รับมาไปเลย คุณจะได้ออกเดินทางสู่อีราเวลเพื่อค้นหาฐานซ่อมบำรุงโคลอสซัส ด้วยความหวังว่าจะเจอวิธีฟื้นฟูโคลอสซัสให้กลับสู่สภาพเดิมได้ แต่หลายอย่างไม่เป็นไปตามแผน...",
  str_mission_desc_4201020_long = "บนเส้นทางสู่อีราเวล โซรอซถูกกลุ่มอิคลิพไซท์โจมตี โดยมีลักษณะเหมือนวางแผนไว้ล่วงหน้า ในระหว่างการต่อสู้ การโจมตีของอิคลิพไซท์ได้ทำให้แผงควบคุมของโคลอสซัสเสียหาย และโซรอซก็เริ่มตกลงสู่เบื้องล่าง...",
  str_mission_desc_4201040_long = "ยานของคุณไปตกที่ลานกว้างบริเวณฐานของหอคอยแห่งหนึ่ง จากข้อมูลของโซรอซ นี่คือ \"ลานจอดยาน\" ดังนั้นฐานที่คุณหาอยู่น่าจะอยู่ไม่ไกล ได้เวลาหยิบเครื่องตรวจจับโลหะและเริ่มออกสำรวจแล้ว",
  str_mission_desc_4201050_long = "ขณะที่คุณเริ่มการค้นหา ก็มีอิคลิพไซท์ส่วนหนึ่งติดตามมาอย่างเงียบ ๆ รอบหอคอยสีขาว เพื่อค้นหาต่อไป คุณจึงระเบิดทางเข้าลานจอดยานโดยอาศัยความช่วยเหลือจากบาร์ตัน และป้องกันไม่ให้พวกมันเข้ามาใกล้มากกว่านี้",
  str_mission_desc_4201060_long = "จากทางเข้าที่ค้นพบ คุณได้เข้าสู่ฐานขนาดใหญ่ใต้เมืองอีราเวล และพบร่องรอยของเคเลสไทต์จำนวนมากที่เคยอาศัยอยู่ที่นี่มาก่อน ซึ่งคุณไม่เคยรู้ว่ามีอยู่",
  str_mission_desc_4201070_long = "หลังจากการต่อสู้ที่ดุเดือด คุณหมดสติไปเพราะขาดออกซิเจน บังเอิญว่าคุณเชื่อมต่อกับปัญญาประดิษฐ์ที่ควบคุมฐานแห่งนี้ได้ คุณอาศัยความช่วยเหลือของปัญญาประดิษฐ์เพื่อเปิดระบบระบายอากาศ และแล้วก็ได้สติอีกครั้ง ภายใต้การนำทางของปัญญาประดิษฐ์ คุณจึงทำการสำรวจฐานต่อไป...",
  str_mission_desc_4201090_long = "คุณมาถึงพื้นที่กว้างภายในฐาน และมีร่องรอยว่าครั้งหนึ่งพื้นที่นี้เคยเป็นที่รู้จักในชื่อเขตแดนผู้ถูกเนรเทศ และผู้ที่ถูกเนรเทศมาที่นี่ในอดีตก็คือพวกเคเลสไทต์ คุณพบปืนเลเซอร์ที่เคยเป็นของเคเลสไทต์ผู้หนึ่ง และนำมาใช้ปราบอิคลิพไซท์ได้สำเร็จ",
  str_mission_desc_4201100_long = "เมื่อถูกอิคลิพไซท์ที่ทรงพลังไล่ล่า คุณจึงไม่เหลือทางเลือกอื่นนอกจากต้องใช้อุปกรณ์ป้องกันของฐานใต้ดินในการรับมือ แต่อุปกรณ์เหล่านี้ไม่ได้มีไว้โจมตีอิคลิพไซท์เท่านั้น แต่ยังเป็นอันตรายกับออโรเรียนด้วยเช่นกัน นอกจากนี้ไวซ์เองก็ได้รับบาดเจ็บและตกอยู่ในสภาวะหมดสติอันแปลกประหลาดที่เรียกว่า \"สูญเสียการรับรู้\" อีกด้วย",
  str_mission_desc_4201115_long = "ในการหาทางรักษาไวซ์และซ่อมแซมโซรอซ คุณจึงออกสำรวจแกนกลางของฐานแห่งนั้นต่อไป คุณพบเครื่องจักรประหลาดที่เรียกว่าระบบวงแหวน ซึ่งมีแต่คุณที่เป็นเคเลสไทต์เท่านั้นที่สามารถใช้งานได้ จากเครื่องจักรนี้ คุณจึงเริ่มมองเห็นความลับที่ไม่มีผู้ใดล่วงรู้ขึ้นมาราง ๆ",
  str_mission_desc_4201120_long = "คุณหาบันทึกเรื่องการปลุกออโรเรียนจากการสูญเสียการรับรู้ในระบบวงแหวนจนเจอ แต่เนื่องจากความเก่าของมัน ทำให้คุณเข้าถึงข้อมูลได้เพียงบางส่วนเท่านั้น คุณตัดสินใจสำรวจลึกเข้าไปอีกเพื่อหาเบาะแสเพิ่มเติม",
  str_mission_desc_4201140_long = "ในขณะที่ระบบฐานรีบูตขึ้นมากะทันหัน คุณก็สูญเสียการควบคุมฐานและตกเป็นเป้าการโจมตีของมัน เหล่าผู้พิทักษ์ของฐานแห่งนี้ได้ตื่นขึ้นมาจากการหลับลึก และคุณต้องเอาชนะพวกมันให้ได้เพื่อยึดการควบคุมฐานกลับคืนมา",
  str_mission_desc_4201155_long = "เมื่อกลับมาควบคุมฐานได้อีกครั้ง การรีบูตก็เสร็จสมบูรณ์ ทำให้คุณสามารถเข้าถึงทุกอย่างได้ ท่ามกลางเสียงสั่นสะเทือนอึกทึก หอคอยก็เริ่มยืดโครงสร้างสูงขึ้น เผยให้เห็นรูปลักษณ์ดั้งเดิมของมัน ผลงานสร้างสรรค์ของเทคโนโลยีโบราณทั่วทั้งแอสตราเริ่มส่งเสียงสะท้อนประหลาดออกมา...",
  str_mission_desc_4202015_long = "เมื่อได้รับสิทธิ์การเข้าถึงระดับผู้ดูแลระบบไปยัง Obelisk of Return คุณจะได้เรียนรู้เกี่ยวกับอุปกรณ์ที่เรียกว่า \"Chord Link\" ที่สามารถช่วย Vice ได้ อย่างไรก็ตาม เนื่องจาก Obelisk of Return อยู่ในสภาพทรุดโทรม จึงไม่มีข้อมูลเกี่ยวกับอุปกรณ์นี้ในระบบ ดังนั้นคุณจะต้องไปที่พื้นที่ซึ่งเป็นที่ตั้งของมันเพื่อตรวจสอบเพิ่มเติม",
  str_mission_desc_4202020_long = "ขณะที่คุณค้นหา Chord Link บาร์ตันตามรอย Forsakin เข้าไปในหอคอย อย่างไรก็ตาม เขาหลงทางใน Obelisk of Return อันกว้างใหญ่...",
  str_mission_desc_4202040_long = "เมื่อทราบว่าบาร์ตันไล่ล่ามา ฟอร์เซคินก็ละทิ้งแผนการของตัวเองที่จะติดตามคุณและใช้กำลัง คุณต้องแข่งกับเวลาเพื่อเจาะระบบควบคุมการเข้าถึงของคอร์ดโซนที่โดนฟอร์เซคินโจมตี",
  str_mission_desc_4202050_long = "คุณหนีไปที่คอร์ดโซนเพื่อหลบเลี่ยงฟอร์เซคิน แต่การเจาะระบบควบคุมการเข้าถึงทำให้ระบบป้องกันตัวของคอร์ดโซนทำงานขึ้นมา เมื่อกับดักทั้งหมดในเส้นทางทำงาน คุณจึงพบกับอุปสรรคที่ท้าทาย ขณะอยู่ในช่วงวิกฤติ คุณได้ทำให้กับดักระเบิดออก และยับยั้งไม่ให้ฟอร์เซคินเข้าสู่คอร์ดโซนได้ชั่วครู่",
  str_mission_desc_4202060_long = "เพื่อปกป้องไวซ์และเอาชนะฟอร์เซคิน บาร์ตันซึ่งได้รับบาดเจ็บสาหัสตัดสินใจที่จะแปลงร่างตัวเองโดยใช้คอร์ดลิงก์ ในช่วงเวลานี้ ฟอร์เซคินได้สั่งให้อิคลิพไซท์พังประตู เพื่อซื้อเวลาให้บาร์ตัน คุณจึงต้องเผชิญหน้ากับฟอร์เซคิน",
  str_mission_desc_4202070_long = "ขณะที่บาร์ตันประสานพลังเสร็จสมบูรณ์ เขาก็ได้รับพลังใหม่ และก้าวออกมาจากคอร์ดลิงก์เพื่อร่วมมือกับคุณในการสู้กับฟอร์เซคิน เมื่อพลิกสถานการณ์ได้ ฟอร์เซคินก็หลบหนีไปท่ามกลางความโกลาหล โดยมีบาร์ตันตามหลังไปติด ๆ...",
  str_mission_desc_4202085_long = "ความสำเร็จของ Barton ทำให้คุณมั่นใจ และคุณใส่ Vice ไว้ใน Chord Link เพื่อซิงโครไนซ์ จากการสอดแนมของ Obelisk of Return คุณเห็น Eclipsites รวบรวมกองทัพขนาดใหญ่นอกหอคอยและ Aurorians จากทุกด้านต่อสู้อย่างหนัก เมื่อคุณเห็นสิ่งนี้ คุณตัดสินใจที่จะขับไล่ Eclipsites เหล่านี้ออกจาก Eraveil ด้วยมือของคุณเอง",
  str_mission_desc_4202090_long = "เนื่องจากต้องใช้เวลาอีกนานกว่าที่ไวซ์จะตื่นขึ้นมา คุณกับคาร์ลีนจึงไม่มีทางเลือกและต้องทิ้งเธอไว้ในคอร์ดลิงก์เพื่อไล่ฟอร์เซคินออกไปจากหอคอย ในเวลานี้ ภาพด้านนอกหอคอยมีแต่ความสยดสยอง มีอิคลิพไซท์จำนวนมหาศาลกำลังต่อสู้กับออโรเรียนอย่างหนักหน่วง ราวกับว่าได้ย้อนเวลากลับสู่วันที่อีราเวลถูกโจมตีเมื่อ 17 ปีก่อน...",
  str_mission_desc_4202100_long = "เมื่ออิคลิพไซท์โจมตีอย่างไม่ลดละ ทุกคนจึงมุ่งมั่นพยายามเต็มที่เพื่อต้านไว้ให้ได้ จากนั้นอิคลิพส์ก็เปิดไพ่ที่เหนือกว่า มันคือปืนใหญ่พลังความมืด อาวุธที่ไม่คาดคิดนี้ทำให้คุณเสียเปรียบทันที ความหวังที่จะได้รับชัยชนะดูเลือนรางลงอย่างรวดเร็ว...",
  str_mission_desc_4202115_long = "ในขณะที่ทุกคนที่อยู่นอก Obelisk of Return ยังคงถูกขังอยู่ในสนามรบ เพื่อพลิกกระแส Reinhardt แนะนำให้ทิ้งบางส่วนไว้ข้างหลังเพื่อเป็นทางเบี่ยงเบนความสนใจในขณะที่เธอและคุณซุ่มโจมตี Eclipsites เพื่อปกป้อง Eraveil คุณตัดสินใจร่วมมือกับ Reinhardt",
  str_mission_desc_4202130_long = "เมื่อ Reinhardt และ Forsakin ถูกขังอยู่ในสนามรบ กระแสน้ำก็ยังไม่เปลี่ยน เมื่อรู้สึกถึงวิกฤตที่ใกล้เข้ามา คุณตัดสินใจกลับไปที่ Obelisk of Return และยึดการเข้าถึง Core Ring เพื่อเปิดใช้งานอาวุธสูงสุดของ Obelisk of Return นั่นคือ Chord of the Law",
  str_mission_desc_4202140_long = "เพื่อเข้าถึงวงแหวนแกนกลางได้ คุณต้องเผชิญหน้ากับหน่วยผู้พิทักษ์ตามลำพัง แต่คุณไม่สามารถเอาชนะพวกมันได้ ขณะที่กำลังจะพ่ายแพ้ ไวซ์ที่เพิ่งฟื้นจากการสูญเสียการรับรู้ก็มาปรากฏตัวอยู่เคียงข้างคุณพร้อมด้วยพลังใหม่ คุณสองคนจับมือกันปราบหน่วยผู้พิทักษ์และในที่สุดก็เปิดใช้งานคอร์ดแห่งบัญญัติได้",
  str_mission_desc_4202155_long = "\"ของขวัญ\" ที่ปรมาจารย์ฟรานซิสทิ้งไว้ให้คุณ ช่วยให้คุณเปิดใช้คอร์ดแห่งกฎได้สำเร็จ ทำให้ Eclipsites ทั้งหมดอยู่ห่างจาก Obelisk of Return และทำให้การต่อสู้สิ้นสุดลง ไม่สามารถเปิดใช้งานได้อีกเนื่องจากไม่มีพลังงาน Obelisk of Return กลายเป็นอนุสาวรีย์แห่งประวัติศาสตร์ และทุกคนสงสัยว่าจะเกิดอะไรขึ้นกับมัน...",
  str_mission_desc_4203015_long = "จู่ๆ ร่างกายของ Vice ก็เริ่มเปล่งแสงประหลาด ซึ่งเป็นผลข้างเคียงที่เป็นไปได้ของการใช้ Chord Link ด้วยความกังวลเกี่ยวกับสถานการณ์ คุณติดต่อวิเวียนโดยหวังว่าเธอจะสามารถระบุต้นตอของปัญหาได้",
  str_mission_desc_4203020_long = "ด้วยความกังวลในความปลอดภัยของ Vice คุณตกลงที่จะช่วยทีมนักวิจัยจาก Illumina ตรวจสอบฟังก์ชันใหม่ของ Soroz ในระหว่างการสืบสวน นักวิจัยได้ค้นพบข้อมูลการต่อสู้โบราณจำนวนมหาศาล ตอนนี้พวกเขาต้องการให้คุณเข้าถึงข้อมูลนี้โดยใช้ Battle Simulator ของ Illumina และทำการวิจัยเพิ่มเติมเกี่ยวกับข้อมูลนี้",
  str_mission_desc_4203030_long = "คุณทำการทดสอบหลายครั้งโดยใช้ Battle Simulator ซึ่งเป็นอุปกรณ์ขั้นสูงที่ใช้สร้างสถานการณ์การต่อสู้ที่เกือบจะสมบูรณ์แบบ หลังจากได้เห็นการทำงานของเครื่องจำลองแล้ว Reinhardt เชื่อว่าการสร้างการต่อสู้ที่ซับซ้อนยิ่งขึ้น อุปกรณ์นี้สามารถใช้เพื่อการฝึกฝนได้",
  str_mission_desc_4203040_long = "คุณเข้าสู่ Battle Simulator อีกครั้ง แต่สภาพแวดล้อมภายในถูกเปลี่ยนเป็น Dark Zone ภายในสถานการณ์จำลองที่มืดมิดและไม่เป็นมิตรนี้ เป้าหมายของคุณคือเอาชนะ Eclipsites และฝ่าวงล้อมของพวกมันให้ได้",
  str_mission_desc_4203050_long = "การใช้ภูมิประเทศเพื่อสร้างความได้เปรียบเล็กน้อย ในที่สุดคุณก็เอาชนะ Eclipsites จำลองสุดท้ายได้ คุณและพันธมิตรของคุณพังทลายและฟกช้ำดำเขียวออกมาจาก Battle Simulator หลังจากได้รับชัยชนะจากการต่อสู้อย่างหนัก และพบว่า Reinhardt กำลังพูดคุยกับนักวิจัยคนอื่นๆ คุณได้ยินส่วนหนึ่งของบทสนทนาของพวกเขาและค้นพบว่า Reinhardt ใช้ชีวิตผ่านการต่อสู้ที่คุณเพิ่งประสบเป็นการส่วนตัว...",
  str_mission_desc_4203060_long = "คุณกลับไปที่เครื่องจำลอง และสภาพแวดล้อมก็เปลี่ยนไปอย่างมากอีกครั้ง Aurorians ในการจำลองใช้อาวุธที่คุณไม่เคยเห็นมาก่อนและกำลังต่อสู้กับ Eclipsites ที่กระหายเลือดระลอกแล้วระลอกเล่า ขณะที่พวกมันล้มมอนสเตอร์ทีละตัว โลกเสมือนจริงก็ดูจะสิ้นหวังมากขึ้นเรื่อยๆ...",
  str_mission_desc_4203070_long = "ภายในการต่อสู้จำลอง โศกนาฏกรรมของสงครามวันสิ้นโลกทำร้ายความรู้สึกของคุณทั้งหมด ทหารที่สิ้นหวัง Eclipsites ที่ออกอาละวาด และสัตว์ประหลาดปีศาจที่คุณไม่เคยเห็นล้อมรอบตัวคุณ... ทันใดนั้น เกิดข้อผิดพลาดขึ้นในเครื่องจำลอง และเมื่อคุณกำลังจะตกอยู่ภายใต้การโจมตีอันชั่วร้ายของ Jormungand Soroz ก็แทรกจิตสำนึกของมันเข้าไป การต่อสู้และดึงคุณออกมา เมื่อตั้งสติได้ก็ต้องตกใจเมื่อรู้ว่า...",
  str_mission_desc_4203085_long = "สภาวิทยาศาสตร์ ซึ่งเป็นองค์กรที่เก็บความลับที่เก็บไว้อย่างดีที่สุดของสหพันธ์อิลลูมินา ได้เชิญคุณและไรน์ฮาร์ดมาพบกับพวกเขาเป็นการส่วนตัว ไม่ว่าแรงจูงใจของพวกเขาคืออะไร พวกเขาก็เข้าใจสภาพของโซรอซได้ดีที่สุดในตอนนี้ เมื่อคุณเข้าไปในห้องประชุม ความรู้สึกไม่สบายใจปรากฏขึ้นมาครอบงำคุณ ทันใดนั้น Reinhardt ก็วางมือของเธอบนไหล่ของคุณเบาๆ ทำลายความตึงเครียดที่กดขี่อยู่ทั่วห้อง",
  str_mission_desc_4203090_long = "ในตอนท้ายของการประชุม คุณและ Algol มีข้อตกลงบางอย่าง ตามคำขอของเขา คุณได้เริ่มต้น Mind Link กับ Guardian One ซึ่งเป็นเครื่องจักรโบราณที่อยู่ในความครอบครองของสหพันธ์อิลลูมินา การทำเช่นนี้จะเป็นประโยชน์ต่อทั้งสองฝ่าย: นักวิจัยของ Illumina จะมีโอกาสสังเกตปฏิสัมพันธ์ของ Caelestite กับอุปกรณ์โบราณ และคุณจะมีโอกาสขอความช่วยเหลือจาก Guardian One",
  str_mission_desc_4203100_long = "ในกระบวนการสร้าง Mind Link กับ Guardian One คุณตระหนักว่าแม้จะมีมานานนับไม่ถ้วน ปัญญาประดิษฐ์นี้มีบุคลิกเหมือนเด็ก เช่นนี้ มันจะเชื่อถือเฉพาะผู้ที่มีปฏิสัมพันธ์กับมันด้วยความซื่อสัตย์และยุติธรรมเท่านั้น หลังจากสัมผัสได้ถึงความกังวลของคุณที่มีต่อโซรอซ Guardian One จะรีบช่วยคุณกอบกู้สติของโซรอซทันที",
  str_mission_desc_4203110_long = "Guardian One นำคุณไปสู่สนามรบจำลองที่ Soroz ตั้งอยู่ ผลที่ตามมาของหายนะโบราณจากยุคก่อนอยู่ต่อหน้าคุณ ซึ่ง Eclipsites ยังคงเดินเตร่อยู่บนดาวเคราะห์ที่ไร้ชีวิต เมื่อรู้ว่าการจำลองใกล้จะจบลงแล้ว คุณต้องค้นหาเพื่อนรักของคุณท่ามกลางซากปรักหักพังของโลกที่กำลังจะตายก่อนที่ทุกอย่างจะพังทลายลง",
  str_mission_desc_4203120_long = "ในซากปรักหักพังของโลกที่แตกสลาย ในที่สุดคุณก็พบ Soroz และเข้าถึงฐานข้อมูลของมันได้ คุ้นเคยกับสิ่งต่างๆ รอบตัวคุณ แต่ไม่แน่ใจเวลาหรือสถานที่ที่สิ่งเหล่านั้นมีอยู่ ในที่สุดอาการมึนงงของคุณก็สลายไปเมื่อ Guardian One บอกคุณว่าได้ค้นพบบันทึกโบราณจำนวนหนึ่งภายในเทอร์มินัล ที่นี่ Caelesites อยู่ไกลจากบ้าน เร่ร่อนไปในทิศทางที่ไร้จุดหมาย...",
  str_mission_desc_4203130_long = "Guardian One บอกคุณว่าในการซ่อมแซม Soroz ก่อนอื่นคุณต้องป้อนความทรงจำและแก้ไขข้อผิดพลาดในข้อมูล ด้วยความช่วยเหลือของ Guardian One มันควรจะเป็นงานง่ายๆ ขณะเข้าสู่ความทรงจำของ Soroz คุณจะเห็นบันทึกของเทอร์มินัลมากขึ้นเรื่อยๆ ในนั้น พวก Caelestite ดูเหมือนจะมีจำนวนน้อยลงเรื่อยๆ...",
  str_mission_desc_4203140_long = "ด้วยความช่วยเหลือของ Guardian One คุณสามารถล้างข้อผิดพลาดในฐานข้อมูลของ Soroz ได้สำเร็จ ขณะที่ใจของคุณยังคงจดจ่ออยู่กับบันทึกเทอร์มินัล คุณตัดสินใจเข้าถึงข้อมูลเหล่านั้นอีกครั้ง ในบันทึก คุณได้เห็นปาฏิหาริย์: ภายใต้การดูแลของ Caelestites Colossi เกิดและได้รับความรู้สึก หลังจากปาฏิหาริย์สั้น ๆ นี้มาถึงการรอคอยอันยาวนาน ช่วงเวลาที่ยาวนานและไร้ซึ่งเหตุการณ์ใด ๆ ที่ต้องใช้สมาธิทุก ๆ ออนซ์ของคุณไปให้ถึงที่สุด ทันใดนั้น ฉากที่คุ้นเคยก็ปรากฏขึ้นต่อหน้าคุณ: Eraveil",
  str_mission_desc_4203155_long = "หลังจากออกจากโลกเสมือน คุณจะกลับไปที่ห้องประชุมอีกครั้ง สภาวิทยาศาสตร์ได้เริ่มอภิปรายเกี่ยวกับเหตุการณ์ที่พวกเขาเพิ่งพบเห็น พวกเขาเชื่อว่า Soroz ใช้งานได้อีกครั้ง แต่ได้ข้อสรุปว่าความรู้สึกของ Colossus เป็นเพียงผลจากอุบัติเหตุเท่านั้น เพื่อให้สติของโซรอซกลับคืนมาอย่างแท้จริง คุณต้องเดินทางไปยังที่ที่ห่างไกลยิ่งกว่านั้น...",
  str_mission_desc_4204015_long = "เมื่อได้รับความไว้วางใจจากไซบอร์กต่อสู้เปราะบางของสภาวิทยาศาสตร์ งานต่อไปของคุณคือการติดต่อกับกองทหารอิลลูมินาที่ประจำการอยู่ในเมืองทไวไลท์ ที่นั่น คุณต้องแลกเปลี่ยนดรอยด์เป็นทรัพยากรที่จำเป็นสำหรับการฟื้นฟูสติของโซรอซ คุณไม่เคยได้ยินเกี่ยวกับเมืองนี้ ซึ่งตั้งอยู่ที่แนวหน้าอิลลูมินา คุณประหลาดใจมากที่พบว่าคาร์ลีนอยู่ที่นั่นในงานมอบหมายนอกสถานที่",
  str_mission_desc_4204020_long = "เมือง Twilight ตั้งอยู่ใกล้ซากปรักหักพัง Aurora และอยู่ติดกับเขต Eternal Night เป็นแหล่งรวมตัวของกลุ่มทหารต่างๆ อัศวินลูโมที่ประจำการอยู่ที่นี่ได้ติดต่อกับคาร์ลีนแล้ว ดูเหมือนว่าเบเร็ตต้าและอิงเกลมีความเข้าใจที่แตกต่างกันอย่างมากเกี่ยวกับสถานที่ห่างไกลและโดดเดี่ยวแห่งนี้ เมื่อ Eclipsites เริ่มโจมตี วัตถุเปราะบางในมือของคุณก็เริ่มส่งเสียงแปลกๆ...",
  str_mission_desc_4204030_long = "เสียงแปลกๆ ปลุกคุณจากความฝัน และโซรอซเกือบถูกฌอน \"ถอด\" ปรากฎว่า Sean รีบมาจาก Twilight หลังจากได้รับข้อความเกี่ยวกับการมาถึงของคุณเมื่อไม่นานมานี้ แผนของเขาคือการต้อนรับคุณในขณะเดียวกันก็ดำเนินงาน \"กำจัด\" ตามปกติ ซึ่งรวมถึงการกวาดล้าง Eclipsites ออกจากพื้นที่รอบๆ Twilight ตลอดจนผู้บุกรุกที่น่าสงสัยอื่นๆ สำหรับเจ้าหน้าที่ระดับรากหญ้าอย่างฌอน นี่เป็นเพียงแนวทางปฏิบัติทั่วไป",
  str_mission_desc_4204040_long = "เมื่อ Axelia, Yingel และ Sean ทักทายกัน คุณจะรู้ว่าทั้งสามคนมีประวัติเหมือนกัน พวกเขาอธิบายว่าพวกเขาเป็น \"บัณฑิต\" จากโครงการฟอสเฟอรัส ซึ่งเป็นโครงการที่นำโดยสภาวิทยาศาสตร์เพื่อจุดประสงค์ในการเลี้ยงดูเด็ก ๆ ให้เป็นสุดยอดทหาร แม้ว่าทั้งสามคนจะเติบโตขึ้นมากตั้งแต่นั้นมา แต่พวกเขาก็ยังหยอกล้อและหัวเราะกันเหมือนตอนเด็กๆ",
  str_mission_desc_4204050_long = "แม้จะมีความขัดแย้งที่รุนแรงรอบ ๆ ทไวไลท์ แต่ผู้อยู่อาศัยก็กังวลมากขึ้นกับการหลบภัยจากภัยธรรมชาติที่ใกล้เข้ามา แสงออโรราเหนือศีรษะคุกคามจนเกินการควบคุม และทุกคนต่างพยายามหาที่กำบังเพื่อฝ่าฟันพายุพลังงานที่กำลังจะมาถึง Eclipsites ใช้ประโยชน์จากความตื่นตระหนกอย่างกว้างขวางและเริ่มโจมตีตามอำเภอใจ เมื่อคุณตัดสินใจเข้าร่วมการต่อสู้และช่วยชาวเมือง คุณจะพบว่ากำลังเสริมได้มาถึงแล้วในรูปแบบของกองทหารของ Lumopolis: อัศวินไอรอนธอร์น",
  str_mission_desc_4204060_long = "เมื่อเผชิญกับโอกาสที่ดูเหมือนจะผ่านไม่ได้ อัศวินไอรอนธอร์นสามารถทำลายอันดับของ Eclipsites ได้อย่างง่ายดายก่อนที่จะพุ่งเข้าใส่พวกเขา หลังจากได้เห็นความสามารถในการต่อสู้อันน่าทึ่งของ Leo คุณตัดสินใจช่วยอัศวินป้องกัน Eclipsites ที่เหลืออยู่ ในขณะที่กระแสน้ำดูเหมือนจะเปลี่ยนไปในทางที่คุณชอบ อย่างไรก็ตาม ภัยคุกคามใหม่ที่ร้ายกาจยิ่งกว่าก็ปรากฏขึ้น...",
  str_mission_desc_4204070_long = "ระลอกใหม่ของ Eclipsites เข้าสู่สนามรบ และเหล่าอัศวิน Lumo ไม่สามารถป้องกันการโจมตีได้ในขณะเดียวกันก็ปกป้องชาวเมืองไปด้วย คุณแยกตัวออกจากแนวหน้าเพื่อปกป้องพวกเขา แต่ Eclipsites ก็โจมตีอย่างไม่ลดละ เมื่อคุณถึงขีดจำกัด เด็กสาวคนหนึ่งก็ปรากฏตัวขึ้นท่ามกลางการต่อสู้ ด้วยแสงศักดิ์สิทธิ์ที่เจิดจ้า เธอปัดเป่าทุกสุริยุปราคาในบริเวณใกล้เคียงทันที เมื่อชาวเมืองปลอดภัย คุณจะเข้าร่วมการต่อสู้อีกครั้งโดยไม่ลังเลและคว้าชัยชนะในท้ายที่สุด หลังจากนั้นหญิงสาวลึกลับที่รู้จักกันในชื่อ Joselyne เชิญคุณไปทานอาหารเย็นกับเธอใน Twilight",
  str_mission_desc_4204085_long = "Joselyne พาคุณไปที่ร้านอาหารใน Twilight และเล่าให้คุณฟังเพิ่มเติมเกี่ยวกับเมืองนี้: ประวัติศาสตร์ ปัญหา และที่สำคัญที่สุด ความเกี่ยวข้องกับ Colossus โบราณที่สาบสูญ หลังจากทานอาหารเสร็จ คุณจะกลับไปหานักวิจัยอิลลูมินา ซึ่งจะช่วยฟื้นฟูสติของโซรอซอย่างเต็มที่ หากเป็นเพียงชั่วคราว ในช่วงเวลาสั้น ๆ นั้น Soroz นำคุณไปยังสถานที่แห่งหนึ่ง: Undercity ที่อยู่ลึกเข้าไปใน Dark Zone ที่ซึ่ง Colossus โบราณอยู่เฉยๆ...",
  str_mission_desc_4204090_long = "คุณตัดสินใจที่จะเดินทางไปยังสถานที่ที่ Soroz กล่าวถึงและได้รับการสนับสนุนจากทั้ง Illumina และ Lumopolis รวมถึง Joselyne ที่เพิ่งรู้จัก หลังจากได้เห็นพลังที่น่าประทับใจของพวกเขาในสนามรบ การคุกคามของ Eclipsites ดูจะน่ากลัวน้อยกว่าเมื่อก่อนมาก",
  str_mission_desc_4204115_long = "คุณและพรรคพวกของคุณดำดิ่งลึกเข้าไปในซากปรักหักพัง ระวัง Eclipsites จำนวนมหาศาลที่สัญจรไปมาในพื้นที่ ปาร์ตี้ของคุณดำเนินการด้วยความระมัดระวังสูงสุด อย่างไรก็ตาม ในเวลานี้ ฌอนตัดสินใจที่จะท้าทาย Axelia เพื่อประลองความแข็งแกร่ง: ใครก็ตามที่เอาชนะ Eclipsites ได้มากที่สุดจะเป็นผู้ชนะ และทั้งคู่แข็งแกร่งกว่ากัน",
  str_mission_desc_4204120_long = "ในที่สุดคุณก็มาถึง Bridge of the Colossus และเริ่มค้นหาโมดูลที่จำเป็น อย่างไรก็ตาม เมื่อพบมัน คุณพบว่าโมดูลได้หลอมรวมตัวเองเข้ากับยักษ์ใหญ่มานานแล้ว การเอาออกด้วยกำลังมีแต่จะสร้างความเสียหายมากขึ้นเท่านั้น จากนั้น Axelia ก็ก้าวเข้ามาและมอบอุปกรณ์ที่สามารถคัดลอกข้อมูลของโมดูลให้คุณได้ แต่บอกว่าจะใช้เวลาสักครู่...",
  str_mission_desc_4204130_long = "หลังจากป้องกัน Eclipsites ที่กำลังโจมตี ในที่สุดอุปกรณ์ของ Axelia ก็คัดลอกข้อมูลของโมดูลเสร็จสิ้น เมื่อกลุ่มของคุณตัดสินใจอพยพ Colossus ก็เริ่มส่งเสียงดังก้องอย่างรุนแรง มันกำลังจะออกจากการควบคุมหรือไม่? ในการทำให้ยักษ์ใหญ่สงบลงและปกป้องการตั้งถิ่นฐานใกล้กับซากปรักหักพัง คุณตัดสินใจที่จะเริ่มต้นการเชื่อมโยงความคิดกับยักษ์ใหญ่...",
  str_mission_desc_4204140_long = "ปรากฏว่าเสียงกึกก้องไม่ได้เกิดจากยักษ์ใหญ่... แล้วมันรับผิดชอบอะไรล่ะ? หลังจากสร้าง Mind Link กับ Colossus แล้ว คุณพบว่ามี Eclipsites จำนวนมากรวมตัวกันอยู่ด้านนอก ภายในแถวของพวกเขา คุณจะรู้สึกถึงการมีอยู่ของสิ่งที่ทรงพลังอย่างยิ่ง...",
  str_mission_desc_4204155_long = "คุณกลับไปที่ Twilight พร้อมกับ Axelia และคนอื่นๆ ลากจูงและกล่าวคำอำลา เมื่อข้อมูลอันมีค่าของคุณอยู่ในมือ คุณจะเดินทางกลับไปยังอิลลูมินา เวลาเท่านั้นที่จะบอกได้ว่าข้อมูลนี้จะช่วยฟื้นฟู Soroz ได้จริงหรือไม่ สิ่งที่คุณทำได้คือรอ ในขณะนี้เองที่คุณได้รับคำเชิญจากทองเหลืองชั้นนำของ Illumina คำขอให้เดินทางไปยัง Undercity ที่ซ่อนอยู่ซึ่งยังมี Chord Link อีกแห่งอยู่...",
  str_mission_desc_4205015_long = "จับ Vice เป็นตัวประกัน Forsakin บังคับให้คุณไปกับเธอ ดูเหมือนว่าหลังจากที่ Chord Link แอบเปิดโดย Illumina ด้วยความตั้งใจที่จะกรอกข้อมูลการทดลองผ่าน Vice\nในอีกด้านหนึ่ง การต่อสู้ใน Twilight ทวีความรุนแรงขึ้นเมื่อ Leo ส่งสัญญาณความทุกข์ใจไปยังทั้ง Lumopolis และ Illumina",
  str_mission_desc_4205020_long = "เพื่อทำการทดลองให้สำเร็จ Forsakin บังคับให้คุณต่อสู้กับทหาร Illumina และถ่วงเวลาพวกเขา แค่หวังว่าเธอจะรักษาสัญญาว่าจะไม่ฆ่าใคร",
  str_mission_desc_4205030_long = "คุณมาถึงที่หมายแล้ว Forsakin ผู้คุ้นเคยกับสภาพแวดล้อมเรียกว่าสถาบัน X ที่เธอสร้างขึ้น! ก่อนที่คุณจะคิดไปไกลกว่านี้ เธอต้องการให้ Vice เปิด Chord Link! จะเกิดอะไรขึ้น?",
  str_mission_desc_4205040_long = "Forsakin ไม่พอใจกับผลลัพธ์ของการทำงานของ Chord Link คุณและ Vice พยายามซุ่มโจมตีเธอ เพียงเพื่อให้เธอเรียกกลุ่ม Eclipsites มาต่อต้านคุณ",
  str_mission_desc_4205041_long = "—",
  str_mission_desc_4205050_long = "คุณไม่เหมาะกับ Forsakin และต่อสู้ไม่มีประโยชน์ Helios ปรากฏตัวถัดจาก Forsakin และแยกคุณออกจาก Vice บังคับให้คุณทั้งคู่ปฏิบัติตาม\nในขณะเดียวกัน Ulysses เรียก Yingel เข้าร่วมการประชุมลับและมอบหมายภารกิจพิเศษให้เธอ",
  str_mission_desc_4205065_long = "ใน Twilight ที่ถูกปิดล้อม ลีโอไม่ได้รับความช่วยเหลือแต่ได้รับคำเชิญให้เข้าร่วมการฝึกร่วมทางทหาร ซึ่งเขาใช้โอกาสนี้เพื่อเตือนโลกถึงภัยคุกคามจาก Dark Zone\nในขณะเดียวกัน Illumina และ Lumopolis ก็เริ่มเตรียมตัวสำหรับการฝึก ราวกับว่าผู้บงการที่อยู่เบื้องหลังมันสาบานว่าจะดูให้จบ...",
  str_mission_desc_4205070_long = "หลังจากที่ Forsakin แยกคุณและ Vice แล้ว คุณไม่มีทางติดต่อเธอได้อีกนอกจากผู้สื่อสาร คุณไปต่อเมื่อ Forsakin เริ่มขุดค้นข้อมูลในเอกสารสำคัญเกี่ยวกับโปรแกรม Phospherus\nในขณะเดียวกัน Yingel ได้พบกับเจ้าหน้าที่ข่าวกรอง Anatoli ด้วยคำสั่งลับ ดูเหมือนว่าเป้าหมายของเธอคือสถาบัน X เช่นกัน",
  str_mission_desc_4205080_long = "เพื่อตามหาคุณและ Vice ที่หายไป รวมถึงค้นหาว่าอะไรคือเบื้องหลังการฝึกร่วม Carleen มาถึง Illumina เพื่อพูดคุยกับ Gronru ซึ่งชี้ให้เธอไปที่ Institute X ซึ่งเธอได้พบกับ Yingel โดยบังเอิญและได้รู้เกี่ยวกับวิกฤตที่นี่",
  str_mission_desc_4205090_long = "ฟอร์ซาคินพยายามหาข้อมูลเพิ่มเติมเกี่ยวกับโปรแกรมฟอสเฟอรัสแต่ไปกระตุ้นการป้องกันโดยไม่ตั้งใจ หลังจากเอาชนะพวกมันได้ เธอเปลี่ยนคีย์เวิร์ดและเข้าถึงไฟล์ได้สำเร็จ",
  str_mission_desc_4205100_long = "คุณขาดการติดต่อกับ Vice เมื่ออุปกรณ์สื่อสารหมดไฟ แต่ก่อนที่จะให้ Yingel และคนอื่นๆ มีเวลาค้นหาตำแหน่งที่แน่นอนของ Vice\nแต่เมื่อ Yingel เข้ามาใกล้ เธอก็ตระหนักได้ว่าศัตรูที่แข็งแกร่งกำลังปกป้อง Vice—Helios",
  str_mission_desc_4205101_long = "—",
  str_mission_desc_4205110_long = "อิงเกลและเฮลิออสถูกขังอยู่ในการต่อสู้ที่ดุเดือด เธอยังตระหนักดีว่า Forsakin น่าจะสัมผัสได้ถึงการต่อสู้\nในขณะเดียวกัน Carleen ก็มาหาคุณ เธอพยายามเอาชนะ Forsakin และพาคุณออกไปจากที่นี่ เพียงเพื่อที่จะจมปลักอยู่ในการต่อสู้ที่ยากเย็นแสนเข็ญของเธอเอง\nสายตาสิ้นหวังของ Helios ที่ร่วมมือกับ Forsakin กระตุ้นให้ Yingel เผา Chord Link อย่างกล้าหาญ...",
  str_mission_desc_4205120_long = "สิ่งที่เรียกว่านรกกลายเป็นเพียงภาพลวงตาของ Yingel แต่มันเปลี่ยนกระแสของการต่อสู้และทำให้ฝ่ายของคุณได้เปรียบ Yingel ยังพยายามโน้มน้าว Forsakin ว่า Reinhardt ไม่เคยทอดทิ้งเธอหลังจากไฟไหม้ห้องทดลอง และการแก้แค้นที่เธอเรียกว่าถูกเข้าใจผิดตั้งแต่ต้น",
  str_mission_desc_4205130_long = "ปฏิเสธที่จะยอมแพ้ Forsakin ตัดพลังงานในห้องแล็บและปิดประตู ซื้อตัวเธอเองและเวลา Chord Link เพื่ออัปเกรด Helios ต่อไป\nในขณะเดียวกัน แรงจูงใจของ Ulysses ก็ค่อยๆ ปรากฏขึ้น ในขณะที่เขาสนใจอย่างมากในผลการทดลองของ Forsakin...",
  str_mission_desc_4205140_long = "ในที่สุด Forsakin ได้รวมการปรับปรุงที่แตกต่างกันสามอย่างบน Helios ทำให้รูปลักษณ์ของเขาเปลี่ยนแปลงไปอย่างมาก หลังจากการต่อสู้สิ้นสุดลง เฮลิออสก็ฟื้นคืนสติได้อย่างน่าประหลาดใจ แม้ว่าจะมีความทรงจำที่ค่อนข้างกระจัดกระจายก็ตาม\nในขณะเดียวกัน Wrath และ Reinhardt มาถึงเพื่อเผชิญหน้ากับ Forsakin แต่เธอก็ยังหนีไปได้",
  str_mission_desc_4205155_long = "ไม่มีใครสามารถพบ Forsakin ในสถาบัน X และคาดเดาว่าเธออาจซ่อนตัวอยู่ใกล้ Gannon ในขณะเดียวกัน การฝึกร่วมทางทหารก็เริ่มต้นขึ้นตามที่วางแผนไว้ในเมืองนั้น โดยผู้แทนจากมหาอำนาจต่างๆ จะประชุมกันและต่อสู้เพื่อชิงตำแหน่งกองทัพที่ดีที่สุด\nแต่ภายใต้เงาของ Gannon นั้น Forsakin และ Helios แฝงตัวอยู่...",
  str_mission_desc_4206015_long = "แบบฝึกหัดเริ่มต้นขึ้น โดยดึงทีม Gannon จาก Lumopolis, Illumina และ Twilight มาร่วมทีม ตลอดจนทั้งสามคนและทีมลึกลับอื่นๆ\nวิเวียนแจ้งให้คุณทราบถึงกฎและระบุว่าผู้ชนะจะได้รับเกียรติให้ท้าทายจอมพล\nในขณะเดียวกันที่มุมหนึ่งของเมือง Forsakin กำลังรอสมาชิก Eclipse เพื่อช่วยเหลือเธอและ Helios",
  str_mission_desc_4206020_long = "อันดับแรกคือ Battle Simulator ที่คุ้นเคยเพื่อให้ทุกคนหวนนึกถึงแคมเปญที่ยากลำบากในอดีต หลายคนต้องพ่ายแพ้ต่ออัตราต่อรองที่ท่วมท้น ยกเว้นทีมของลีโอจาก Twilight ซึ่งได้รับชัยชนะอย่างน่าอัศจรรย์",
  str_mission_desc_4206030_long = "ถัดไปเป็นส่วนของห้องเรียนซึ่งคุณสามารถแลกเปลี่ยนหน่วยกิตของหลักสูตรตามเกรดและประสิทธิภาพสำหรับวัสดุสิ้นเปลือง ดังนั้นภายใต้การดูแลของ Wrath ทุกคนจึงเจาะลึกถึงศิลปะแห่งการ \"ทะเลาะวิวาท\"...",
  str_mission_desc_4206040_long = "การฝึกที่ไม่เป็นอันตรายถูกก่อวินาศกรรมและเกือบจบลงด้วยหายนะ เดาว่าการแข่งขันระหว่างทีมนั้นไม่เป็นมิตรเอาเสียเลย\nในขณะเดียวกัน ด้วยประสิทธิภาพที่โดดเด่นของ Leo และ Yingel คุณจึงตัดสินใจสมัครเข้าร่วมเซสชันจำลองพิเศษ แต่มีคนเอาจริงเอาจังเช่นกัน...",
  str_mission_desc_4206041_long = "—",
  str_mission_desc_4206050_long = "สำหรับ Eclipsites ที่มาจากที่ไหนก็ไม่รู้ใน Gannon ลีโอและ Zhao อยู่เหนืออำนาจของพวกเขาเพื่อสั่งให้ทหารอิลลูมินาแก้ปัญหา ราธไม่ได้กระตือรือร้นมากนักหลังจากค้นพบ แต่ก็ชื่นชมพรสวรรค์ของลีโอ\nในการสนทนา Wrath ยังได้รับรู้ถึงความสิ้นหวังใน Twilight และตระหนักว่าพวกระดับสูงดูเหมือนจะเซ็นเซอร์ข่าว...",
  str_mission_desc_4206060_long = "บทเรียนจะก้าวไปสู่การต่อสู้จริงในการฝึกซ้อมร่วมทางทหาร ภายใต้คำแนะนำของคุณ ทุกคนเอาชนะศัตรูทั้งหมดผ่านพันธมิตรชั่วคราว นำเหตุการณ์ไปสู่ส่วนสุดท้าย: ยึดธง\nทุกคนเริ่มใช้เครดิตหลักสูตรที่ได้รับกับอุปกรณ์และอุปกรณ์ประกอบฉากเพื่อรอการต่อสู้ครั้งใหญ่เพื่อชิงธงใน Undercity",
  str_mission_desc_4206070_long = "เข้าสู่ Undercity เพื่อค้นหาธง คุณ Carleen และ Vice กำลังวางกลยุทธ์เมื่อทีมลึกลับจาก Umbraton วิ่งเข้ามาพร้อมกับกลุ่ม Eclipsites ที่ลากจูง...",
  str_mission_desc_4206080_long = "ในที่สุดคุณก็ยุติ Eclipsites หลังจากการต่อสู้ที่วุ่นวาย แต่ทีม Umbraton ที่เริ่มต้นปัญหาปฏิเสธที่จะเข้าสู่ Undercity กับคุณราวกับว่าพวกเขามีภารกิจของตัวเอง\nในขณะเดียวกัน สองทีมที่แข็งแกร่งที่สุด ได้แก่ Team Leo และ Team Yingel เริ่มต่อสู้กันเองที่ไหนสักแห่ง",
  str_mission_desc_4206090_long = "เมื่อทีมลึกลับดูเหมือนจะบงการเส้นทางของคุณ คุณก็พบกับสัตว์ประหลาดแมงมุมที่อันตราย\nหลังจากการต่อสู้ที่ยากลำบาก คุณรีบไปที่ตำแหน่งที่มีธงเพียงเพื่อจะพบการต่อสู้ระหว่าง Team Leo และ Team Yingel โดยผู้ชนะคือ Team Yingel",
  str_mission_desc_4206105_long = "ทีมเลโอพอใจกับการเป็นรองชนะเลิศเนื่องจากพวกเขาทำเพื่อแลกกับการที่อิลลูมินาส่งกำลังเสริมไปยังทไวไลท์\nในขณะเดียวกัน Ulysses ก็ขยายแผนการเพื่อบรรลุเป้าหมายผ่านการกระทำของ Forsakin ใน Gannon\nYingel ได้รับข่าวการบุกรุกของ Eclipsite ในเมือง คุณ ลีโอ และคนอื่นๆ ตัดสินใจที่จะช่วยเธอในเรื่องนี้",
  str_mission_desc_4206110_long = "ในการประลองกับจอมพล Axelia แสดงระดับพลังที่ผิดปกติและความปรารถนาที่จะตาย ไรน์ฮาร์ทยังสัมผัสได้ถึงบางอย่างที่แปลกประหลาดในการแข่งขันนิทรรศการ\nในขณะเดียวกัน การเบี่ยงเบนความสนใจของ Eclipsites ทำให้ Forsakin และ Helios สามารถหลบหนี Gannon ผ่านทางลับได้",
  str_mission_desc_4206120_long = "Eclipsites ใน Gannon ดูเหมือนจะดึงความสนใจของคุณโดยตั้งใจ แต่คุณไม่สามารถหยุดและปล่อยให้พวกมันวิ่งอาละวาดได้เช่นกัน ในระหว่างนี้ คุณยังสัมผัสได้ถึงการมีอยู่ของฟิเจอรัลด์เดอะเจตภูต\nในที่เกิดเหตุ ความผิดฐานใกล้ฆ่าตัวตายของ Axelia เริ่มสร้างความกังวลให้กับ Reinhardt",
  str_mission_desc_4206121_long = "—",
  str_mission_desc_4206130_long = "Reinhardt ยอมรับเพียงเพื่อหยุด Axelia จากการโจมตีฆ่าตัวตายของเธอเอง แต่นั่นก็ตกอยู่ในแผนของ Ulysses เช่นกัน\nคุณ, Leo, Yingel และคนอื่นๆ รีบไปที่ตำแหน่งของ Wraith ซึ่งเป็นที่เก็บเมนเฟรมของ Guardian One!\nในขณะเดียวกัน Forsakin และ Helios ไปที่จุดนัดพบเพียงเพื่อพบว่า Esien ได้ส่งทหารไปที่นั่นแล้ว พวกเขาตระหนักดีว่า Eclipse ได้สร้างมันขึ้นมา",
  str_mission_desc_4206140_long = "ถูก Eclipse ผลักไสให้เป็นเพียงเบี้ยบูชายัญ ฟิเจอรัลด์พ่ายแพ้อย่างยับเยินและถูกควบคุมตัว แต่เจตภูตอีกตัวที่ไม่รู้จักได้นำหัวใจของ Guardian One ไปใช้ และไม่มีใครทำอะไรได้\nสำหรับ Forsakin เธอหนีไปได้เมื่อ Helios อยู่ข้างหลังเพื่อปกปิดการหลบหนี\nกลับมาที่เวที Ulysses เปิดเผยว่าคณะกรรมการพบหลักฐานว่า Reinhardt กักขัง Forsakin ไว้ในที่พักของเธอ ทำให้ Grand Marshal ถูกจับกุมต่อหน้าทุกคน",
  str_mission_desc_4206155_long = "และนี่คือสิ่งที่ยืนอยู่ แม้ว่าคุณจะพบว่า Reinhardt ถูกปลดออกจากหน้าที่ซึ่งเป็นยาเม็ดที่กลืนได้ยาก แต่ก็ยังเป็นความจริง\nสำหรับ Ulysses เขาพอใจกับการสกัดกั้นผลการทดลองของ Forsakin มาก แต่ Wraith ที่ฉวยโอกาสขโมย Guardian One ทำให้การดำเนินการนี้แย่ลง\nจะเกิดอะไรขึ้นกับ Reinhardt? และศัตรูที่ไม่รู้จักแฝงตัวอยู่ในเงามืด?",
  str_mission_desc_4207015_long = "สหพันธ์อิลลูมินากำลังดำเนินการพิจารณาคดีของไรน์ฮาร์ตครั้งที่สามในข้อกล่าวหาขายชาติ ขณะที่คุณและ Vice รออยู่ด้านนอกห้องสอบถาม ข่าวสารในที่สุดก็ถึงหูคุณว่า Reinhardt ถูกถอดยศจอมพลและถูกลงโทษจำคุก ข่าวนี้ทำให้คุณทั้งสองสงสัยเกี่ยวกับความเป็นไปได้ของการเปลี่ยนแปลงที่มหัศจรรย์ในอนาคต",
  str_mission_desc_4207020_long = "ขณะที่คุณรู้สึกสับสนเกี่ยวกับสถานการณ์ปัจจุบัน วิเวียน วิ่งเข้ามาอย่างรีบเร่ง เรียกไวซ์ไปด้านหนึ่ง พูดถึงภารกิจที่ต้องดำเนินการทันทีที่อยู่ในมือเธอ คุณมาถึงสถานีอิลลูมินาและค้นพบว่าคนที่ไปกับไวซ์ในภารกิจนี้ไม่ใช่แค่คารอนเท่านั้น แต่ยังมีผู้แข่งขันอีกสามคนที่อ้างว่ามาจากอัมบราตัน พอได้ยินเรื่องนี้ ความไม่สบายเริ่มคลุมเครือใจของคุณ",
  str_mission_desc_4207030_long = "ขณะที่คุณหลงใหลในความคิดเกี่ยวกับใครที่จะนำทางอิลลูมินาไปข้างหน้า รายการออกอากาศข่าวเฉียบพลันประกาศว่า วราธได้รับแต่งตั้งเป็นจอมทัพใหม่ ในขณะที่คุณตกใจ ลีโอรีบเข้ามาแจ้งคุณเกี่ยวกับการบุกรุกของอิคลิพไซท์ใน Twilight เขาขอร้องให้คุณขับยักษ์ใหญ่และติดตามเขาไปให้ความช่วยเหลือ ในระหว่างนี้ ภายในห้องปฏิบัติการบางแห่งในอิลลูมินา มีแผนลับที่กำลังดำเนินอยู่เงียบๆ",
  str_mission_desc_4207031_long = "—",
  str_mission_desc_4207040_long = "ในสายตาของผู้มอง จอมทัพใหม่วราธนำกำลังทหารใหม่มาประชุมที่สถานี พร้อมกับเครื่องจักรสงครามชั้นนำ Engine VII แม้ว่าวราธจะยืนอยู่ในตำแหน่งที่เธอปรารถนามานานแล้ว แต่เธอรู้ดีว่าเธอยังไม่เคยชนะไรน์ฮาร์ตอย่างเปิดเผยและยุติธรรม คิดถึงเรื่องนี้ ความทรงจำเกี่ยวกับความท้าทายในอดีตของเธอต่อไรน์ฮาร์ตเริ่มคลื่นคลายในหัวใจของวราธ",
  str_mission_desc_4207050_long = "ด้วยความเข้าใจในพลังของตัวเองอย่างชัดเจน วราธได้คาดการณ์ผลของการคัดเลือกจอมทัพคนสุดท้ายมานานแล้ว ถึงแม้ว่าจะได้ขึ้นแทนไรน์ฮาร์ต แต่ก็ไม่ใช่เส้นทางที่เธอหวังหา ดังนั้น วราธตั้งใจอย่างแน่วแน่ในการรักษาตำแหน่งจอมทัพชั่วคราวจนกว่าไรน์ฮาร์ตจะกลับมา โดยที่เธอตั้งใจที่จะทำหน้าที่ให้ดีที่สุดในทุกๆ ด้านที่เป็นไปได้",
  str_mission_desc_4207060_long = "ด้วยแรงจูงใจและการส่งเสริมจากโจเซลีน ทหารกล้าหาญยืนหยัดต่อต้านการโจมตีของอิคลิพไซท์ ในระหว่างนั้น คุณและเลโอก็สุดท้ายถึงที่เข้าของทไวไลท์ แม้ว่าเลโอจะไม่ยินยอมให้คุณเข้าร่วมการสู้รบที่ร้ายแรงนี้ แต่บทบาทที่เป็นประโยชน์ของคุณในฐานะ Caelestite และคนขับของ Colossus ทำให้เขาเชื่อมั่นในทางตรงกันข้าม ในที่สุด ก็คือการส่งกำลังเสริมของคุณที่ทำให้ความมั่นใจของทหารกลับคืนมาในสนามรบ",
  str_mission_desc_4207075_long = "วางแผนที่จะขอความช่วยเสริมจากลูโมโพลิส จ้าวไม่ได้ตั้งใจกลับกลายเป็นเชลยของลูกน้องของอีสต์วาน ในศาลราชวงศ์ของลูโมโพลิส ชวาตส์ถือคำขอความช่วยเสริมหลายคำในมือของเขา ในขณะที่ขุนนางอภิปรายว่าควรส่งกำลังเสริมหรือไม่ ในที่สุด ชวาตส์สั่งให้กองทัพสนับสนุนรักษาตำแหน่งของพวกเขาที่ป้อมลูโม โดยไม่มีส่วนเกี่ยวข้องในการปฏิบัติการทางทหารของอิลลูมินา",
  str_mission_desc_4207080_long = "ด้วยการโจมตีของ Eclipsites ที่มากขึ้นเรื่อย ๆ แม้กระทั่ง Leo ที่มีประสบการณ์ก็ยังรู้สึกว่าตัวเองหมดแรง ในขณะที่กลุ่มกำลังพิจารณาว่าควรจะโจมตีอย่างกล้าหาญหรือถอยหลังต่อไป Wrath นำกองทัพอิลลูมินาเข้าสู่สนามรบ ทำให้กระแสการต่อสู้ใน Twilight เปลี่ยนไป",
  str_mission_desc_4207090_long = "ฟอร์เซคินรู้สึกตัวเกี่ยวกับ \"เมล็ดพันธุ์\" ที่ถูกฝังในทหารเหล่านี้ เพื่อเพิ่มความสามารถในการต่อสู้ แม้ว่าเธอจะไม่พอใจในการปล้นค้นหาทดลองของเธอโดยยูลิสซ์ แต่เธอยังรู้ว่าอิคลิพไซท์ที่น่ากลัวที่ถูกนำมาโดยเจตภูตนั้นเป็นประโยชน์ต่อการกระทำต่อไปของเธอ ในระหว่างนี้ คุณสัมผัสถึงคลื่นของพลังความมืดที่ยิ่งใหญ่ แต่ยังไม่รู้ตัวว่าฝันร้ายในทวีลประสาทเพียงเริ่มต้นเท่านั้น",
  str_mission_desc_4207100_long = "ในการตรวจสอบความผิดปกติในหมู่ทหารอิลลูมินา ลีโอและวราธมีการอภิปรายอย่างร้อนแรงเกี่ยวกับปัญหาภายในกองกำลังของเธอ หวังว่าจะค้นหาสาเหตุของความผิดปกติของทหาร วราธขอความช่วยเสียงจากคุณ ขณะที่คุณสืบสวนเข้าในสติของทหารที่ถูกคอร์รัปต์และค้นพบหนองที่ไม่มีขีดจำกัดภายใน ในโลกความเป็นจริง Twilight ก็ยังทุกข์ทรมานจากการบุกรุกอย่างต่อเนื่องของโคลนและอิคลิพไซท์",
  str_mission_desc_4207110_long = "เห็นชะตากรรมของทหารที่ถูกอิคลิพไซท์กัดกินในระหว่างการทดลอง Yingel สุดท้ายก็รู้ถึงจุดประสงค์ที่แท้จริงของ \"โปรแกรมฟอสเฟอรัส\": พวกเขานำ \"เมล็ดพันธุ์\" มาปลูกฝังในออโรเรียนและคัดเลือกทหารที่โดดเด่นผ่านการต่อสู้กับอิคลิพไซท์! ในขณะที่ Yingel พยายามหยุดการทดลอง หัวข้อที่ควบคุมไม่อยู่กลับโจมตีอย่างรุนแรงต่อพวกเขาอย่างไม่คาดคิด",
  str_mission_desc_4207111_long = "—",
  str_mission_desc_4207120_long = "หลังจากตรวจสอบสนามรบอย่างละเอียดคู่กับวราธ คุณค่อย ๆ ค้นพบเหตุผลว่าทำไมทหารอิลลูมินาถึงเปราะบางต่ออิทธิพลของโคลน ในระหว่างนั้น โคลนก็ยืดออกไปในทวีป Twilight อย่างต่อเนื่อง ขณะที่ศัตรูที่ทำหน้าที่เป็นศูนย์ควบคุมสั่งการยึดโอกาสเพื่อเริ่มโจมตี ด้วยวราธที่เดินหน้าหนุน คุณนำทีมในสนามรบ แต่โดนโคลนจับได้โดยไม่ได้ตั้งใจ",
  str_mission_desc_4207130_long = "ขณะที่คุณสังเกตุวราธกระโจนเข้าไปในกลุ่มอิคลิพไซท์อย่างเสี่ยงความตาย คุณตัดสินใจใช้ Force Boost เพื่อเข้าสู่จิตใจของเธอและปลุกเธอจากภายใน จากห้องประชุมที่ถูกปิดบังไปยังเมือง Gannon ที่เปียกฝน และภาพของไรน์ฮาร์ตนอนบนโต๊ะผ่าตัด... ในที่สุด ในหมู่ภาพที่เปลี่ยนแปลงอยู่ตลอดเวลาของความตื่นตัวของวราธ คุณสามารถหาตำแหน่งของเธอได้",
  str_mission_desc_4207140_long = "คุณและวราธสุดท้ายก็ค้นพบกองกำลัง Illumina ที่หายไป ด้วยคำพูดของวราธ Axelia ค่อยๆ กู้คืนความคล่องแคล่วของเธอ หลังจากการค้นหาอย่างละเอียดของคุณ ศัตรูหลักปรากฏตัวขึ้น ในขณะที่ Leo มาถึง นำ Expedition Knights มาด้วย อย่างไรก็ตาม เพื่อปกป้องทีมของเธอจากอิทธิพลคอร์รัปของโคลน วราธตัดสินใจที่จะเผชิญหน้ากับศัตรูคนนี้ด้วยตัวเอง",
  str_mission_desc_4207155_long = "เมื่อไม่กี่วันที่ผ่านมา วราธได้รับข้อความจากคณะกรรมการ - สืบทอดจากไรน์ฮาร์ตเป็นจอมทัพแห่งอิลลูมินาคนใหม่ โดยมีเงื่อนไขในการเข้าร่วม \"โปรแกรมฟอสเฟอรัส\" ด้วยความปรารถนาที่เกือบจะสามารถจับต้องได้ วราธตระหนักว่าความทะเยอทะยานของเธอกำลังเปลี่ยนแปลงอย่างเงียบ ๆ ในที่สุดเธอตกลงกับเงื่อนไขของคณะกรรมการ แต่ก็มีแผนที่ก่อตั้งอย่างลับ ๆ ในหัวใจของเธอด้วย",
  str_mission_desc_4208015_long = "นอกเส้นขอบของ Twilight การเปลี่ยนแปลงก็กำลังเกิดขึ้น ขณะที่ทีมสืบสวนของ Illumina ติดตามหาแกนกลุ่ม \"Guardian One\" พวกเขาได้พบข้อมูลสำคัญที่ไม่คาดคิด ในขณะเดียวกัน ภายในราชวังของ Lumopolis ไฮแดรด ที่ทำหน้าที่เป็นผู้สื่อข่าวของอีสต์วาน ได้พูดคุยกับชวาตส์เกี่ยวกับเรื่องการส่งกำลังเสริม ในที่สุด ชวาตส์ตัดสินใจ - คุ้มครอง Aurorians ด้วยวิธีของ Lumopolis",
  str_mission_desc_4208020_long = "ภายใต้อิทธิพลของโคลน, บางทหารอิลลูมินากลายพันธุ์เป็นอิคลิพไซท์ โจมตีเพื่อนร่วมทีมของตัวเอง ตัวเลโอจึงจัดการอพยพของผู้ใต้บังคับบัญชาของวราธในขณะที่เขาจัดการกับทหารที่กลายพันธุ์ด้วยตัวเอง ในความสับสนที่เกิดขึ้น วราธที่บาดเจ็บกลับมาสู้ในสนามรบ พยายามนำคนที่ตกอยู่ในความเสียคลั่งกลับมา",
  str_mission_desc_4208030_long = "ด้วยทรัพยากรการแพทย์ที่จำกัดใน Twilight คุณตัดสินใจแบ่งเป็นสามทีมเพื่อดำเนินการช่วยเหลือ วราธยังคงตามหากลุ่มทหารอิลลูมินาที่สูญหาย ในขณะที่ Joselyne คุ้มครองทหารที่บาดเจ็บอย่างรุนแรงเพื่อหาที่อยู่อาศัยใน Lumo Stronghold ส่วนคุณ ลีโอเสนอให้คุณขับ Colossus และพาผู้อพยพไปสู่ความปลอดภัยใน Eraveil แต่คุณยืนยันในการตั้งตัว ยืนยันที่จะอยู่เพื่ออดทนความยากลำบากกับทุกคน",
  str_mission_desc_4208040_long = "คารอนดูเหมือนจะคาดการณ์ถึงการมาถึงของวิกตอเรียได้ แต่ก็ตกใจเมื่อรู้ว่าการต่อต้านที่แปลกประหลาดที่พบไม่ใช่สิ่งที่วิกตอเรียทำ ไวซ์เมื่อทราบถึงสถานการณ์ใน Twilight ก็เป็นห่วงความปลอดภัยของคุณ และได้รับความช่วยเสริมจากวิกตอเรียในการเดินทางไปยังเมือง อย่างไรก็ตาม หลังจากพักค้างคืนสั้น ๆ กำลังแปลกประหลาดก็โจมตีรถไฟของคารอนอีกครั้ง",
  str_mission_desc_4208041_long = "—",
  str_mission_desc_4208050_long = "ความสำคัญจากไบเบิลโชกเลือดทำให้ทุกคนสับสน วิกตอเรียจึงรู้สึกเร็วว่า \"โดเมน\" ของ Wraith ได้หุ้มรถไฟ ในการหลุดพ้นจาก \"โดเมน\" นี้ คารอนต่อสู้กับ Wraith ตัวต่อตัว ในขณะที่วิกตอเรียและสามคนในผู้ใต้บังคับของเธอดำเนินพิธีบูชาเพื่อหลุดพ้นจากความยุ่งยาก ในขณะที่วายซ์ทะลุวงกัน ความสามารถของคุณในการรับรู้จิตใจจับความเคลื่อนไหวของหัวใจวายซ์ได้",
  str_mission_desc_4208060_long = "คุณตั้งใจจะช่วยทหารคนนี้ด้วยพลังจิตของคุณ แต่ถึงแม้คุณจะเห็นประสบการณ์ก่อนการต่อสู้ของทหารคนนี้ คุณก็ยังไม่สามารถหยุดความบ้าคลั่งของเขาได้ ในขณะนี้ ทหารกำลังเริ่มเป็นคลั่งต่อเนื่องกัน ในขณะที่ลีโอเสนอว่าเขาจะไปสังหารพวกเขา วราธ ซึ่งยืนหยัดในฐานะจอมทัพ ตัดสินใจที่จะให้ความสิ้นสุดที่เมตตาให้กับเพื่อนร่วมทีมที่ถูกทรมานเกินกว่าจะวัดค่าได้",
  str_mission_desc_4208070_long = "เมื่อประตูเมืองเปิดออก แสงสว่างที่แปลกปลอมทำให้ทุกคนถวายความเคารพ นักบวช Joselyne รู้จักสิ่งนี้เป็นความสว่างที่เป็นที่น่าเคารพของ \"นางฟ้า\" ของวัดลูโมโพลิส \"นางฟ้า\" ดูแลบาดแผลของผู้บาดเจ็บ ยอมรับความพยายามของ Joselyne และตัดสินใจที่จะเดินทางไปกับเธอไปยัง Twilight เพื่อช่วยเหลือคนที่ยังต้องการความช่วยเสียง",
  str_mission_desc_4208080_long = "ฟอร์เซคินขำขัน กล่าวว่าทหารที่ตกเป็นเหยื่อเหล่านี้คือ \"งานศิลป์\" ที่เธอสร้างขึ้นอย่างประณีตเพื่อให้ทุกคนได้ชม ความโกรธของวราธลุกโชน แต่เธอก็ไม่กระทำอย่างประมาท ระมัดระวังต่ออิทธิพลของ \"เมล็ดพันธุ์\" ที่มีต่อร่างกายของเธอ ในทางของเธอในการเรียกคืนทหารที่ฟอร์เซคินได้นำไป Axelia เป็นพยานต่อการแสดงที่น่าขนลุกของทหารที่กันและกัน ในช่วงเวลาที่ยิ่งใหญ่ที่สุด ทีมขยายกำลังถึงที่เกิดเหตุ",
  str_mission_desc_4208095_long = "วิเวียนรู้จักแอนาโทลีเป็นแหล่งสัญญาณและนึกถึงวิธีที่เขาขัดขวางเธอในภารกิจที่คุกอิลลูมินา พบว่าแอนาโทลีใช้วิธีนี้เพื่อทดสอบความมุ่งมั่นของวิเวียน และในที่สุดเขาตัดสินใจที่จะช่วยเธอในการสำเร็จแผนของเธอ แต่เมื่อทั้งสองคิดว่าแผนกำลังดำเนินไปอย่างราบรื่น สัญญาณถูกตัดอย่างกะทันหัน",
  str_mission_desc_4208100_long = "การต่อสู้ใน Twilight ทำให้ลีโอมั่นใจในการเป็นผู้คุ้มครองเมือง โจเซลีนรู้สึกลึกซึ้งในความขัดแย้งระหว่างกลุ่ม และแสดงให้ \"นักบุญ\" รู้ถึงความมุ่งมั่นในการสร้างที่หลบภัยให้ชาว Aurorian ภายในโบสถ์ อย่างไรก็ตาม สงครามยังไม่จบ หลังจากที่ทราบว่ากองกำลังหลายกลุ่มได้รวมตัวเข้ามาในการป้องกันของ Illumina คุณทุกคนตัดสินใจที่จะรวมกันและเดินหน้าสู่เส้นป้องกัน",
  str_mission_desc_4208110_long = "ในขณะที่ทหารต่อสู้อย่างรุนแรง บาร์ตันและฮิอิโระมาเสริมกำลัง หลังจากแบ่งปันสถานการณ์ปัจจุบัน ชาโรนายังคงวิตกเกี่ยวกับความปลอดภัยของวราธ อย่างไรก็ตาม การปรากฏตัวของไรน์ฮาร์ตทันทีทำให้ทุกคนมั่นใจขึ้น ดังที่พบว่า แผนของวราธไม่เพียงแต่ป้องกันทไวไลท์ แต่ยังช่วยกู้ไรน์ฮาร์ตและรวมกลุ่มกันที่แนวหน้า",
  str_mission_desc_4208111_long = "—",
  str_mission_desc_4208120_long = "วราธตั้งใจนำกองทหารของเธอไปล้อมกองทัพ Eclipsite แต่ \"Engine VII\" ภายใต้อิทธิพลของ Darkflow กลายเป็นอุปสรรคที่ไม่คาดคิด ในขณะที่ Axelia ติดลำบากในการต่อสู้กับ \"Engine VII\" Reinhardt ได้มาช่วยเสียเวลา ด้วยความพอใจและความสบายใจที่ผสมกัน Reinhardt มองวราธกลับไปร่วมกองหน้า แต่วราธยอมเดินออกข้างๆอย่างเต็มใจ ให้ Reinhardt ควบคุมการสั่งการในการต่อสู้ที่กำลังดำเนินไป",
  str_mission_desc_4208130_long = "—",
  str_mission_desc_4208140_long = "ก่อนที่จะออกไป Forsakin ควบคุมทั้งทหาร Illumina และ Engine VII โจมตีทหาร Illumina อย่างรุนแรงในครั้งสุดท้าย ไรน์ฮาร์ตรับรู้ถึงการมีส่วนร่วมของฟอร์เซคินในการดำเนินการของ Eclipse และพยายามประนีประนอมกับเธอ โดยขอให้เธอปฏิบัติตามความปรารถนาของตัวเอง อย่างไรก็ตาม การตอบสนองของฟอร์เซคินทำให้ความขัดแย้งระหว่างพวกเขาที่เคยเป็นพี่น้องเพิ่มขึ้น ไม่นานหลังจากนั้น ทหาร Lumopolis และ Twilight ร่วมต่อสู้ในเส้นป้องกัน",
  str_mission_desc_4208155_long = "ฝนตกลงบนแนวหน้าอิลลูมินา หลังจากหยุด โคลนก็หายไป เผยถึงพื้นดินภายใต้แสงอาทิตย์อีกครั้ง วราธมองไปที่ความสูญเสียที่หนักแน่น ตัวเองรู้สึกผิดที่ไม่สามารถปกป้อง Twilight และทหารของเธอในฐานะจอมทัพ อย่างไรก็ตาม ไรน์ฮาร์ตชื่นชมการปฏิบัติงานของเธอ ยืนยันว่าความมุ่งมั่นที่ไม่สั่นสะเทือนของเธอคือสิ่งที่ปกป้อง Twilight และทหาร อย่างไรก็ตาม การต่อสู้ที่แท้จริงยังคงคาดหวั่นอยู่ข้างหน้า",
  str_mission_limit_4000001 = "ผู้นำทาง ไปต่อสู้แล้วเคลียร์ด่านกับ<color=#e8d9bb>ไวซ์</color>เลย!",
  str_mission_limit_4000002 = "จัดสมาชิกในทีมของคุณแล้วสู้ร่วมกับ<color=#e8d9bb>ไวซ์</color>เลย!",
  str_mission_limit_4000003 = "คุณควรจัดเพื่อนร่วมทีมคนอื่น ๆ เพื่อเคลียร์ด่านกับ<color=#e8d9bb>ไวซ์</color> ลองดูสิ!",
  str_mission_leader_limit_4000002 = "ผู้นำทาง <color=#e8d9bb>ไวซ์</color>เป็นผู้เข้าชิงตำแหน่งกัปตันที่เหมาะที่สุด!",
  str_mission_desc_4209015 = "—",
  str_mission_desc_4209020 = "ฝันร้ายที่สดใสทำให้คุณตื่นขึ้นอย่างกะทันหันหลายวันต่อมาในช่วงเวลาที่ยังเช้ามาก...",
  str_mission_desc_4209030 = "ในความตื่นเต้นของคุณ คุณได้เริ่มต้นโดยไม่ได้รับเวลาหรือสถานที่สำหรับการนัดพบ และสถานการณ์ใน Illumina ดูไม่ดีในตอนนี้...",
  str_mission_desc_4209040 = "คุณตกใจกับการเดบิวต์ของอัลกอล แต่ยิ่งตกใจมากขึ้นเมื่อเห็น \"สัตว์เลี้ยง\" พยาธิของเธอ",
  str_mission_desc_4209050 = "คุณและวิเวียนรู้สึกประทับใจเมื่อ Algol พาคุณไปที่สำนักงานของเธอ จริง ๆ แล้วมีสถานที่แบบนี้อยู่ในอิลลูมินาเหรอ?",
  str_mission_desc_4209065 = "—",
  str_mission_desc_4209070 = "อิคลิพไซท์หลายตัวปรากฏขึ้นอย่างกะทันหันในอิลลูมินาเทคปาร์คและขวางทางของคุณ...",
  str_mission_desc_4209080 = "อิคลิพไซท์ยังคงหลั่งไหลออกมาจากตึกอย่างต่อเนื่อง แต่สิ่งที่ทำให้คุณตกใจมากกว่านั้นคือ Ulysses กำลังเดินตามหลังพวกเขาอย่างเงียบ ๆ...",
  str_mission_desc_4209081 = "ดูเหมือนว่าทหารอิลลูมินาเหล่านี้จะผ่านการเปลี่ยนแปลงที่น่ากลัวในเวลากลางคืน ระวังด้วยนะ!",
  str_mission_desc_4209090 = "คำพูดของยูลิสซิสเต็มไปด้วยคำขู่เคือง และคุณได้เห็นอันตรายในภาพลวงตาของเขา...",
  str_mission_desc_4209100 = "ในการประชุมทบทวนครั้งที่ห้า ยูลิสซิสรำลึกถึงบทหนึ่งจากอดีตของเขา...",
  str_mission_desc_4209115 = "—",
  str_mission_desc_4209120 = "โปรโตไทป์ที่ถูกปิดทิ้งไว้นานนั้นมีความเกี่ยวข้องกับยูลิสซิสอย่างไร?",
  str_mission_desc_4209121 = "อิคลิพไซท์พวกนี้มีความสามารถในการโต้ตอบที่ถูกเพิ่มขึ้นอย่างมาก ดังนั้นพยายามอย่าไปสู้รับใกล้กับพวกมัน",
  str_mission_desc_4209130 = "ในความตื่นเต้นของการอ่านบันทึกของวิศวกร Ulysses ได้หลงทางไปจากการวิจัยของตัวเองมากขึ้นและมากขึ้น...",
  str_mission_desc_4209140 = "ผ่านคอมพิวเตอร์ของ Ulysses คุณได้ค้นพบว่าเขาเข้าถึงคลังสินค้าที่ไม่ได้บันทึกไว้โดยไม่ได้รับอนุญาต...",
  str_mission_desc_4209150 = "หลังจากที่คุณเอาชนะทหารพลังเหนือมนุษย์แล้ว คุณเริ่มเหลี่ยมลงที่ต้นแบบที่ยังคงทำงานอยู่...",
  str_mission_desc_4210015 = "—",
  str_mission_desc_4210020 = "ยูลิสซิสยืนยันว่าการทดลองของเขาเป็นประโยชน์ต่ออิลลูมินาและพยายามพิสูจน์ว่าเขาถูกต้อง แต่สิ่งนั้นทำให้แอนาโทลีที่อยู่ใกล้ๆ รู้สึกไม่พอใจอย่างรุนแรง...",
  str_mission_desc_4210030 = "เพื่อเร่งการถอดรหัส คุณได้เชื่อมต่อจิตใจกับ Bool เพื่อค้นหาเบาะแส",
  str_mission_desc_4210045 = "—",
  str_mission_desc_4210050 = "เมื่ออัลกอลคิดว่าคุณได้รวบรวมข้อมูลเพียงพอแล้ว ความไม่แน่นอนก็ปรากฏขึ้น...",
  str_mission_desc_4210060 = "จะเกิดอะไรขึ้นเมื่อคุณเข้าสู่ระบบของผู้พิทักษ์?",
  str_mission_desc_4210070 = "เมื่อวิกฤตเกิดขึ้น, บางคนตื่นตระหนก, และบางคนก็ไม่สามารถรอได้...",
  str_mission_desc_4210071 = "สถานที่ที่กลุ่มทหารอิลลูมินากำลังดำเนินภารกิจลับดูเหมือนจะเป็นลูโมโพลิส...",
  str_mission_desc_4210080 = "ยูลิสซิสถึงที่โกดังศูนย์และรีบเปิดของขวัญที่เขาได้เตรียมไว้มานานหลายปี...",
  str_mission_desc_4210090 = "ที่เสียงนั้น คุณทันทีรู้สึกเข้าใจความหมายของความฝันที่สดใสแต่ก็เหมือนภาพลวงตา...",
  str_mission_desc_4210100 = "คุณรีบออกไปโดยไม่คิดอะไรเลย แต่พบว่าคุณได้สูญเสียการรับรู้ของมัน...",
  str_mission_desc_4210110 = "การล้อเลียนของศัตรูทำให้คุณโกรธแค้น คุณจะตอบสนองอย่างไรในฐานะเคเลสไทต์ล่ะ?",
  str_mission_desc_4210120 = "วิศวกรได้แสดงสัญญาณที่จะถอยหลัง แต่หัวใจของระบบป้องกัน Gannon ยังหายไป ตอนนี้เราควรทำอย่างไร?",
  str_mission_desc_4210121 = "ทหารเหล่าซูเปอร์ที่ทรงพลังสามารถเพิ่มพลังให้กับศัตรูของคุณทั้งหมด ดังนั้นคุณต้องหยุดพวกเขา!",
  str_mission_desc_4210130 = "หลังจากที่แกนกลางถูกแทนที่ คุณได้ยินยูลิสซิสพูดภาษาต่างประเทศที่แปลกหน้า...",
  str_mission_desc_4210140 = "ก่อนที่การมองเห็นของเขาจะล่มสลาย, เขารำลึกถึงการสนทนาในช่วงสงครามที่สถานพยาบาล...",
  str_mission_desc_4210155 = "—",
  str_mission_desc_4209015_long = "หลังจากการสั่นสะเทือนอย่างรุนแรง คุณและทหารของ Twilight กลับสู่อีราเวลหลังจากหายหน้าหายตาไปนาน ผู้รอดชีวิตจาก Twilight เตรียมอาหารเลี้ยงอย่างอุดมสมบูรณ์ หลังจากที่คุณทานอาหารจนอิ่ม คุณเริ่มการสนทนากับโซรอซ",
  str_mission_desc_4209020_long = "ความกังวลเกี่ยวกับความปลอดภัยของไวซ์ ทำให้คุณนั่งอยู่ที่เครื่องควบคุมโคลอสซัสเป็นวันวัน รอคอยข่าวสารจากไรน์ฮาร์ตอย่างวิตกกังวล แล้วทันทีคุณก็ได้รับข้อความที่คุณรอคอยมานาน",
  str_mission_desc_4209030_long = "เนื่องจากปัญหาที่เกิดขึ้นกับระบบป้องกันของอิลลูมินา คุณถูกอิคลิพไซท์โจมตีในสนามบริการของอิลลูมินา ในขณะนั้น บุคคลที่เชิญคุณมาที่นี่ปรากฏตัวอย่างที่ไม่คาดคิด",
  str_mission_desc_4209040_long = "Algol แนะนำเพื่อนร่วมงานของเธอ Bool และอธิบายเหตุผลที่เชิญคุณมาที่ Illumina เธอแนะนำว่าไฟล์ข้อมูลของ Soroz อาจจะมีคำใบ้เกี่ยวกับ Core ของ Guardian One ซึ่งหวังว่าจะนำไปสู่การค้นพบที่ตั้งของ Vice",
  str_mission_desc_4209050_long = "ขณะที่คุณกำลังดื่มกาแฟที่ Guardian One ทำขึ้นมา วิเวียนดูเหมือนจะผ่อนคลายลงสักที หลังจากพักผ่อนสั้น ๆ ทุกคนก็เริ่มทำงาน แต่น่าเสียดายที่ไม่มีใครบอกคุณเรื่องวิธีการสื่อสารที่ไม่ธรรมดาและค่อนข้างเจ็บปวดของ Bool...",
  str_mission_desc_4209065_long = "หลังจากวิเคราะห์อย่างยาวนาน คุณค้นพบพิกัดที่กระพริบอยู่ภายในไฟล์ข้อมูลของโซรอซ ซึ่งดูเหมือนจะเก่ากว่าอีราเวลมาก อัลกอลสงสัยว่าแหล่งกำเนิดของโคลอสซัสอยู่ลึกลงไปใน Dark Zone ดังนั้นคุณจึงเข้าหานักฟิสิกส์ผู้เชี่ยวชาญของอิลลูมินาเพื่อสอบถามเกี่ยวกับพิกัดเหล่านั้น",
  str_mission_desc_4209070_long = "หลังจากที่คุณเอาชนะอิคลิพไซท์ คุณค้นพบว่าร่างกายของพวกเขามีลักษณะคล้ายคลึงกับออโรเรียนอย่างน่าตกใจ บาร์ตัน ที่กำลังตรวจตรา Illumina Tech Park เข้าร่วมกลุ่มของคุณและทุกคนสันนิษฐานว่าอิคลิพไซท์เหล่านี้ส่วนใหญ่เป็นทดลองสัตว์ที่หนีออกจากห้องปฏิบัติการของ Ulysses ด้วยความช่วยเหลือจาก Alglol คุณเดินทางไปยังห้องปฏิบัติการและเตรียมตัวที่จะถามคำถามนักวิจัย",
  str_mission_desc_4209080_long = "ยูลิสซิสไม่ปฏิเสธว่าอิคลิพไซท์ที่มาก่อนหน้านี้ได้หนีออกจากห้องปฏิบัติการของเขา และเขาเชิญคุณเข้าไปลึกขึ้นในอาคารเพื่อสิ่งที่เขาเรียกว่า \"การทดลองเล็ก ๆ\" คุณสงสัยเกี่ยวกับจำนวนสิ่งที่เขากล่าวถึง ดังนั้นคุณยอมรับคำเชิญของเขา",
  str_mission_desc_4209090_long = "หลังจากเห็นภาพที่อันตรายและน่ากลัว Ulysses ถูกนำออกไปโดยเจ้าหน้าที่ของสหพันธรัฐ Illumina ในขณะที่คุณยังไม่แน่ใจว่าเขาทำไมถึงแสดงสิ่งเหล่านี้ให้คุณเห็น แต่ดูเหมือนว่าแสงแดดกำลังเริ่มส่องสว่างในเมือง Gannon อีกครั้ง คุณและเพื่อน ๆ หวังว่าวิกฤตนี้จะสิ้นสุดลงเร็ว ๆ นี้",
  str_mission_desc_4209100_long = "หลายปีที่ผ่านมา ยูลิสซีส์คนเยาว์ทุ่มเทตัวเองในการปรับปรุงการรอดชีวิตของ Aurorian ในขณะที่ทำการวิจัยเกี่ยวกับเทคโนโลยีวิศวกรรมพันธุกรรมของ Illumina ซึ่งถูกส่งผ่านมาจากหลายศตวรรษที่แล้ว เขาค้นพบชื่อที่ถูกลืมไปโดยประวัติศาสตร์ การเห็นชื่อนี้ทำให้เขารู้สึกเต็มไปด้วยความหวังสำหรับอนาคตของ Aurorian ทั้งหมด",
  str_mission_desc_4209115_long = "Joyce บอกคุณเกี่ยวกับหินลอยที่ปรากฏขึ้นที่พิกัดภายใน Dark Zone และข้อมูลนั้นตรงกับภาพที่คุณเห็นในสมองของ Ulysses จึงทำให้ Algol ตระหนักว่า Ulysses ได้ซ่อนงานที่เขาทำกับต้นแบบของ Guardian ตลอดเวลา",
  str_mission_desc_4209120_long = "ในการพิจารณาคดี ทุกคนตกใจเมื่อรู้ว่ายูลิซซีส์ได้วิจัยเครื่องจักรโบราณอย่างลับ ๆ ขณะที่ความจริงเหล่านี้กำลังเปิดเผย คุณและ Algol ยังคงค้นหาต้นแบบในเมือง Gannon แต่ที่อันตรายเท่ากับเครื่องจักรนี้คือทหารเอลีทที่ซ่อนตัวในแชโดว์และปล่อย Darkflow",
  str_mission_desc_4209130_long = "ยูลิสซิสเสนอการทดลองที่กล้าหาญ ซึ่งทำให้ Robby ซึ่งเป็นเพื่อนร่วมงานคนเก่าของเขาสงสัยเขา ใครคือ \"วิศวกร\" และเขาได้โน้มน้าวยูลิสซิสให้ดำเนินการที่รุนแรงกับการวิจัยของเขาอย่างไร?",
  str_mission_desc_4209140_long = "เมื่อ Algol มาถึง Warehouse Zero ซึ่งเธอรู้สึกตื่นเต้นเมื่อค้นพบว่าต้นแบบของ Guardian ยังคงทำงานได้ แต่น่าเสียดายที่การบุกรุกของคุณยังทำให้เกิดการโจมตีจากทหารเหล่าซูเปอร์ที่ถูกเก็บไว้ในอาคาร",
  str_mission_desc_4209150_long = "เมื่อ Algol เห็นต้นแบบครั้งแรก ซึ่งเธอยังเป็นนักเรียนของ Ulysses สิ่งที่น่าประหลาดใจยิ่งขึ้นคือ Ulysses ยังคงใช้งานอยู่ในคลังส่วนตัวของเขาแม้ว่าจะถูกปิดบังคับเพื่อเหตุผลด้านความปลอดภัย ขณะที่คุณและเพื่อน ๆ ของคุณพยายามเข้าถึงต้นแบบลึกลับนี้ คุณรู้สึกเต็มไปด้วยความรอคอยและความหวาดกลัว",
  str_mission_desc_4210015_long = "คุณถูกทึงใจโดยฟังก์ชันและความเร็วในการประมวลผลของ Bool ที่น่าประทับใจ ขณะที่ Algol กำลังเล่าถึงเรื่องราววันแรกที่พวกเขาพบกัน คุณค่อยๆ รู้สึกตระหนักถึงความหมายที่ซ่อนอยู่เบื้องหลังป้ายบนร่างกายของเธอ",
  str_mission_desc_4210020_long = "มันเปิดเผยว่าจุดประสงค์ที่แท้จริงของ Undercity 80 คือการคัดเลือกผู้สมัครสำหรับโครงการ Artificial Sun ในขณะที่กำลังรวบรวมข้อมูลที่สำคัญเกี่ยวกับโครงการ ทีมสำรวจของ Anatoli ถูกกำจัดอย่างสิ้นเชิง ไม่ยอมรับการสูญเสียทีมของเขา Anatoli ต้องการให้คณะกรรมการลองและลงโทษ Ulysses สำหรับอาชญากรรมของเขา",
  str_mission_desc_4210030_long = "หลังจากใช้พลังจิตกับ Bool คุณรู้สึกว่าโดนทะลุด้วยคลื่นข้อมูลและลำดับที่ไม่มีที่สิ้นสุด ในการดึงข้อมูลที่คุณต้องการ อัลกอลได้แบ่งปันเทคนิคของเธอในการจัดการกับภาระงานที่ยากลำบากกับคุณ คุณลองอีกครั้ง และดูเหมือนว่าคุณจะสามารถรับข้อมูลที่มีประโยชน์ได้บ้าง",
  str_mission_desc_4210045_long = "เช่นเดียวกับ Yingel และ Axelia, ฌอนก็เป็นผลิตภัณฑ์จากโครงการฟอสเฟอรัส อย่างไรก็ตาม ฌอนถูกพิจารณาว่าเป็นความล้มเหลวในตอนแรกของโครงการ และถูกส่งไปยัง Twilight หลังจากที่รู้ถึงที่มาของเขา ฌอนเริ่มสงสัยว่าจุดประสงค์ในชีวิตของเขาคือการกลายเป็นอาวุธสงครามที่ไม่เห็นแก่ใจ",
  str_mission_desc_4210050_long = "การเชื่อมต่อกับจิตใจของ Bool ทำให้คุณรู้สึกเวียนศีรษะและไม่สบายไม่น้อย เอลกอลกำหนดให้คุณมีเวลาสองนาที ในระหว่างนั้นคุณได้รับคำสั่งให้เรียกคืนข้อมูลเท่าที่คุณสามารถทำได้ ขอบคุณที่คุณออกมาโดยไม่ได้รับความเสียหายมาก แต่มีบางสิ่งที่ดูเหมือนจะก่อให้เกิดปัญหากับ Algol สิ่งใดที่สามารถทำลายอารยธรรมที่มีความสามารถในการสร้างเทคโนโลยีนี้ลงได้บ้าง?",
  str_mission_desc_4210060_long = "คุณตกใจกับสถานการณ์ในเมือง Gannon อัลกอลยังคงค้นหาทางเข้าสู่ระบบอย่างสิ้นหวัง แต่กลับค้นพบว่าการสั่นสะเทือนที่รุนแรงนั้นเกิดจากศัตรูที่มองไม่เห็น การพิจารณาคดีของยูลิสซีสก็ถูกหยุดชั่วคราว เมื่อคุณคิดว่าวิกฤตการณ์จะจบลงแล้ว ศัตรูที่มองไม่เห็นก็ปรากฏบนหน้าจอของต้นแบบ...",
  str_mission_desc_4210070_long = "Ulysses อ้างว่าเขาได้คิดวิธีการเอาชนะศัตรูแล้ว และ Belisaria ยอมรับการดำเนินการของเขา แก้ไขการเตรียมตัวก่อนหน้า และเร่งการเริ่มต้นแผนการที่ได้ทำไว้ล่วงหน้าอย่างเร่งด่วน",
  str_mission_desc_4210080_long = "ทหารเหนือมนุษย์ที่เก็บไว้ในคลังสินค้าเป็นผลลัพธ์ของการวิจัยทางวิทยาศาสตร์ของยูลิสซีส์หลายปี พร้อมกับเป็นของขวัญที่เขามอบให้กับวิศวกร แต่สิ่งที่ทำให้ยูลิสซีส์ประหลาดใจคือ วิศวกรได้รับการควบคุมทหารเหนือมนุษย์เหล่านี้และใช้พวกเขาโจมตีเพื่อนบ้านอิลลูมินาทั้งหมด",
  str_mission_desc_4210090_long = "\"กลับบ้านไป Caelestite\" ข้อความลึกลับสำหรับหลายคน แต่เป็นข้อความที่คุณได้ยินในฝันมากมายครั้ง ใครเขา? เขาต้องการให้คุณไปที่ไหนอย่างแน่นอน? ขณะที่คุณกำลังสูญเสียสติที่สุด คุณได้รับข่าวทันท่วงทีว่า Soroz ถูกเปิดใช้งานแล้ว",
  str_mission_desc_4210100_long = "ชั่วโมงของการจากลาได้มาถึงที่สุดแล้ว แต่คุณไม่รู้สึกอะไรเลย ด้วยเหตุผลที่ไม่ทราบ คุณได้เล่นสถานการณ์นี้ในใจของคุณมากกว่าที่คุณนับได้ อันตรายตามมาใกล้เคียงในความเศร้าของคุณ แต่เพื่อนเล็ก ๆ ของคุณได้ขั้นมาและป้องกันการโจมตีที่สามารถทำให้คุณเสียชีวิตได้",
  str_mission_desc_4210110_long = "ภายในจิตใต้สำนึกของฟิเจอรัลด์ คุณเหมือนจะเห็นกระบวนการที่วิศวกรทำให้คนอื่นเป็นทาส ไม่เพียงเท่านั้น คุณยังเห็นความทรงจำที่ห่างไกลของห้วงนรกที่กว้างใหญ่และโครงกระดูกของโคลอสซัสที่เกิดขึ้นจากในจิตใต้สำนึกของฟิเจอรัลด์...",
  str_mission_desc_4210120_long = "เพื่อป้องกันเมืองแกนน่อน พันธมิตรของ Algol, Guardian One, สละ Core ของตนเองอย่างเด็ดขาด ในระหว่างนั้น เพื่อที่จะได้รับพลังคำนวณที่เพียงพอสำหรับการเปลี่ยนแปลง ไรน์ฮาร์ต ดำเนินการโปรโตคอลฉุกเฉินเพื่อเปลี่ยนแปลงพลังการประมวลผลของทุกคอมพิวเตอร์ในเมืองแกนน่อนไปยังที่ตั้งของพวกเขา",
  str_mission_desc_4210130_long = "Algol ค้นพบว่าภาษาคอมพิวเตอร์ที่ระบบการ์เดียนใช้มีความเกี่ยวข้องกับภาษาที่อิคลิพไซท์ใช้อย่างไรก็ตาม Ulysses ภูมิใจว่าเขาสามารถเปลี่ยนแปลงโลกทั้งหมด แต่คุณไม่ปรารถนาที่จะอยู่ในโลกที่ถูกเขาปรับเปลี่ยน",
  str_mission_desc_4210140_long = "อะไรที่น่าเศร้ากว่า การสูญเสียความศรัทธาหรือความไม่สามารถที่จะทำให้ความฝันเป็นจริง? ยูลิสซิสถามคุณคำถามสุดท้ายก่อนล้มลงที่เท้าของคุณ ไม่สามารถตอบได้อีกต่อไป นี่อาจเป็นครั้งสุดท้ายที่เขาคิดคำถามนี้",
  str_mission_desc_4210155_long = "หลังจากหมดสติไปสามวัน คุณตื่นขึ้นแล้วพบว่าวิกฤติที่เมืองแกนน่อนได้ผ่านไปแล้ว แต่สิ่งที่รอคอยคุณตอนนี้คือภารกิจสำรวจที่อันตรายยิ่งขึ้น คุณรำลึกถึงวิธีที่คุณถูกช่วยในขณะที่ใช้พลังของคุณ และสงสัยว่าจะมีใครในพื้นที่ที่สว่างเป็นที่หนึ่งที่หนึ่งสามารถให้คำแนะนำที่คุณกำลังมองหาได้หรือไม่",
  str_mission_desc_4301015 = "—",
  str_mission_desc_4301020 = "ภายในศูนย์ควบคุมชั่วคราวที่กว้างใหญ่ คณะกรรมการการสำรวจ Astra ร่วมกันจัดการประชุมที่สำคัญเกี่ยวกับอนาคตของชาว Aurorian",
  str_mission_desc_4301030 = "เนื่องจากพบกับกระแสลมที่รุนแรงอย่างไม่คาดคิด ยานของคุณตกลงบนที่ราบที่เต็มไปด้วยหิมะที่ขอบของนอร์ธแลนด์...",
  str_mission_desc_4301040 = "คุณตามรอยเลือด แต่มันหายไปอย่างลึกลับในทาง...",
  str_mission_desc_4301055 = "ขณะที่เบธเลเฮมพาคุณออกจากถ้ำ นางรู้สึกถึงสนามพลังที่ไม่ธรรมดาภายใน และคิดค้นวิธีการเพื่อเอาชนะความลำบากที่เกิดขึ้น",
  str_mission_desc_4301060 = "ในสถานการณ์วิกฤติที่นอร์ธแลนด์ตอนนี้ เบธเลเฮมกำลังขอคำปรึกษาจากพี่เสือโคร่งหิมะเกี่ยวกับการปลุกสัญญาณพื้นฐานเพื่อทำความสะอาดสิ่งสกปรกที่กำลังประคองที่ทุ่งหิมะ",
  str_mission_desc_4301070 = "—",
  str_mission_desc_4301080 = "เมื่อหิมะหนักปกคลุมพื้นที่ชายแดน คุณได้มาถึงเผ่าที่เติบโตขึ้นมาของเทียเร่ และเริ่มต้นการค้นหาต้นสนที่สาม",
  str_mission_desc_4301090 = "ด้วยการตื่นขึ้นของ Primal Haven ประภาคารใหม่ถูกสร้างขึ้น เทียเร่ จับหอกทรงพลังของเธอ แล้ววิ่งออกไปอีกครั้ง สู่อิคลิพไซท์ที่ยิ่งใหญ่นั้น",
  str_mission_desc_4301105 = "—",
  str_mission_desc_4301015_long = "เบธเลเฮมรำลึกถึงการปะทุกันในอดีต หลายปีที่แล้ว ขณะที่เธอกำลังตรวจตรารป่าสนที่ขอบแดนเหนือ เธอได้มีการปะทุกันสั้น ๆ กับสัตว์จิ้งจอกหิมะที่อาศัยอยู่ที่นั่น เทียเร่ เด็กที่ถูกสัตว์จิ้งจอกหิมะเลี้ยงดู ตอนนี้ทำหน้าที่เป็นการ์ดของเบธเลเฮม อาศัยอยู่ในพระราชวังฤดูหนาว แต่ยังคงกังวลเกี่ยวกับเผ่าพันธุ์ของเธอ",
  str_mission_desc_4301020_long = "ผู้แทนจาก Lumopolis, Umbraton และ Courier Union ได้แลกเปลี่ยนความคิดเห็นเกี่ยวกับการเตรียมการสำรวจของสหพันธ์อิลลูมินา หลังจากการประชุม ไรน์ฮาร์ตได้มอบหมายให้คุณและคาร์ลีนไปตรวจสอบสถานะการจัดตั้งที่ย่อยของ Northland",
  str_mission_desc_4301030_long = "โดยไม่ได้ตั้งใจ คุณได้เดินเข้าสู่เขตของเผ่าชายแดน และสับสนเมื่อเห็นรอยเลือดที่กระจายอยู่ทั่วพื้นดิน การตอบสนองที่ตามมาจากเทียเร่และหมาป่าหิมะแสดงให้เห็นว่าเรื่องราวไม่ได้ง่ายดายเท่าที่ดู แม้ว่าพวกเขาจะต่อต้านอย่างรุนแรง คุณก็ยังตัดสินใจที่จะตามพวกเขาเพื่อดูว่าเกิดอะไรขึ้นจริงๆ",
  str_mission_desc_4301040_long = "เอาชนะความกลัวภายในของคุณ คุณใช้ความสามารถทางจิตของคุณเพื่อตามหาเทียเร่และหมาป่าหิมะ ในที่สุดคุณสะดุดพบกับรอยเลือดที่พวกเขาทิ้งไว้และไม่คาดคิดว่าสองเพื่อนของคุณจากเรดีเซล เวรนช์ก็ได้มาถึงนอร์ทแลนด์ด้วยเครื่องบินของคุณ แต่คุณยังไม่รู้ว่า อิคลิพไซท์ที่มีพลังมากกำลังซ่อนตัวอยู่ใกล้ๆ",
  str_mission_desc_4301055_long = "ในการนำโดยพี่เลี้ยงหมาป่าหิมะ คุณได้มายังแท่นบูชาโบราณที่ถูกปกป้องโดยเผ่าหมาป่าหิมะมาหลายรุ่น ที่นี่ พลังคุณส resonates กับพลังงานโบราณ และตำนานของ \"สามต้นสน\" เริ่มเปิดเผย สิ่งที่ทำให้พี่เลี้ยงหมาป่าหิมะประหลาดใจคือ ไม่ใช่ครอบครัวราชวงศ์ที่เอาต้นสนไป แต่ต้นสนเลือกครอบครัวราชวงศ์และยอมรับควีน",
  str_mission_desc_4301060_long = "ขณะที่เบธเลเฮมต้องเผชิญหน้ากับอิคลิพไซท์คนเดียว คุณตัดสินใจที่จะค้นหาสองต้นสนอื่นๆ ร่วมกับเทียเร่ โนวิโอแนะนำว่าเนื่องจากพลังงานโบราณได้สลายลง ในการค้นหาต้นสน คุณต้องหาคำใบ้จากตำนานของ \"สามต้นสน\"",
  str_mission_desc_4301070_long = "พาคุณไปบนไหล่ของเธอ ทีเอร์วิ่งอย่างรวดเร็วไปทั่วทาง ในที่สุดก็ได้มาถึงศาลแห่งนอร์ธแลนด์ เมื่อคุณรู้สึกสับสน คำพูดของซาร์ยานำทางให้คุณ มันเป็นไปได้ว่าต้นสนที่ถูกตัดลงได้ถูกประดิษฐ์เป็นราชินีของบัลลังก์ แต่เนื่องจากราชินีไม่เคยนั่งบนมัน บัลลังก์จึงเก็บฝุ่นอยู่ในศาล",
  str_mission_desc_4301080_long = "เมื่อคุณสืบค้นความทรงจำของเทียเร่ คุณพบความขัดแย้งระหว่างพี่ชายจิ้งจอกหิมะและยายของเทียเร่เกี่ยวกับอนาคตของเธอ ประเด็นสำคัญของการทะเลาะวิวาทนั้นคือเรื่องของแผ่นหินที่เป็นสัญลักษณ์ของความมั่นคงที่โบราณ ซึ่งเป็นสิ่งที่คุณกำลังมองหา ด้วยความช่วยเหลือจากเจ้าจิ๋วและรอย คุณสามารถหาต้นสนที่สามและนำมันกลับมาที่แท่นบูชาได้",
  str_mission_desc_4301090_long = "การโจมตีของเทียเร่ปลุกความทรงจำในอิคลิพไซท์ ทำให้เขานึกถึงอดีตและเหตุผลที่อยู่เบื้องหลังการฝึกฝนอย่างหากินของเขา ขณะที่เขาพยายามทำการโจมตีครั้งสุดท้ายต่อคุณ คุณไล่เขาออกจากนอร์ทแลนด์ ภายใต้แสงของ Beacon คุณก้าวขึ้นอีกขั้นที่สำคัญ โดยเดินทางเข้าสู่ Dark Zone.",
  str_mission_desc_4301105_long = "แม้ว่า Eclipsite ยังไม่ถูกเอาชนะและด่านของ Northland ยังคงอยู่ในระหว่างการก่อสร้าง คุณตัดสินใจที่จะทำการเตรียมพร้อมอย่างใจจดใจจ่อและดำเนินการสำรวจ Dark Zone ในเวลาที่จะมาถึง ก่อนที่คุณจะออกเดินทาง คุณได้รับ Lumina Ore ที่ถูกส่งมาโดยเทียเร่ ที่อยู่ใกล้ๆ เบธเลเฮมรู้สึกสงบและพอใจที่รู้ว่าผู้คุ้มครอง Northland คือเทียเร่ ได้เติบโตและเจริญเติบโตขึ้น",
